window.TS = {"built":"2026-11-16","topics":[{"id":"udlaendinge","name":"Udlændinge & integration","lo":"Mest åben","hi":"Strammest"},{"id":"oekonomi","name":"Økonomi & skat","lo":"Mest omfordeling","hi":"Lavest skat"},{"id":"arbejdsmarked","name":"Arbejdsmarked & pension","lo":"Mest tryghed","hi":"Mest arbejdsudbud"},{"id":"velfaerd","name":"Velfærd & ældre","lo":"Mest offentligt","hi":"Mest frit valg"},{"id":"sundhed","name":"Sundhed","lo":"Kun offentligt","hi":"Mest privat"},{"id":"klima","name":"Klima & energi","lo":"Hurtigst omstilling","hi":"Pris og forbruger først"},{"id":"natur_landbrug","name":"Natur & landbrug","lo":"Hårdest krav","hi":"Færrest krav"},{"id":"eu","name":"EU","lo":"Mest EU-positiv","hi":"Mest EU-skeptisk"},{"id":"forsvar","name":"Forsvar & sikkerhed","lo":"Mindst oprustning","hi":"Mest oprustning"},{"id":"ret","name":"Ret & straf","lo":"Forebyggelse","hi":"Hårdest straffe"},{"id":"bolig","name":"Bolig","lo":"Mest regulering","hi":"Mest marked"},{"id":"uddannelse","name":"Børn & uddannelse","lo":"Mest lighed","hi":"Mest krav og frit valg"}],"pseudo":{"na":{"letter":"NA","name":"Nordatlantiske mandater","short":"Grønland og Færøerne","color":"#9AA3B2","on":"#12161C"},"ufg":{"letter":"UFG","name":"Uden for folketingsgrupperne","short":"Løsgængere","color":"#C9CED8","on":"#12161C"}},"election":{"date":"2026-03-24","results":{"s":{"pct":21.8,"seats":38},"sf":{"pct":11.6,"seats":20},"v":{"pct":10.1,"seats":18},"la":{"pct":9.4,"seats":16},"df":{"pct":9.1,"seats":16},"m":{"pct":7.7,"seats":14},"k":{"pct":7.6,"seats":13},"el":{"pct":6.3,"seats":11},"rv":{"pct":5.8,"seats":10},"dd":{"pct":5.8,"seats":10},"alt":{"pct":2.6,"seats":5},"bp":{"pct":2.1,"seats":4}},"source":{"title":"lex.dk: Folketingsvalg 2026","url":"https://lex.dk/folketingsvalg_2026"}},"government":{"name":"Regeringen Mette Frederiksen III","nick":"Firkløverregeringen","since":"2026-06-03","parties":["s","sf","m","rv"],"support":["el","alt"],"formation":"Dannet efter 69 dage og tre kongerunder. Troels Lund Poulsen (V) fik forsøget 8.–22. maj og opgav. Mindretalsregering med 82 mandater ved dannelsen.","basis":"Det politiske grundlag for firkløverregeringen (73 sider): grøn profil, sociale initiativer, skatte- og velfærdsreformer og et stærkere nordisk og europæisk forsvarssamarbejde.","ministers":[{"name":"Mette Frederiksen","party":"s","post":"Statsminister"},{"name":"Lars Løkke Rasmussen","party":"m","post":"Udenrigsminister"},{"name":"Pia Olsen Dyhr","party":"sf","post":"Økonomi- og indenrigsminister"},{"name":"Martin Lidegaard","party":"rv","post":"Erhvervs- og konkurrencekraftsminister"},{"name":"Peter Hummelgaard","party":"s","post":"Finansminister"},{"name":"Nicolai Wammen","party":"s","post":"Justitsminister"},{"name":"Christina Egelund","party":"m","post":"Forsknings-, uddannelses- og digitaliseringsminister"},{"name":"Samira Nawa","party":"rv","post":"Klima-, energi- og forsyningsminister"},{"name":"Jacob Mark","party":"sf","post":"Børne-, ældre- og boligminister"},{"name":"Morten Bødskov","party":"s","post":"Udlændinge- og integrationsminister"},{"name":"Magnus Heunicke","party":"s","post":"Undervisningsminister"},{"name":"Ane Halsboe-Jørgensen","party":"s","post":"Beskæftigelsesminister og minister for ligestilling"},{"name":"Jeppe Bruus","party":"s","post":"Forsvarsminister"},{"name":"Jakob Engel-Schmidt","party":"m","post":"Skatte- og vækstminister"},{"name":"Ida Auken","party":"s","post":"Sundheds- og kirkeminister"},{"name":"Christian Rabjerg Madsen","party":"s","post":"Minister for natur og dyrevelfærd"},{"name":"Zenia Stampe","party":"rv","post":"Kulturminister"},{"name":"Lisbeth Bech-Nielsen","party":"sf","post":"Minister for samfundssikkerhed og beredskab"},{"name":"Monika Rubin","party":"m","post":"Socialminister og minister for nordisk samarbejde"},{"name":"Maria Reumert Gjerding","party":"sf","post":"Miljøminister"},{"name":"Karina Lorentzen Dehnhardt","party":"sf","post":"By-, land- og transportminister (siden 27. okt. 2026)"}],"source":{"title":"lex.dk: Regeringen Mette Frederiksen III","url":"https://lex.dk/Regeringen_Mette_Frederiksen_III"}},"parties":[{"id":"s","letter":"A","name":"Socialdemokratiet","short":"S","founded":"1871","foundedNote":"Stiftet i 1871 af Louis Pio, Harald Brix og Paul Geleff som en sektion af Den Internationale Arbejderforening, for at varetage den voksende arbejderklasses interesser. Partiet hed Socialdemokraterne indtil 2016.","leader":{"name":"Mette Frederiksen","title":"Formand og statsminister","since":"2015","born":"1977","bio":"Formand for Socialdemokratiet siden 2015 og statsminister siden 2019. Hun har ledet tre regeringer: Mette Frederiksen I (2019), II (SVM-regeringen fra 2022) og III (firkløverregeringen fra 3. juni 2026). Hun har flere gange samarbejdet med borgerlige partier i enkeltsager. Ved valget 24. marts 2026 led partiet sit dårligste resultat siden 1903, og hun har givet udtryk for, at hun er klar til at fortsætte som leder og statsminister."},"role":"regering","roleNote":"Socialdemokratiet er største parti i firkløverregeringen sammen med SF, Moderaterne og Radikale Venstre, som har 82 mandater. Regeringen er en mindretalsregering, der støttes af Enhedslisten og Alternativet.","ideology":["socialdemokratisk","velfærdsstat","midterpolitik"],"euGroup":"S&D-gruppen","youth":{"name":"Danmarks Socialdemokratiske Ungdom (DSU)","note":"Partiets ungdomsorganisation med lokale afdelinger over hele landet."},"website":"https://www.socialdemokratiet.dk","oneLiner":"Velfærdsstatens parti, der i 2026 gik i regering med midten og SF efter sit dårligste valg siden 1903.","summary":"Socialdemokratiet vil bevare og udbygge en stor offentlig velfærd med tryghed for ældre, syge og nedslidte, og gratis tandpleje er et langsigtet mål. Partiet står for en stram udlændingepolitik, hvor færre udlændinge skal komme til Danmark, og hvor kriminelle udlændinge skal udvises. Økonomisk vil partiet have en stærk offentlig sektor, men i firkløverregeringen har det accepteret skattelettelser for topskatteydere og erhvervslivet. Partiet adskiller sig fra de borgerlige ved at fastholde en stor offentlig rolle i velfærden, og fra SF ved at vægte udlændingestramninger højere.","pitch":"Vi har sat en stærk regering sammen midt i en svær tid. Vi står fast på en stram og fast udlændingepolitik, vi sikrer tryghed for de ældre og de nedslidte med en højere tidlig pension, og vi vil genindføre store bededag fra 2030. Og vi bruger mere på forsvaret, så Danmark kan stå stærkt i Europa.","critique":"Kritikere peger på, at partiet har mistet mange vælgere, og at samarbejdet med borgerlige partier om skat og store bededag har skuffet mange af partiets egne vælgere. FH og Ældre Sagen mener, at finanslovsforslaget for 2027 gør det sværere at få seniorpension. Dansk Folkeparti stemte i september og oktober 2026 for flere forslag, som S stemte imod, bl.a. om store bededag og koranloven.","keyIssues":[{"title":"Tryghed for ældre og nedslidte (Arne-pension)","detail":"Lovforslag L 98 hæver ydelsen for tidlig pension (Arne-pension) med 3.162 kr. pr. måned, så den kommer på niveau med seniorpensionen for gifte og samlevende. Aldersgrænsen på 64 år fastholdes for årgangene 1963-1965, så de kan få tidlig pension i op til fire år. Kravet til anciennitet lempes midlertidigt for disse årgange. Forslaget er fremsat af regeringen (S, SF, M og RV) og er opdateret 13. november 2026."},{"title":"Stram udlændingepolitik","detail":"Grundlaget siger: „Vi står fast på udlændingepolitikken, så der er styr på antallet, der kommer til Danmark.“ Folketinget vedtog 3. september 2026 L 17 A, der skærper udvisningen ved ubetinget fængselsstraf på mindst ét år for visse former for alvorlig kriminalitet, med S for. Samme dag vedtog Folketinget L 17 B om styrket hjemrejsestøtte. Regeringens lovforslag L 43 begrænser opholdstilladelser for personer fra mindre krigsramte områder i Ukraine."},{"title":"Skat og afgifter","detail":"Grundlaget afskaffer toptopskatten og mellemskatten og fastsætter en bundskat op til 777.900 kr. og derefter en topskat på 15 procentpoint. Selskabsskatten sænkes. Den 12. november 2026 vedtog Folketinget L 36, der afskaffer kaffeafgiften og indfører nulmoms på bøger, med S for. Dansk Erhverv har kritiseret, at finansieringen af skattelettelserne er usikker."},{"title":"Tandpleje og sundhed","detail":"Grundlaget har som ambition, at tandpleje skal være gratis for hele befolkningen. Det starter med sårbare grupper og førtidspensionister. Lovforslag L 64 gør tandpleje vederlagsfri for kontanthjælpsmodtagere og andre på kontanthjælpsniveau, og L 87 indfører kronikerpakker og frit valg til sundheds- og omsorgspladser."},{"title":"Grøn omstilling og drikkevand","detail":"Regeringen vil være den grønneste regering og lover en reduktion af drivhusgasser på mindst 85 procent i 2035 i forhold til 1990. Grundlaget indeholder et nationalt sprøjteforbud på sårbare grundvandsområder og en sænkning af nitratgrænsen. Folketinget vedtog 3. september 2026 L 5 om bæredygtig forvaltning af næringsstoffer i land- og skovbrug, med S for, mens DF stemte imod."},{"title":"Forsvar og NATO","detail":"Udgifterne til forsvar og beredskab skal være mindst 5 procent af BNP i 2030, heraf 3,5 procent til forsvar. Danmark skal indfri NATO-målet allerede i 2030."},{"title":"Store bededag","detail":"Grundlaget lover at genindføre store bededag som helligdag fra 2030, forudsat at der først skabes en yderligere beskæftigelsesstigning. Lovforslaget fremsættes i 2027. Den 1. oktober 2026 forkastede Folketinget B 3, et beslutningsforslag fra DF om at genindføre store bededag med det samme. S stemte imod."}],"positions":{"udlaendinge":{"score":4,"text":"Grundlaget står fast på en stram og fast udlændingepolitik. Folketinget vedtog 3. september 2026 L 17 A om skærpet udvisning, med S for. Den 27. august 2026 vedtog Folketinget L 15 om gennemførelse af dele af EU's migrations- og asylpagt med 77 stemmer for, herunder S, mens DF, Liberal Alliance, Alternativet og Dansk Folkeparti stemte imod. Regeringen vil også genfremsætte et lovforslag om statsborgerskab for 2.055 tidligere godkendte ansøgere efter en ny gennemgang."},"oekonomi":{"score":3,"text":"Partiet står for en stor offentlig sektor, men firkløverregeringen sænker skatten for topskatteydere og erhvervslivet: toptopskat og mellemskat afskaffes, og selskabsskatten sænkes. Den 12. november 2026 vedtog Folketinget L 36 om afskaffelse af kaffeafgiften og nulmoms på bøger, med S for. I valgkampen foreslog S en skat på 0,5 procent af formuer over 25 mio. kr. Den er ikke med i grundlaget."},"arbejdsmarked":{"score":2,"text":"Socialdemokratiet vil sikre tryghed for nedslidte og syge. Lovforslag L 98 hæver Arne-pensionen med 3.162 kr. pr. måned og fastholder aldersgrænsen på 64 år for årgangene 1963-1965. Regeringens reform af beskæftigelsesindsatsen (L 61-L 63) skal afskaffe jobafklaringsforløb og begrænse sanktioner til situationer, hvor tilliden er brudt."},"velfaerd":{"score":2,"text":"Partiet vil have flere offentlige kroner og offentligt ansatte i velfærden og tager initiativ til et Velfærdsforlig 2.0. Lovforslag L 87 om kronikerpakker og frit valg til sundheds- og omsorgspladser er fremsat af regeringen, og grundlaget har en 2040-strategi for ældreområdet."},"sundhed":{"score":2,"text":"Socialdemokratiet vil styrke den offentlige sundhedssektor gennem sundhedsreformen og en ny Forebyggelsesfond. Lovforslag L 64 gør tandpleje vederlagsfri for kontanthjælpsmodtagere og andre på kontanthjælpsniveau. Gratis tandpleje for hele befolkningen er et langsigtet mål."},"klima":{"score":3,"text":"Regeringen vil have en reduktion af drivhusgasser på mindst 85 procent i 2035 i forhold til 1990, en gennemgribende elektrificering og mere vedvarende energi. Partiet vil være den grønneste regering i Danmarks historie."},"natur_landbrug":{"score":3,"text":"Grundlaget lægger vægt på rent drikkevand, mere natur og bedre dyrevelfærd for grisene. Et nationalt sprøjteforbud på sårbare grundvandsområder er lovet, og nitratgrænsen skal sænkes. Folketinget vedtog 3. september 2026 L 5 om bæredygtig forvaltning af næringsstoffer i land- og skovbrug, med S for. DF stemte imod."},"eu":{"score":2,"text":"Socialdemokratiet fører en EU-positiv linje og vil gå forrest i det europæiske samarbejde. Partiet stemte den 27. august 2026 for L 15 om EU's migrations- og asylpagt, som DF stemte imod."},"forsvar":{"score":5,"text":"Forsvars- og beredskabsudgifterne skal være mindst 5 procent af BNP i 2030, heraf 3,5 procent til forsvar. Danmark skal indfri NATO-målet allerede i 2030. Regeringens lovforslag L 95 giver forsvaret mulighed for at detektere og spore ubemandede fartøjer."},"ret":{"score":4,"text":"Lovforslag L 29 gør det strafbart at indgå i et mæglingsråd for at unddrage strafbare gerninger fra retsforfølgning, og et æresrelateret motiv skal være en skærpende omstændighed. Grundlaget lover strafskærpelser for personfarlig kriminalitet og en udvisningsreform. Reglerne for straffesagsgæld skal revideres."},"bolig":{"score":2,"text":"Regeringen vil have en Boligplan 2030 med en forpligtende aftale om at udbygge boligmassen i hovedstaden og flere plejeboliger. Lovforslag L 86 fastsætter anvendelsen af Landsbyggefondens midler i 2027."},"uddannelse":{"score":3,"text":"Partiet vil have en ny finansiering af folkeskolen, så skoler i hele landet får samme basisvilkår. Lovforslag L 5 forhøjer SU-fribeløbet for elever på ungdomsuddannelser fra 1. januar 2027."}},"history":[{"year":"1871","event":"Partiet stiftes af Louis Pio, Harald Brix og Paul Geleff som en sektion af Den Internationale Arbejderforening."},{"year":"1916","event":"Partiet går ind i en regering under C.Th. Zahle med henvisning til krigens omstændigheder."},{"year":"1924","event":"Partiet danner sin første mindretalsregering, som den største partigruppe i Folketinget."},{"year":"1935","event":"Partiet opnår sit valgmæssige højdepunkt med 46,1 procent under sloganet „Stauning eller kaos“."},{"year":"1949","event":"Partiet siger ja til NATO-medlemskab, et skifte fra den tidligere forsvarsskepsis."},{"year":"1973","event":"Ved jordskredsvalget falder partiet fra 70 til 46 mandater."},{"year":"2001","event":"Partiet mister for første gang siden 1924 status som Folketingets største parti."},{"year":"2011","event":"Helle Thorning-Schmidt bliver Danmarks første kvindelige statsminister i en regering med Radikale Venstre og SF."},{"year":"2019","event":"Mette Frederiksen danner en mindretalsregering. SF er et af tre støtteparter."},{"year":"2026","event":"Ved valget 24. marts 2026 får partiet 21,84 procent og 38 mandater, 12 færre end i 2022 og det dårligste resultat siden 1903. Efter 69 dage med tre kongerunder dannes firkløverregeringen 3. juni 2026."}],"people":[{"name":"Mette Frederiksen","role":"Statsminister og formand","note":"Partiets dominerende skikkelse siden 2015 og den politiker, der har ledet tre regeringer."},{"name":"Peter Hummelgaard","role":"Finansminister","note":"Ansvarlig for finanslovsforslaget for 2027 (L 73)."},{"name":"Morten Bødskov","role":"Udlændinge- og integrationsminister","note":"Står for udlændingelinjen og for gennemgangen af statsborgerskabssager."},{"name":"Ane Halsboe-Jørgensen","role":"Beskæftigelses- og ligestillingsminister","note":"Har ansvaret for beskæftigelsesindsatsen og arbejdsmarkedet."},{"name":"Ida Auken","role":"Sundheds- og kirkeminister","note":"Står for sundhedsreformen og den planlagte Forebyggelsesfond."},{"name":"Nicolai Wammen","role":"Justitsminister","note":"Justitsministeriet står bag udvisningsreformen og de skærpede straffe."},{"name":"Jeppe Bruus","role":"Forsvarsminister","note":"Ansvarlig for forsvarsløftet, der lover 3,5 procent af BNP til forsvar i 2030."}],"voters":{"summary":"Socialdemokratiets vælgere har historisk været overrepræsenteret blandt lønmodtagere i den private og offentlige sektor og blandt personer med en erhvervsuddannelse eller en kort videregående uddannelse. Partiet har traditionelt haft flere ældre end yngre vælgere, og kvinder og mænd stemmer omtrent ligt. Partiet står stærkest i byer med mange lønmodtagere og i Jylland og på Sjælland uden for hovedstaden.","strongholds":"Partiets stærkeste fodfæste har historisk været i de tættere befolkede dele af landet og i de områder, hvor der er mange lønmodtagere i industri, handel og den offentlige sektor. Partiet har over tid svækket sig i de store byer og på Vestegnen.","demographics":"Vælgerne er typisk ældre end gennemsnittet, har en erhvervsuddannelse eller en kort videregående uddannelse, og er ofte ansat i den offentlige sektor. Kvinder og mænd er ret ligeligt repræsenteret."},"election2026":{"note":"Socialdemokratiet fik 21,84 procent af stemmerne (779.252 stemmer) og 38 mandater ved valget 24. marts 2026, 12 færre end i 2022 (50 mandater og 27,5 procent). Det er partiets dårligste resultat siden 1903. Årsagerne diskuteres: den stramme udlændingelinje og velfærden, dyrtiden, og at venstrefløjens vælgere er skuffede over samarbejdet med de borgerlige, bl.a. om afskaffelsen af store bededag."},"strengths":["Partiet er det største i Folketinget og har en lang historie som regeringsparti.","Stærk profil på velfærd, ældre og tryghed, som er svær at ramme for konkurrenterne.","Mette Frederiksen er en erfaren statsminister, og hendes linje i Grønland-sagen beskrives af analytikere som bredt respekteret.","Har kunnet samle et bredt regeringsgrundlag med fire partier."],"weaknesses":["Laveste valgresultat siden 1903, og tab af vælgere til både venstre og højre.","Mindretalsregering, der er afhængig af støtte fra Enhedslisten og Alternativet i hver sag.","Mange vælgere mener, at partiet har skiftet kurs, fordi det samarbejder med borgerlige om skat og store bededag.","Den stramme udlændingelinje har ikke givet partiet fremgang, og DF mener, den ikke er stram nok."],"internalTensions":[{"title":"Formueskatten fra valgkampen","detail":"Partiet foreslog i valgkampen en skat på 0,5 procent af formuer over 25 mio. kr. med provenuet øremærket til en lilleskole-reform. Forslaget er ikke med i firkløverregeringens grundlag. Det er uklart, om forslaget er opgivet eller udskudt."},{"title":"Skattelettelser versus velfærdsløfter","detail":"Grundlaget sænker topskatten for de højeste indkomster og selskabsskatten, samtidig med at partiet lover mere velfærd. Dansk Erhverv mener, at finansieringen er usikker. Det er et spørgsmål, hvor venstrefløjens vælgere og partiets egne politikere kan blive uenige."},{"title":"Mette Frederiksens fremtid","detail":"Efter valgnederlaget har Mette Frederiksen givet udtryk for, at hun er klar til at fortsætte som leder og statsminister. Hendes fremtid som leder er ikke afgjort."}],"typicalArguments":[{"claim":"Vi står fast på udlændingepolitikken, så der er styr på antallet, der kommer til Danmark.","counter":"Dansk Folkeparti stemte 27. august 2026 imod L 15 om EU's migrationspagt, og om stramningerne er tilstrækkelige, er et politisk spørgsmål."},{"claim":"Vi sikrer tryghed for de ældre og nedslidte med en højere tidlig pension og en bedre Arne-pension.","counter":"FH og Ældre Sagen har kritiseret finanslovsforslaget for 2027, fordi det gør det sværere at få seniorpension for syge og nedslidte. Ældre Sagen skriver senere, at regeringen har droppet de planlagte besparelser."},{"claim":"Vi sænker skatten for dem, der arbejder og for erhvervslivet, så væksten kommer.","counter":"Dansk Erhverv mener, at finansieringen af skattelettelserne er usikker, og at der er flere tidsler i grundlaget."},{"claim":"Vi er den grønneste regering og vil have rent drikkevand.","counter":"Dansk Folkeparti stemte 3. september 2026 imod L 5 om bæredygtig forvaltning af næringsstoffer i land- og skovbrug."}],"vsDF":{"agree":["Udvisning af kriminelle udlændinge: L 17 A om skærpet udvisning blev vedtaget 3. september 2026 med stemmer fra både S og DF.","Afskaffelse af kaffeafgiften og nulmoms på bøger: L 36 B blev vedtaget 12. november 2026 med stemmer fra både S og DF."],"disagree":["Store bededag: 1. oktober 2026 stemte S imod B 3, DF's forslag om at genindføre store bededag. DF stemte for.","Koranloven: 1. oktober 2026 stemte S imod B 6, DF's forslag om at afskaffe koranloven. DF stemte for.","EU's migrationspagt: 27. august 2026 stemte S for L 15, mens DF stemte imod.","Hjemrejsestøtte: 3. september 2026 stemte S for L 17 B, mens DF stemte imod."],"note":"Afstemningerne står i oda.ft.dk-filen for de seneste 30 afstemninger. DF har efter valget droppet kravet om at komme i regering, og DF arbejder for en blå regering."},"vocabulary":[{"term":"Firkløverregeringen","meaning":"Regeringen af S, SF, Moderaterne og Radikale Venstre, dannet 3. juni 2026. Navnet er genbrugt fra Poul Schlüters borgerlige regeringer 1982-1988."},{"term":"Velfærdsforlig 2.0","meaning":"Et planlagt bredt forlig om velfærd og pension, som regeringen vil forhandle efter en trepartsaftale."},{"term":"Arne-pension","meaning":"Den tidlige pensionsordning for nedslidte og syge. Lovforslag L 98 hæver ydelsen med 3.162 kr. pr. måned."},{"term":"Udvisningsreform","meaning":"Et lovforslag, der skal sikre, at flere kriminelle udlændinge udvises fra Danmark."},{"term":"Mindretalsregering","meaning":"En regering, der ikke har flertal i Folketinget alene og derfor er afhængig af støtte fra andre partier i hver sag."}],"funFacts":["Partiet fik 46,1 procent ved valget i 1935 under sloganet „Stauning eller kaos“.","Store bededag skal genindføres som helligdag i 2030, hvis betingelserne er opfyldt.","Partiet blev stiftet i 1871 som en sektion af Den Internationale Arbejderforening."],"sources":[{"title":"Regeringens lovforslag 2026-27 (Folketinget)","url":"https://www.ft.dk/samling/20261/lovforslag/L98/index.htm"},{"title":"Seneste afstemninger i Folketinget (Folketinget)","url":"https://www.ft.dk/samling/20252/beslutningsforslag/B3/index.htm"},{"title":"Regeringen Mette Frederiksen III (lex.dk)","url":"https://lex.dk/Regeringen_Mette_Frederiksen_III"},{"title":"Socialdemokratiet (lex.dk)","url":"https://lex.dk/Socialdemokratiet"},{"title":"Folketingsvalget 2026 (da.wikipedia.org)","url":"https://da.wikipedia.org/wiki/Folketingsvalget_2026"},{"title":"Det politiske grundlag for firkløverregeringen (Statsministeriet, juni 2026)","url":"https://stm.dk/media/rc1ktdmg/det-politiske-grundlag-for-firkloeverregeringen.pdf"},{"title":"Danish premier's party wins election vote but suffers worst result since 1903 (Irish Times, 25.3.2026)","url":"https://www.irishtimes.com/world/europe/2026/03/25/danish-premiers-party-wins-election-vote-but-suffers-worst-result-since-1903/"},{"title":"Ældre Sagen: 2026 besparelser på seniorpensionen droppet","url":"https://www.aeldresagen.dk/maerkesager-og-resultater/resultater/politiske-resultater/2026-besparelser-paa-seniorpensionen-droppet"},{"title":"Dansk Erhverv: formueskat vil ramme hårdt uden for Nordsjælland, hovedstaden og de store byer (marts 2026)","url":"https://www.danskerhverv.dk/presse-og-nyheder/nyheder/2026/marts/formueskat-vil-ramme-hardt-uden-for-nordsjalland-hovedstaden-og-de-store-byer/"},{"title":"Dansk Erhverv: nyt regeringsgrundlag med flere tidsler og usikker finansiering (juni 2026)","url":"https://www.danskerhverv.dk/presse-og-nyheder/nyheder/2026/juni/dansk-erhverv-sardeles-starke-tiltag-for-erhvervsliv-og-konkurrencekraft-i-nyt-regeringsgrundlag--men-ogsa-flere-tidsler-og-usikker-finansiering/"},{"title":"Altinget: Messerschmidts nye indpisker har en plan (16.7.2026)","url":"https://www.altinget.dk/christiansborg/artikel/messerschmidts-nye-indpisker-har-en-plan-der-skal-lokke-utilfredse-sfere-og-socialdemokrater-over-til-df"}],"order":4,"color":"#A82721","on":"#FFFFFF","blok":"rød","officialName":"Socialdemokratiet","nick":"Socialdemokratiet"},{"id":"sf","letter":"F","name":"Socialistisk Folkeparti","short":"SF","founded":"1959","foundedNote":"SF blev stiftet 15. februar 1959 efter et brud med Danmarks Kommunistiske Parti. Aksel Larsen var blevet ekskluderet fra DKP i november 1958, og striden handlede om partiets uafhængighed af det sovjetiske kommunistparti.","leader":{"name":"Pia Olsen Dyhr","title":"Formand og økonomi- og indenrigsminister","since":"2014","born":"1971","bio":"Formand for SF siden februar 2014, efter Annette Vilhelmsen. Hun var handelsminister i Helle Thorning-Schmidts regering fra 2011 og transportminister fra 2013 til 2014. I 2026 blev hun økonomi- og indenrigsminister i firkløverregeringen, SF's første ministerpost siden 2014. Hun har sagt, at Lars Løkke Rasmussen har „reformeret sig selv“, og det har skabt debat i SF's bagland."},"role":"regering","roleNote":"SF sidder i firkløverregeringen sammen med Socialdemokratiet, Moderaterne og Radikale Venstre fra 3. juni 2026. SF var uden for regeringen fra 2014 til 2026. Regeringen er en mindretalsregering, der støttes af Enhedslisten og Alternativet.","ideology":["socialistisk","grøn","velfærdsstat"],"euGroup":"De Grønne/Den Europæiske Frie Alliance (Greens/EFA)","youth":{"name":"SFU (Socialistisk Folkeparti Ungdom)","note":"Partiets ungdomsorganisation."},"website":"https://sf.dk","oneLiner":"Grøn socialistisk venstrefløj, der er tilbage i regering for første gang siden 2014.","summary":"SF vil have en stærk offentlig velfærd, et grønnere Danmark og rent drikkevand, og partiet vil have et nationalt sprøjteforbud på sårbare grundvandsområder. SF prioriterer børn og unges trivsel, en ny finansiering af folkeskolen og flere penge til sundhed for sårbare grupper. SF er mere EU-positiv og mere klimaambitiøs end de borgerlige partier, men i firkløverregeringen har partiet accepteret stramme regler for udlændinge på kontanthjælp og førtidspension, som det før valget var imod.","pitch":"Vi er tilbage i regering for første gang siden 2014, og vi bruger det til at gøre noget for drikkevandet, børnenes trivsel og de syge og nedslidte. Vi har fået et nationalt sprøjteforbud på de sårbare grundvandsområder med i aftalen og et klimamål på 85 procent i 2035. Vi er ikke kommet igennem med alt, men vi sikrer en grøn og social politik.","critique":"Kritikere mener, at SF har kompromitteret sine principper ved at gå i regering med Lars Løkke Rasmussen og acceptere skattelettelser for topskatteydere og erhvervslivet. SF's bagland er ifølge kommentatorer skeptisk over for Løkke, især i den økonomiske politik. Partiet har også accepteret stramme regler for udlændinge, som det før valget var imod. Borgerlige kritikere peger på, at velfærds- og klimakrav koster penge.","keyIssues":[{"title":"Sprøjteforbud og rent drikkevand","detail":"Grundlaget lover et nationalt sprøjteforbud på sårbare grundvandsdannende områder, som også omfatter slam og forurenet jord. Lovgivningen skal fremsættes i Folketinget i 2026, og forbuddet skal indføres gradvist. Nitratgrænsen skal sænkes til myndighedernes anbefalede grænseværdi. Grundlaget siger selv, at forbuddet vil ramme de enkelte grundejere forskelligt."},{"title":"Trivsel og folkeskole","detail":"Grundlaget lover en ny finansiering af folkeskolen med en mere ensartet grundfinansiering, så skoler i hele landet får samme basisvilkår. Der skal være flere lærere, og partiet vil sætte ind mod mistrivsel og langvarigt skolefravær. Der nedsættes en ekspertkommission for trivselsøkonomi. Pia Olsen Dyhr har sagt, at en stor trivselsreform for børn og unge lå på bordet i forhandlingerne, men den blev ikke en del af aftalen."},{"title":"Udlændinge på kontanthjælp og førtidspension","detail":"SF og Radikale Venstre tilsluttede sig i juni 2026 strammere regler for indvandrere på kontanthjælp og førtidspension, som er aftaler fra den tidligere SVM-regering. Før valget var begge partier imod stramningerne. SF's beskæftigelsesordfører, Kirsten Normann Andersen, siger, at det er normalt, at et regeringsparti accepterer aftaler, det ikke selv går ind for."},{"title":"Gratis tandpleje og sundhed for sårbare","detail":"Grundlaget har som ambition, at tandpleje skal være gratis for hele befolkningen. Det starter med sårbare grupper og førtidspensionister. Lovforslag L 64 gør tandpleje vederlagsfri for kontanthjælpsmodtagere og andre på kontanthjælpsniveau. Lovforslaget udmønter en aftale om en ny model for voksentandplejen, som SF var med i."},{"title":"Tidlig pension for nedslidte","detail":"Grundlaget siger, at aldersgrænsen for tidlig pension ikke hæves, som det ellers var forudsat 1. januar 2027, og at ydelsen hæves, så den bliver ensartet med seniorpensionen. Lovforslag L 98 hæver ydelsen med 3.162 kr. pr. måned og fastholder aldersgrænsen på 64 år for årgangene 1963-1965. FH og Ældre Sagen mener, at finanslovsforslaget for 2027 gør det sværere at få seniorpension for nedslidte."},{"title":"Klima og grøn omstilling","detail":"Grundlaget lover en reduktion af drivhusgasserne på mindst 85 procent i 2035 i forhold til 1990, en mere gennemgribende elektrificering og et mere ambitiøst klimamål. Målet står i grundlaget, som SF er med til at underskrive."}],"positions":{"udlaendinge":{"score":3,"text":"SF er mere åben end S og de borgerlige, men har i juni 2026 accepteret strammere regler for udlændinge på kontanthjælp og førtidspension. SF stemte den 3. september 2026 for L 17 A om skærpet udvisning ved ubetinget fængselsstraf og for L 15 om EU's migrationspagt den 27. august 2026. Partiet står bag grundlagets „stramme og faste udlændingepolitik“."},"oekonomi":{"score":2,"text":"SF vil have mere offentlig velfærd og en skat, der rammer de rigeste hårdere. Grundlaget afskaffer dog toptopskatten og mellemskatten og sænker selskabsskatten. Det er et kompromis, SF er med til at stå bag i regeringen. Den 12. november 2026 vedtog Folketinget L 36 om afskaffelse af kaffeafgiften og nulmoms på bøger, med SF for."},"arbejdsmarked":{"score":2,"text":"SF vil have tryghed for nedslidte og syge. Lovforslag L 98 hæver ydelsen for tidlig pension med 3.162 kr. pr. måned og fastholder aldersgrænsen på 64 år for årgangene 1963-1965. Samtidig lemper grundlaget modregningsreglerne for efterløn og tidlig pension, så det bliver mere attraktivt at arbejde længere."},"velfaerd":{"score":1,"text":"SF vil have flere offentlige kroner og flere ansatte i velfærden. Grundlaget lover et løft til de pensionister, der har mindst, og en 2040-strategi for ældreområdet. Der skal også være et Velfærdsforlig 2.0, der samler bredt om velfærd og pension."},"sundhed":{"score":1,"text":"SF vil styrke den offentlige sundhedssektor. Lovforslag L 64 gør tandpleje vederlagsfri for kontanthjælpsmodtagere og andre på kontanthjælpsniveau, og grundlaget vil have en ny Forebyggelsesfond. Gratis tandpleje for alle er et langsigtet mål."},"klima":{"score":2,"text":"Grundlaget lover en reduktion af drivhusgasser på mindst 85 procent i 2035 og en mere gennemgribende elektrificering. Det er et ambitiøst klimamål, som SF er med til at stå bag."},"natur_landbrug":{"score":2,"text":"SF har fået et nationalt sprøjteforbud på sårbare grundvandsområder med i grundlaget, og nitratgrænsen skal sænkes. Folketinget vedtog 3. september 2026 L 5 om næringsstoffer i land- og skovbrug, og SF stemte for. DF stemte imod."},"eu":{"score":2,"text":"SF er EU-positiv og sidder i gruppen De Grønne/EFA i Europa-Parlamentet. Den 27. august 2026 stemte SF for L 15 om EU's migrationspagt."},"forsvar":{"score":3,"text":"SF er med til at stå bag, at Danmark indfrier NATO-målet i 2030, og at udgifterne til forsvar og beredskab skal være mindst 5 procent af BNP i 2030, heraf 3,5 procent til forsvar."},"ret":{"score":3,"text":"SF stemte for L 17 A om skærpet udvisning ved ubetinget fængselsstraf den 3. september 2026. Grundlaget vil revidere reglerne for straffesagsgæld, så det kan betale sig at tage et job efter afsoning."},"bolig":{"score":2,"text":"SF er med til at stå bag Boligplan 2030 med en forpligtende aftale om at udbygge boligmassen i hovedstaden og flere plejeboliger. Lovforslag L 86 fastsætter anvendelsen af Landsbyggefondens midler i 2027."},"uddannelse":{"score":1,"text":"SF vil have en ny finansiering af folkeskolen, der sikrer samme basisvilkår overalt i landet, og flere lærere. Grundlaget investerer også i daginstitutioner og SFO."}},"history":[{"year":"1959","event":"SF stiftes 15. februar efter et brud med DKP."},{"year":"1960","event":"Partiet vinder 11 mandater ved sit første folketingsvalg."},{"year":"1966","event":"SF støtter den socialdemokratiske „røde regering“. Venstresocialisterne bryder ud i 1967, og regeringen mister flertallet."},{"year":"1979","event":"SF indfører kønskvoter som det første parti og får repræsentation i Europa-Parlamentet."},{"year":"1994","event":"SF støtter Poul Nyrup Rasmussens regeringer frem til 2001 uden selv at sidde i regeringen."},{"year":"2011","event":"SF går ind i Helle Thorning-Schmidts regering."},{"year":"2014","event":"SF forlader regeringen i januar 2014, og Pia Olsen Dyhr vælges til formand i februar 2014."},{"year":"2019","event":"SF bliver et af tre støtteparter for Mette Frederiksens første regering, uden selv at sidde i regeringen."},{"year":"2024","event":"SF bliver Danmarks største parti ved valget til Europa-Parlamentet med 17,4 procent."},{"year":"2026","event":"Ved folketingsvalget 24. marts 2026 får SF 11,58 procent og 20 mandater, fem flere end i 2022. Den 3. juni 2026 går partiet ind i firkløverregeringen, første gang siden 2014."}],"people":[{"name":"Pia Olsen Dyhr","role":"Formand og økonomi- og indenrigsminister","note":"Har været SF's formand siden 2014 og er partiets mest centrale person i regeringen."},{"name":"Karina Lorentzen Dehnhardt","role":"By-, land- og transportminister fra 27. oktober 2026","note":"Overtog ministeriet efter Signe Munk, der gik på sygeorlov med stress."},{"name":"Jacob Mark","role":"Børne-, ældre- og boligminister","note":"Har ansvaret for børne-, ældre- og boligpolitikken, som er centrale for SF."},{"name":"Maria Reumert Gjerding","role":"Miljøminister","note":"Har ansvaret for miljøpolitikken, herunder sprøjteforbuddet, som grundlaget lover."},{"name":"Lisbeth Bech-Nielsen","role":"Minister for samfundssikkerhed og beredskab","note":"Står for beredskabet i en tid med sikkerhedstrusler."},{"name":"Theresa Berg Andersen","role":"Gruppeformand","note":"Har erklæret fuld opbakning til Pia Olsen Dyhr og det fælles projekt."},{"name":"Kirsten Normann Andersen","role":"Beskæftigelsesordfører","note":"Har forsvaret partiets accept af stramme regler for udlændinge på kontanthjælp."}],"voters":{"summary":"SF's vælgere er historisk overrepræsenteret blandt yngre vælgere, offentligt ansatte og personer med en videregående uddannelse. Kvinder har ofte stemt på SF i højere grad end mænd. Partiet har en stærk tilslutning blandt vælgere, der prioriterer klima og velfærd højt.","strongholds":"Partiets stærkeste fodfæste har historisk været i byerne og i de universitetsbyer, hvor der er mange studerende og offentligt ansatte.","demographics":"Vælgerne er typisk yngre end gennemsnittet, har ofte en videregående uddannelse og er ofte ansat i den offentlige sektor. Kvinder er stærkere repræsenteret end mænd."},"election2026":{"note":"SF fik 11,58 procent (413.306 stemmer) og 20 mandater ved valget 24. marts 2026, fem flere end i 2022. Partiet var største parti ved valget til Europa-Parlamentet i 2024 med 17,4 procent. Efter valget har partiet ifølge en overskrift på Voxmeter 3. november 2026 målt sin laveste måling siden 2022."},"strengths":["Stærk profil på klima, natur og drikkevand, som har opbakning i en stor del af vælgerne.","Har fået sprøjteforbuddet og klimamålet med i en regering, hvor S er det dominerende parti.","EU-positiv profil og en stærk gruppe i Europa-Parlamentet.","Pia Olsen Dyhr står stadig stærkt i partiet, selv om hendes image har fået skrammer."],"weaknesses":["Første gang i regering siden 2014, og partiet skal vise, at det kan levere resultater for vælgerne.","Har accepteret stramme udlændingeregler, som partiet før valget var imod.","Bagland og vælgere er ifølge kommentatorer skeptiske over for samarbejdet med Lars Løkke Rasmussen, især i den økonomiske politik.","Målinger efter valget har været lave, og partiet skal finde sit kerneprofil i regeringen."],"internalTensions":[{"title":"Udlændinge: stramninger, som SF før var imod","detail":"I juni 2026 tilsluttede SF og Radikale Venstre sig strammere regler for indvandrere på kontanthjælp og førtidspension. Før valget var begge partier imod stramningerne. Det er et punkt, hvor partiets bagland kan reagere."},{"title":"Løkke i regering","detail":"Kommentatorer skriver, at det er et følsomt punkt for SF's bagland, at Lars Løkke Rasmussen er i regering, især i den økonomiske politik. Pia Olsen Dyhr har argumenteret for, at Løkke har reformeret sig selv."},{"title":"Skattelettelser og velfærd","detail":"Grundlaget afskaffer toptopskatten og mellemskatten og sænker selskabsskatten. SF skal forsvare kompromiset over for vælgere, der forventer mere omfordeling."}],"typicalArguments":[{"claim":"Vi har fået et nationalt sprøjteforbud, så drikkevandet bliver rent.","counter":"Landbruget og de grundejere, der bliver ramt, får større byrder. Grundlaget siger selv, at forbuddet rammer de enkelte grundejere forskelligt."},{"claim":"Vi har sikret investeringer i folkeskolen og en indsats for børns trivsel.","counter":"En stor trivselsreform for børn og unge blev ikke en del af aftalen, og det var et ønske, SF selv havde."},{"claim":"Vi har fået gratis tandpleje og større tryghed for pensionister.","counter":"Gratis tandpleje for alle er et langsigtet mål, og FH og Ældre Sagen mener, at finanslovsforslaget for 2027 gør det sværere at få seniorpension."},{"claim":"Vi har forhindret en borgerlig skattepolitik.","counter":"Grundlaget afskaffer toptopskatten og mellemskatten og sænker selskabsskatten, og SF er med til at stå bag det."}],"vsDF":{"agree":["Udvisning af kriminelle udlændinge: L 17 A om skærpet udvisning blev vedtaget 3. september 2026 med stemmer fra både SF og DF.","Afskaffelse af kaffeafgiften og nulmoms på bøger: L 36 B blev vedtaget 12. november 2026 med stemmer fra både SF og DF."],"disagree":["Store bededag: 1. oktober 2026 stemte SF imod B 3, DF's forslag om at genindføre store bededag. DF stemte for.","Koranloven: 1. oktober 2026 stemte SF imod B 6, DF's forslag om at afskaffe koranloven. DF stemte for.","EU's migrationspagt: 27. august 2026 stemte SF for L 15, mens DF stemte imod.","Landbrug: 3. september 2026 stemte SF for L 5 om næringsstoffer i land- og skovbrug, mens DF stemte imod."],"note":"Afstemningerne står i oda.ft.dk-filen for de seneste 30 afstemninger. DF har efter valget droppet kravet om at komme i regering, og DF arbejder for en blå regering."},"vocabulary":[{"term":"Sprøjteforbud","meaning":"Et forbud mod sprøjtemidler på sårbare grundvandsdannende områder. Det skal beskytte drikkevandet."},{"term":"Trivselsøkonomi","meaning":"En ekspertkommission skal se på, hvordan trivsel, social sammenhæng og økonomi kan måles og prioriteres sammen."},{"term":"Røde regering","meaning":"En regering af S og de venstreorienterede partier. Pia Olsen Dyhr har talt for en rød regering i valgkampen."},{"term":"Firkløverregeringen","meaning":"Regeringen af S, SF, Moderaterne og Radikale Venstre, dannet 3. juni 2026."},{"term":"Velfærdsforlig 2.0","meaning":"Et planlagt bredt forlig om velfærd og pension efter en trepartsaftale."}],"funFacts":["SF blev dannet i 1959 efter et brud med det kommunistiske parti, og de første år var præget af uenighed om Sovjetunionen.","SF var ifølge lex.dk det første parti i Danmark med kønskvoter, fra 1979.","I 2024 blev SF Danmarks største parti ved Europa-Parlamentsvalget med 17,4 procent."],"sources":[{"title":"Socialistisk Folkeparti (lex.dk)","url":"https://lex.dk/Socialistisk_Folkeparti"},{"title":"Pia Olsen Dyhr (lex.dk)","url":"https://lex.dk/Pia_Olsen_Dyhr"},{"title":"Regeringen Mette Frederiksen III (lex.dk)","url":"https://lex.dk/Regeringen_Mette_Frederiksen_III"},{"title":"Folketingsvalget 2026 (da.wikipedia.org)","url":"https://da.wikipedia.org/wiki/Folketingsvalget_2026"},{"title":"Det politiske grundlag for firkløverregeringen (Statsministeriet, juni 2026)","url":"https://stm.dk/media/rc1ktdmg/det-politiske-grundlag-for-firkloeverregeringen.pdf"},{"title":"Altinget: SF og Radikale tilslutter sig strammere regler for indvandrere på kontanthjælp og førtidspension (11.6.2026)","url":"https://www.altinget.dk/arbejdsmarked/artikel/sf-og-radikale-tilslutter-sig-strammere-regler-for-indvandrere-paa-kontanthjaelp-og-foertidspension"},{"title":"Altinget: Messerschmidts nye indpisker har en plan (16.7.2026)","url":"https://www.altinget.dk/christiansborg/artikel/messerschmidts-nye-indpisker-har-en-plan-der-skal-lokke-utilfredse-sfere-og-socialdemokrater-over-til-df"},{"title":"Altinget: Stor rokade i SF's ordførerskaber (3.11.2026)","url":"https://www.altinget.dk/artikel/stor-rokade-i-sfs-ordfoererskaber"},{"title":"Voxmeter","url":"https://www.voxmeter.dk"},{"title":"FH: Gode takter i finanslovsforslag (Ritzau, 9.10.2026)","url":"https://via.ritzau.dk/pressemeddelelse/15216180/fh-gode-takter-i-finanslovsforslag?lang=da"},{"title":"Ældre Sagen: 2026 besparelser på seniorpensionen droppet","url":"https://www.aeldresagen.dk/maerkesager-og-resultater/resultater/politiske-resultater/2026-besparelser-paa-seniorpensionen-droppet"},{"title":"SF's hjemmeside","url":"https://sf.dk"}],"order":2,"color":"#E07EA8","on":"#12161C","blok":"rød","officialName":"Socialistisk Folkeparti","nick":"SF"},{"id":"rv","letter":"B","name":"Radikale Venstre","short":"RV","founded":"1905","foundedNote":"Partiet blev stiftet 21. maj 1905 i Odense. Det brød ud af Venstre og var et liberalt reformparti, der ville have demokrati, skoler og social reform. Det har siden været et midterparti, der har båret både rød og blå regeringer.","leader":{"name":"Martin Lidegaard","title":"Partiformand / politisk leder","since":"2022","bio":"Var klima- og energiminister 2011-2014 og udenrigsminister 2014-2015. Blev valgt til politisk leder 3. november 2022. I 2026 er han erhvervs- og konkurrencekraftsminister i firkløverregeringen (lex.dk), og han har sagt, at uddannelse og energi er partiets to hovedkrav."},"role":"regering","roleNote":"Radikale Venstre er en af fire partier i firkløverregeringen, der blev præsenteret 3. juni 2026. Partiet har tre ministre: Martin Lidegaard (erhverv), Samira Nawa (klima, energi og forsyning) og Zenia Stampe (kultur). Regeringen er et mindretal og er afhængig af støtte fra Enhedslisten og Alternativet.","ideology":["liberalt","midterparti","europæisk","klimaorienteret"],"euGroup":"Renew Europe","youth":{"name":"Radikal Ungdom","note":"Partiets ungdomsorganisation."},"website":"https://www.radikale.dk","oneLiner":"Liberalt midterparti, der vil have grøn omstilling, stærk uddannelse og et samarbejdende Europa.","summary":"Radikale Venstre vil have en grøn omstilling, stærkere uddannelse og et åbent, europæisk samarbejde. Partiet kombinerer liberale værdier med en stærk stat på områder som uddannelse og klima. I regeringen har Lidegaard gjort energi og uddannelse til partiets to hovedkrav. Det adskiller partiet fra Moderaterne ved at lægge større vægt på klima og fordeling, og fra SF ved at være mere markedsorienteret i erhvervspolitikken.","pitch":"Vi vil have en grøn omstilling, der er fair, og et uddannelsessystem, der giver alle en chance. Vi har sikret, at Danmark har en regering med en klimapolitik, der har en retning. Vi står for et åbent, europæisk og liberalt Danmark.","critique":"Kritikerne mener, at Radikale Venstre har gået på kompromis med sine klimaambitioner for at få plads i regeringen. Lidegaard har selv sagt, at partiet som et af fire regeringspartier ikke kan garantere, at klimapolitikken bliver gennemført, bl.a. udfasningen af olie og gas efter 2042. Modstanderne peger også på, at partiet må stå på mål for en økonomisk linje, det ikke selv har skrevet.","keyIssues":[{"title":"Grøn energi og elektrificering","detail":"Lidegaard har sagt, at energipolitikken er et af partiets to hovedkrav. Det omfatter mere elektrificering, nye havvindudbud og en bedre elnet (Altinget, 20. mar. 2026). Lovforslag L 12 om elproduktionsanlæg på havet og L 14 om EU's brint- og gasmarkedspakke er i Folketinget nu."},{"title":"Uddannelse og folkeskole","detail":"Uddannelse var Lidegaards første 'absolutte hovedkrav' (Altinget, 20. mar. 2026). Regeringsgrundlaget afsætter 1 mia. kr. varigt til uddannelse og forskning. Lovforslag L 5 forhøjer SU-fribeløbet, og L 88 indfører en mundtlig eksamination på hf."},{"title":"Klimalov og klimaneutralitet","detail":"Regeringen vil indskrive klimaneutralitet i 2045 og 110 pct. reduktion i 2050 i klimaloven. Samira Nawa er klima-, energi- og forsyningsminister og deltog i COP31 i Antalya i november 2026."},{"title":"Fordeling og tech-skat","detail":"Regeringsgrundlaget vil øge beskatningen af store arvesummer og indføre en tech-skat på 1 mia. kr. årligt. Det er Radikale Venstres linje på fordeling i regeringen."},{"title":"Europa og NATO","detail":"Regeringen vil gå forrest i det europæiske samarbejde og indfri NATO-målet allerede i 2030. Radikale stemte 27. aug. 2026 for at gennemføre dele af EU's migrationspagt (L 15)."}],"positions":{"udlaendinge":{"score":2,"text":"Regeringsgrundlaget siger: 'Vi står fast på udlændingepolitikken, så der er styr på antallet, der kommer til Danmark – samtidig med, at vi løfter vores ansvar internationalt.' Radikale stemte for skærpede udvisningsregler (L 17 A, 3. sept. 2026) og for at gennemføre dele af EU's migrationspagt (L 15, 27. aug.), men imod forbud mod højtalerforstærket bøn (B 11) og imod forbud mod kønsopdelt svømning (B 13)."},"oekonomi":{"score":3,"text":"Partiet vil have en mere fordelende økonomi: øget beskatning af store arvesummer og en tech-skat på 1 mia. kr. årligt. Radikale har også accepteret lavere selskabsskat som del af regeringens økonomiske politik. Partiet stemte for nulmoms på bøger (L 36, 12. nov. 2026)."},"arbejdsmarked":{"score":4,"text":"Regeringsgrundlaget vil lempe modregningen for efterløn og tidlig pension og hæve Arne-pensionen med 3.162 kr. om måneden (L 98, opdateret 13. nov. 2026). Partiet vægter tryghed og uddannelse, især for dem, der mangler en uddannelse."},"velfaerd":{"score":3,"text":"Regeringen vil gøre tandpleje gratis som ambition og starter med sårbare grupper og førtidspensionister. Lovforslag L 64 indfører vederlagsfri tandpleje for kontanthjælpsmodtagere. Radikale vil have offentlig velfærd, der er lige for alle."},"sundhed":{"score":2,"text":"Regeringsgrundlaget har fokus på gratis tandpleje for sårbare grupper og på offentlig sundhed. Lovforslag L 58 gennemfører værdighedsreformen for ældreplejen."},"klima":{"score":2,"text":"Partiet vil have den hurtigste og mest vidtgående grønne omstilling. Klimaneutralitet i 2045 og 110 pct. reduktion i 2050 skal skrives ind i klimaloven, og olie- og gasfyr skal væk i 2035. Lidegaard har stillet et grønt hovedkrav til regeringen og sagt, at det ville være 'tudetosset ikke at gå den her vej' (Altinget, 20. mar. 2026)."},"natur_landbrug":{"score":2,"text":"Den grønne trepart skal fortsætte, og der skal omlægges 390.000 hektar landbrugsareal. Lovforslag L 33 gennemfører IE-ændringsdirektivet på husdyrbrugområdet. Radikale vil have en klar linje for naturen, men har også ansvar over for erhvervet."},"eu":{"score":1,"text":"Radikale er et af de mest EU-positive partier i Danmark. Regeringen vil gå forrest i det europæiske samarbejde og arbejde for europæisk autonomi."},"forsvar":{"score":4,"text":"Regeringen vil have forsvar og beredskab på mindst 5 pct. af BNP i 2030, heraf 3,5 pct. til forsvar. Radikale har accepteret det som en del af regeringsgrundlaget."},"ret":{"score":2,"text":"Regeringen vil fremsætte en udvisningsreform for kriminelle udlændinge og ændre reglerne for straffesagsgæld, så det kan betale sig at tage uddannelse eller få job efter afsoning. Radikale vægter forebyggelse og resocialisering."},"bolig":{"score":3,"text":"Boligplan 2030 med en forpligtende aftale om boligbyggeri i hovedstaden og en kommission om boligbeskatning. Radikale vil have, at boligmarkedet er fair."},"uddannelse":{"score":2,"text":"1 mia. kr. varigt til uddannelse og forskning, en tech-skat til finansiering og en ny finansiering af folkeskolen, så midlerne går til almenområdet. Lovforslag L 46 gennemfører dele af aftalen fra 6. maj 2025 om erhvervsuddannelserne. Lidegaard har kaldt uddannelse et 'absolut hovedkrav'."}},"history":[{"year":"1905","event":"Radikale Venstre stiftes 21. maj 1905 i Odense som et liberalt reformparti, der brød ud af Venstre."},{"year":"2011","event":"Radikale Venstre er med i den rød-grønne regering, hvor Martin Lidegaard bliver klima- og energiminister (2011-2014)."},{"year":"2014","event":"Lidegaard bliver udenrigsminister i 2014-2015."},{"year":"2022","event":"Efter valget i 2022 står Radikale uden for regeringen. Partiet er næsten halveret ved valget, ifølge en Altinget-kommentar fra december 2022."},{"year":"2022","event":"3. november 2022 vælges Martin Lidegaard som politisk leder."},{"year":"2026","event":"Ved valget 24. marts 2026 får Radikale 5,8 pct. og 10 mandater."},{"year":"2026","event":"3. juni 2026 præsenteres firkløverregeringen. Radikale kommer tilbage i regering med Lidegaard som erhvervsminister, Nawa som klimaminister og Stampe som kulturminister."}],"people":[{"name":"Martin Lidegaard","role":"partiformand / erhvervs- og konkurrencekraftsminister","note":"Har gjort energi og uddannelse til partiets to hovedkrav i regeringsforhandlingerne (Altinget, 20. mar. 2026)."},{"name":"Samira Nawa","role":"klima-, energi- og forsyningsminister","note":"Fik 10.372 personlige stemmer ved valget i 2026, det højeste personlige stemmetal for Radikale (lex.dk). Ansvarlig for klimapolitikken."},{"name":"Zenia Stampe","role":"kulturminister","note":"Radikale Venstre-minister for kultur og ansvarlig for Slots- og Kulturstyrelsen og Det Kongelige Teater (lex.dk)."},{"name":"Katrine Robsøe","role":"folketingsmedlem","note":"Medlem af Radikale Venstres folketingsgruppe efter valget i 2026."},{"name":"Stinus Lindgreen","role":"folketingsmedlem","note":"Medlem af Radikale Venstres folketingsgruppe efter valget i 2026."}],"voters":{"summary":"Radikale Venstres vælgere er typisk liberale og grønne, med mange offentligt ansatte og akademikere. De stemmer på partiet for europæisk samarbejde, grøn omstilling og en fair fordeling. Partiet har historisk fået stemmer fra vælgere, der vil have et midterparti uden en fast blok.","strongholds":"Radikale er typisk stærkest i de store byer, især i og omkring København og Aarhus. Partiet har færre vælgere i landdistrikterne.","demographics":"Vælgerne er typisk højtuddannede, yngre og bosiddende i byerne. Der er flere kvinder og flere offentligt ansatte end blandt Moderaterne."},"election2026":{"note":"Radikale Venstre fik 5,8 pct. og 10 mandater ved valget 24. marts 2026. Ved valget i 2022 var partiet næsten halveret (ifølge Altinget), og 2026-resultatet er en tilbagevenden. Radikale stod uden for regeringen i 2022, men er i 2026 med i regeringen efter 69 dages forhandlinger."},"strengths":["Tilbage i regering med tre ministre","Energi og uddannelse er klare kernesager med Lidegaard som erfaren forhandler","Stærk europæisk profil, der passer til regeringens EU-politik"],"weaknesses":["Kun 5,8 pct. og 10 mandater, og partiet er et af fire i regeringen","Lidegaard har sagt, at partiet ikke kan garantere klimapolitikken, bl.a. udfasningen af olie og gas efter 2042","Svært at profilere sig, når regeringen samlet har en økonomisk linje, partiet er uenig i"],"internalTensions":[{"title":"Klima versus kompromis","detail":"Lidegaard har sagt, at partiet ikke kan garantere klimapolitikken i regeringen, fordi de er et af fire partier. Det skaber spænding mellem ambitioner og kompromiser."},{"title":"Økonomisk linje","detail":"Altinget skriver, at firkløverpartierne endnu ikke er blevet enige om, hvordan regeringens økonomiske politik skal defineres. Det kan give Radikale en udfordring med at forsvare regeringens skatte- og erhvervspolitik."}],"typicalArguments":[{"claim":"Klimaet kan ikke vente. Vi skal skrive klimaneutralitet 2045 ind i loven, og det skal ske nu.","counter":"Kritikere mener, at de grønne prioriteter er for små i forhold til ambitionerne, og at klimapolitikken fylder for lidt i den samlede regeringspolitik."},{"claim":"Uddannelse er den bedste investering i fremtiden, og Danmark skal have stærke skoler og universiteter.","counter":"Kritikerne siger, at midler til folkeskolen ofte bliver brugt til at dække andre udgifter, så de ikke når almenområdet."},{"claim":"Vi er et europæisk parti, og Danmark skal være med i det europæiske samarbejde.","counter":"DF og andre EU-skeptiske partier mener, at EU tager for meget suverænitet, og at Danmark skal have større selvbestemmelse."},{"claim":"Vi vil have en fordelende økonomi, hvor de største formuer bidrager mere.","counter":"Kritikere, herunder erhvervsorganisationer, mener, at skatter på formuer og arv giver for lille råderum for erhvervslivet og investeringer."}],"vsDF":{"agree":["Nulmoms på bøger (L 36, vedtaget 12. nov. 2026): både Radikale Venstre og Dansk Folkeparti stemte for.","Udvisning af kriminelle udlændinge (L 17 A, 3. sept. 2026): både Radikale Venstre og Dansk Folkeparti stemte for skærpelsen.","Rettet indkomstmodtager (B 27, 1. okt. 2026): begge partier stemte for forslaget om, at ingen samlet skal betale mere i skat end de tjener."],"disagree":["Store bededag (B 3, 1. okt. 2026): Dansk Folkeparti stemte for at genindføre den, Radikale stemte imod.","Koranloven (B 6, 1. okt. 2026): Dansk Folkeparti stemte for at afskaffe den, Radikale stemte imod.","Kønsopdelt svømning (B 13, 3. sept. 2026): Dansk Folkeparti stemte for at forbyde den, Radikale stemte imod.","EU's migrationspagt (L 15, 27. aug. 2026): Radikale stemte for at gennemføre dele af den, Dansk Folkeparti stemte imod."],"note":"Radikale og Dansk Folkeparti er enige om skat og udvisning, men modsatte på religion, helligdage, EU-migration og kønsopdelte svømmehaller. Afstemningerne viser en klar værdikløft."},"vocabulary":[{"term":"Den grønne trepart","meaning":"Aftale mellem regeringen, landbruget og miljøorganisationer om at omlægge landbrugsjord og reducere CO2-udledningen fra landbruget."},{"term":"Tech-skat","meaning":"En ny skat på teknologivirksomheder, som regeringen vil indføre for at finansiere uddannelse og forskning (1 mia. kr. årligt)."},{"term":"Klimaneutralitet 2045","meaning":"Målet om, at Danmark ikke udleder mere CO2, end landet kan binde, i 2045. Regeringen vil indskrive det i klimaloven."},{"term":"Seniorpension","meaning":"En ordning, der giver mulighed for at gå tidligere på pension for dem, der har arbejdet længe. Regeringen vil stramme den for at finansiere Arne-pensionen fra 2027."},{"term":"Nulmoms","meaning":"Momsfritagelse, hvor virksomheden ikke opkræver moms på varen, men stadig kan trække købsmoms fra. Regeringen vil indføre nulmoms på bøger (L 36)."}],"funFacts":["Radikale Venstre blev stiftet 21. maj 1905 i Odense og er et af Danmarks ældste partier.","Samira Nawa fik 10.372 personlige stemmer ved valget i 2026, det højeste personlige stemmetal for Radikale.","Lidegaard var klima- og energiminister 2011-2014 og senere udenrigsminister, inden han i 2026 blev erhvervsminister."],"sources":[{"title":"Lex.dk: Regeringen Mette Frederiksen III (ministerliste)","url":"https://lex.dk/Regeringen_Mette_Frederiksen_III"},{"title":"Det politiske grundlag for firkløverregeringen (PDF, stm.dk)","url":"https://stm.dk/media/rc1ktdmg/det-politiske-grundlag-for-firkloeverregeringen.pdf"},{"title":"Folketinget: L 36 om nulmoms på bøger (afstemning 12. nov. 2026)","url":"https://www.ft.dk/samling/20261/lovforslag/L36/index.htm"},{"title":"Folketinget: L 73 Forslag til finanslov for 2027","url":"https://www.ft.dk/samling/20261/lovforslag/L73/index.htm"},{"title":"Folketinget: L 98 om forhøjelse af ydelsen på tidlig pension","url":"https://www.ft.dk/samling/20261/lovforslag/L98/index.htm"},{"title":"Altinget: Lidegaard stiller nyt grønt regeringskrav (20. mar. 2026)","url":"https://www.altinget.dk/klima/artikel/lidegaard-kommer-med-groent-hovedkrav-til-ny-regering-det-vil-vaere-tudetosset-ikke-at-gaa-den-her-vej"},{"title":"Altinget: Lidegaard: Her er mine tre vigtigste opgaver som erhvervsminister (3. jun. 2026)","url":"https://www.altinget.dk/forsyning/artikel/lidegaard-her-er-mine-tre-vigtigste-opgaver-som-erhvervsminister"},{"title":"Altinget: Radikales exit fra regeringsforhandlingerne er en befrielse for Lidegaard (14. dec. 2022)","url":"https://www.altinget.dk/artikel/radikales-exit-fra-regeringforhandlingerne-er-en-befrielse-for-lidegaard"},{"title":"Ritzau: Samira Nawa rejser til COP31 (6. nov. 2026)","url":"https://via.ritzau.dk/pressemeddelelse/15274516/klima-energi-og-forsyningsminister-samira-nawa-rejser-til-cop31?publisherId=9426318"},{"title":"Dansk Erhverv: Stærke tiltag for erhvervslivet i regeringens forslag til ny finanslov","url":"https://www.danskerhverv.dk/presse-og-nyheder/nyheder/2026/oktober/dansk-erhverv-starke-tiltag-for-erhvervslivet-i-regeringens-forslag-til-ny-finanslov--men-ogsa-skarpe-tidsler/"},{"title":"Da.wikipedia: Radikale Venstre","url":"https://da.wikipedia.org/wiki/Radikale_Venstre"}],"order":5,"color":"#733280","on":"#FFFFFF","blok":"rød","officialName":"Radikale Venstre","nick":"Radikale"},{"id":"m","letter":"M","name":"Moderaterne","short":"M","founded":"2022","foundedNote":"Lars Løkke Rasmussen forlod Venstre 1. januar 2021 efter en intern konflikt om partiledelsen. Navnet Moderaterne blev præsenteret 5. juni 2021, og partiet blev officielt stiftet på et stiftende årsmøde 5. juni 2022.","leader":{"name":"Lars Løkke Rasmussen","title":"Partiformand / politisk leder","since":"2022","born":"1964","bio":"Har været Venstre-formand og statsminister, før han forlod Venstre i 2021 og stiftede Moderaterne. Ved valget i 2026 var Moderaterne afgørende for flertallet, og Løkke fik stor indflydelse på regeringsdannelsen. Han er udenrigsminister i firkløverregeringen fra 3. juni 2026 (lex.dk)."},"role":"regering","roleNote":"Moderaterne sidder i firkløverregeringen sammen med Socialdemokratiet, SF og Radikale Venstre, præsenteret 3. juni 2026. Regeringen har 82 mandater og er afhængig af støtte fra Enhedslisten og Alternativet.","ideology":["liberalt","midterparti","økonomisk liberalt","vækstorienteret"],"euGroup":"Renew Europe","youth":{"name":"Unge Moderater","note":"Partiets ungdomsorganisation."},"website":"https://www.moderaterne.dk","oneLiner":"Midterparti, der vil lavere skat, vækst og en midterregering, der kan samle både rød og blå.","summary":"Moderaterne vil skabe vækst, sænke skatten på arbejde og erhverv og sikre, at velfærden kan betales. Partiet vil være bindeled mellem rød og blå side, og Løkke har været den, der afgør flertal. I firkløverregeringen har partiet fået flere erhvervs- og skatteønsker med, herunder lavere selskabsskat og afskaffelse af mellemskat og toptopskat. Det adskiller partiet fra SF og Radikale ved at lægge mere vægt på skattelettelser og arbejdsudbud, og fra de blå partier ved at sidde i en regering med S.","pitch":"Vi sørger for, at der er råd til velfærden, fordi vi skaber vækst. Vi sænker skatten for dem, der arbejder og investerer, og vi tager ansvar for, at Danmark har et stærkt erhvervsliv. Vi er den midterkraft, der kan få en regering til at fungere.","critique":"Kritikerne mener, at Moderaterne har købt sig til magt ved at gå ind i en rød regering, og at partiet ikke har fået de skattelettelser igennem, det lovede. Ifølge en Altinget-kommentar fra 22. maj 2026 har Løkke tabt magtkampen med de blå og må nu give slip på skattelettelser for at få flertal med S og SF. Dansk Folkeparti har afvist samarbejde med Moderaterne, uanset hvem der leder partiet (Ekstra Bladet via Ground News, nov. 2025).","keyIssues":[{"title":"Lavere selskabsskat og erhvervsvenlig økonomi","detail":"Regeringsgrundlaget sænker selskabsskatten med 3 procentpoint over tre år. Lempelserne finansieres bl.a. ved at fastholde chokolade- og sukkerafgiften, skære 1,5 mia. kr. i erhvervsstøtte og indføre et loft over rentefradraget på 150.000 kr. for enlige."},{"title":"Afskaffelse af mellemskat og toptopskat","detail":"Skattesystemet skal bestå af en bundskat op til 777.900 kr. og derefter en topskat på 15 procentpoint. Toptopskatten afskaffes og finansieres med en ny hovedaktionærmodel."},{"title":"Arbejdsudbud og senere tilbagetrækning","detail":"Regeringen vil lempe modregningen for efterløn og tidlig pension og sætte et mål om 35.000 flere fuldtidspersoner i strukturel beskæftigelse i 2035. Lovforslag L 98 hæver Arne-pensionen med 3.162 kr. om måneden og fastholder en tilgangsalder på 64 år for årgang 1963-1965."},{"title":"Udvisning af kriminelle udlændinge","detail":"Regeringen vil sikre, at flere kriminelle udlændinge udvises, og har fremsat en udvisningsreform. Regeringsgrundlaget siger samtidig, at regeringen vil respektere eventuelle domme fra Den Europæiske Menneskerettighedsdomstol."},{"title":"Forsvar og NATO-mål","detail":"Udgifter til forsvar og beredskab skal udgøre mindst 5 pct. af BNP i 2030, heraf 3,5 pct. til forsvar. NATO-målet indfris allerede i 2030."}],"positions":{"udlaendinge":{"score":3,"text":"Regeringsgrundlaget siger: 'Vi står fast på udlændingepolitikken, så der er styr på antallet, der kommer til Danmark – samtidig med, at vi løfter vores ansvar internationalt.' Moderaterne stemte 3. sept. 2026 for skærpede udvisningsregler (L 17 A) og 27. aug. for at gennemføre dele af EU's migrationspagt (L 15)."},"oekonomi":{"score":4,"text":"Moderaterne vil sænke selskabsskatten, afskaffe mellemskat og toptopskat og halvere momsen på fødevarer, så snart det er muligt. Løkke har selv kaldt skatte- og arbejdsudbudspolitik for 'blå politik' (Altinget, 20. aug. 2026). Partiet stemte 12. nov. 2026 for nulmoms på bøger (L 36)."},"arbejdsmarked":{"score":4,"text":"Regeringen vil lempe modregningsreglerne for efterløn og tidlig pension, give mulighed for at sætte ratepension på pause og udvide pensionsudbetalingsalderen til fem år før folkepensionsalderen. Store bededag genindføres som helligdag fra 2030, og Moderaterne stemte imod at genindføre den straks (B 3, 1. okt. 2026)."},"velfaerd":{"score":3,"text":"Regeringen har som ambition, at tandpleje skal være gratis for alle, og starter med sårbare grupper og førtidspensionister. Lovforslag L 64 indfører vederlagsfri tandpleje for kontanthjælpsmodtagere. Der afsættes 5 mia. kr. varigt til 'Børnenes Danmark'."},"sundhed":{"score":3,"text":"Regeringsgrundlaget lægger vægt på offentligt finansieret sundhed og gratis tandpleje. Der er ikke lagt op til privat inddragelse i sundhedsvæsenet i regeringsgrundlaget. Lovforslag L 58 gennemfører værdighedsreformen for ældreplejen."},"klima":{"score":3,"text":"Regeringen vil indskrive klimaneutralitet i 2045 og 110 pct. reduktion i 2050 i klimaloven samt en reduktion på mindst 85 pct. i 2035. Regeringsgrundlaget vægter vækst og erhvervslivets konkurrenceevne højt ('Vi skal sikre vækst i økonomien')."},"natur_landbrug":{"score":3,"text":"Den grønne trepart skal fortsætte, og der skal omlægges 390.000 hektar landbrugsareal. Regeringen vil udfase gas- og oliefyr, så der i 2035 ikke er boliger, der opvarmes med naturgas eller olie. Moderaterne stemte 3. sept. 2026 for L 5 om næringsstoffer i land- og skovbrug."},"eu":{"score":1,"text":"Regeringsgrundlaget siger, at Danmark 'går forrest i det europæiske samarbejde'. Moderaterne har foreslået en ny vækstpagt for EU med ti forslag (Altinget)."},"forsvar":{"score":5,"text":"Forsvar og beredskab skal udgøre mindst 5 pct. af BNP i 2030, heraf 3,5 pct. til forsvar. NATO-målet indfris allerede i 2030."},"ret":{"score":3,"text":"Regeringen vil fremsætte en udvisningsreform for kriminelle udlændinge og flere midler til politiet. Den vil ændre reglerne for straffesagsgæld, så det i højere grad kan betale sig at tage en uddannelse eller få et job efter afsoning."},"bolig":{"score":3,"text":"Regeringen vil lave en 'Boligplan 2030' med en forpligtende aftale om boligbyggeri i hovedstaden og en kommission om en ny boligbeskatning. Boligmarkedet skal i højere grad fungere efter markedsvilkår, med særlig støtte til unge og studerende."},"uddannelse":{"score":3,"text":"Regeringen vil afsætte 1 mia. kr. varigt til uddannelse og forskning og indføre en tech-skat på 1 mia. kr. årligt. Lovforslag L 5 forhøjer SU-fribeløbet for elever på ungdomsuddannelser, og L 46 gennemfører dele af erhvervsuddannelsesaftalen fra 2025."}},"history":[{"year":"2021","event":"Lars Løkke Rasmussen forlader Venstre 1. januar 2021 efter en intern konflikt om partiledelsen og starter en politisk forening."},{"year":"2021","event":"Navnet Moderaterne præsenteres 5. juni 2021 som navn på det nye midterparti."},{"year":"2022","event":"Moderaterne stiftes officielt på et stiftende årsmøde den 5. juni 2022."},{"year":"2025","event":"I november 2025 afviser Dansk Folkeparti samarbejde med Moderaterne, uanset om Løkke er leder (Ekstra Bladet via Ground News)."},{"year":"2026","event":"Ved folketingsvalget 24. marts 2026 får Moderaterne 14 mandater (7,7 pct.) og bliver afgørende for, hvem der kan danne regering."},{"year":"2026","event":"22. maj 2026 opgiver Troels Lund Poulsen at danne en blå regering, efter at Løkke har afvist at støtte den (Altinget)."},{"year":"2026","event":"3. juni 2026 præsenteres firkløverregeringen efter 69 dage. Moderaterne får Løkke som udenrigsminister, Jakob Engel-Schmidt som minister for skatte- og vækst og Monika Rubin som socialminister (lex.dk)."},{"year":"2026","event":"6. oktober 2026 trækker Alternativet støtten til Henrik Frandsen (M) som formand for Folketinget."},{"year":"2026","event":"12. nov. 2026 vedtages L 36 om nulmoms på bøger og afskaffelse af kaffeafgiften, med stemmer fra Moderaterne."}],"people":[{"name":"Lars Løkke Rasmussen","role":"partiformand / udenrigsminister","note":"Afgørende for regeringsdannelsen i 2026 og den person, der har sat kursen for Moderaterne siden 2021."},{"name":"Jakob Engel-Schmidt","role":"minister for skatte- og vækstministeriet","note":"Står for skatte- og vækstområdet, herunder skattereformen og de nye skattelettelser (lex.dk)."},{"name":"Henrik Frandsen","role":"folketingsmedlem","note":"Blev i oktober 2026 udpeget som kandidat til formand for Folketinget, men mistede Alternativets støtte."},{"name":"Lars Aagaard","role":"folketingsmedlem og tidligere klimaminister","note":"Har været klimaminister og er nu en del af Moderaternes folketingsgruppe."},{"name":"Monika Rubin","role":"socialminister og minister for nordisk samarbejde","note":"Repræsenterer Moderaterne på det sociale område i regeringen (lex.dk)."}],"voters":{"summary":"Moderaternes vælgere er typisk midterorienterede og skattebevidste. De stemmer på partiet, fordi de vil have vækst og lavere skat uden en ren blå regering. Mange kommer fra Venstre og Konservative. Partiet kan også tiltrække vælgere, der er trætte af blokpolitik.","strongholds":"Moderaterne har ingen klar geografisk hovedbastion. Støtten er spredt over hele landet, og partiet er ofte stærkest i de dele af landet, hvor Venstre har haft sine bedste resultater.","demographics":"Vælgerne er typisk erhvervsaktive midaldrende og ældre med mellemlange eller lange uddannelser. Partiet har en tendens til flere mænd og flere vælgere med erhvervsbaggrund end RV og ALT."},"election2026":{"note":"Moderaterne fik 7,7 pct. og 14 mandater ved valget 24. marts 2026, og partiets mandater blev afgørende for, hvem der kunne danne regering. Løkke valgte at gå sammen med S, SF og Radikale i stedet for en blå regering under Troels Lund Poulsen. Altinget skriver, at Løkke ikke havde den stærkeste forhandlingsposition over for den blå side, og at blå kommentatorer mener, at han tabte magtkampen."},"strengths":["Afgørende placering i Folketinget efter valget 2026","Har fået skatte- og erhvervsønsker igennem i regeringsgrundlaget","Løkke er erfaren og kan samle både rød og blå side"],"weaknesses":["Lille parti med 7,7 pct. og 14 mandater","Svært at få skattelettelser igennem i en regering med S og SF","Kan opfattes som et parti, der har skiftet side, og som DF afviser at samarbejde med"],"internalTensions":[{"title":"Blå eller rød kurs","detail":"Løkke har afvist en blå regering under Troels Lund Poulsen, men kalder samtidig skattepolitik for 'blå politik'. Det skaber spænding mellem midterlinje og blå identitet."},{"title":"Økonomisk fortælling","detail":"Altinget skriver, at firkløverpartierne endnu ikke er blevet enige om, hvordan regeringens økonomiske politik skal defineres. Det kan give konflikt om, hvem der bestemmer kursen."}],"typicalArguments":[{"claim":"Vi sænker skatten på arbejde og erhverv, og det skaber vækst, der kan betale velfærden.","counter":"Kritikere peger på, at lavere selskabsskat og afskaffelse af toptopskatten primært giver mest til de rigeste, og at finansieringen er usikker."},{"claim":"Vi står fast på udlændingepolitikken, så antallet styres, og vi overholder internationale forpligtelser.","counter":"Dansk Folkeparti mener, at regeringens udlændingepolitik ikke er stram nok, og at alle partier bag regeringen holder fast i et system, der underminerer udlændingepolitikken (Pia Kjærsgaard, Altinget)."},{"claim":"Vi har været med til at samle en regering, der kan få flertal, og som ikke kun er blå eller rød.","counter":"Blå kommentatorer mener, at Løkke har tabt magtkampen med de blå, og at han nu må give slip på skattelettelser for at få flertal med S og SF (Helle Ib, Altinget, 22. maj 2026)."},{"claim":"Arne-pensionen løftes med 3.162 kr. om måneden fra 2027, fordi det er rimeligt for dem, der har slidt.","counter":"Dansk Folkeparti afviser at stramme seniorpensionen, som er en del af finansieringen. Enhedslisten siger, at de ikke vil forringe seniorpensionen (sn.dk, 9. okt. 2026)."},{"claim":"Vi vil have en grøn omstilling, der ikke koster vækst.","counter":"Kritikere mener, at klimapolitikken fylder for lidt i den samlede regeringspolitik, og at vækst og klima ikke trækker samme vej."}],"vsDF":{"agree":["Nulmoms på bøger (L 36, vedtaget 12. nov. 2026): både Moderaterne og Dansk Folkeparti stemte for.","Udvisning af kriminelle udlændinge (L 17 A, 3. sept. 2026): både Moderaterne og Dansk Folkeparti stemte for skærpelsen.","Rettet indkomstmodtager (B 27, 1. okt. 2026): begge partier stemte for forslaget om, at ingen samlet skal betale mere i skat end de tjener."],"disagree":["Store bededag (B 3, 1. okt. 2026): Dansk Folkeparti stemte for at genindføre den, Moderaterne stemte imod.","Koranloven (B 6, 1. okt. 2026): Dansk Folkeparti stemte for at afskaffe den, Moderaterne stemte imod.","Kønsopdelt svømning (B 13, 3. sept. 2026): Dansk Folkeparti stemte for at forbyde den, Moderaterne stemte imod.","EU's migrationspagt (L 15, 27. aug. 2026): Moderaterne stemte for at gennemføre dele af den, Dansk Folkeparti stemte imod."],"note":"Moderaterne og Dansk Folkeparti stemmer sammen om skat og udvisning, men er modsatte på religion, forsvar af helligdage, EU-migration og seniorpension. Det er den mest konkrete uenighed i de seneste afstemninger."},"vocabulary":[{"term":"Blå politik","meaning":"Løkkes betegnelse for skattelettelser og tiltag, der øger arbejdsudbuddet. Han sagde i august 2026, at økonomisk politik med skattelettelser er 'blå politik' (Altinget)."},{"term":"Firkløverregeringen","meaning":"Det uofficielle navn for regeringen S, SF, M og Radikale Venstre, præsenteret 3. juni 2026."},{"term":"Mellemskat og toptopskat","meaning":"Mellemskatten er et skattetrin mellem bundskat og topskat. Toptopskatten er en ekstra skat for de højeste indkomster. Begge skal afskaffes ifølge regeringsgrundlaget."},{"term":"Seniorpension","meaning":"En ordning, der giver mulighed for at gå tidligere på pension for dem, der har arbejdet længe. Regeringen vil stramme den for at finansiere Arne-pensionen fra 2027."},{"term":"Arne-pension","meaning":"Tidlig pension for dem, der har slidt sig op i nedslidende job. Regeringen hæver ydelsen med 3.162 kr. om måneden (L 98)."},{"term":"Kongerunde","meaning":"Et møde, hvor en kongelig undersøger drøfter med partierne, hvem der kan danne regering. Regeringsdannelsen i 2026 havde tre kongerunder."}],"funFacts":["Moderaterne fik 14 mandater ved valget 24. marts 2026, og Altinget skriver, at partiets mandater var afgørende for flertallet.","Regeringsdannelsen tog 69 dage og tre kongerunder. Altinget skriver, at forhandlingerne var de længste nogensinde efter et folketingsvalg.","Løkke nominerede Troels Lund Poulsen som kongelig undersøger i maj 2026, men Troels Lund opgav at danne en blå regering den 22. maj 2026."],"sources":[{"title":"Lex.dk: Regeringen Mette Frederiksen III (ministerliste)","url":"https://lex.dk/Regeringen_Mette_Frederiksen_III"},{"title":"Det politiske grundlag for firkløverregeringen (PDF, stm.dk)","url":"https://stm.dk/media/rc1ktdmg/det-politiske-grundlag-for-firkloeverregeringen.pdf"},{"title":"Folketinget: Afstemninger i folketingsåret 2026-27 (oda.ft.dk)","url":"https://www.ft.dk/samling/20261/beslutningsforslag/B3/index.htm"},{"title":"Folketinget: L 73 Forslag til finanslov for 2027","url":"https://www.ft.dk/samling/20261/lovforslag/L73/index.htm"},{"title":"Folketinget: L 98 om forhøjelse af ydelsen på tidlig pension","url":"https://www.ft.dk/samling/20261/lovforslag/L98/index.htm"},{"title":"Altinget: Løkke afviser at ny regering trækker økonomien i en rødere retning (20. aug. 2026)","url":"https://www.altinget.dk/artikel/loekke-afviser-at-ny-regering-traekker-oekonomien-i-en-roedere-retning-vi-skaerper-ambitionerne-paa-blaa-markoerer"},{"title":"Altinget: Løkke tabte magtkampen med de blå (Helle Ib, 22. maj 2026)","url":"https://www.altinget.dk/christiansborg/artikel/loekke-tabte-magtkampen-med-de-blaa-nu-bliver-hans-sejre-paa-de-roedes-naade"},{"title":"Altinget: Alternativet trækker støtten til Henrik Frandsen som ny folketingsformand (6. okt. 2026)","url":"https://www.altinget.dk/artikel/alternativet-traekker-stoetten-til-henrik-frandsen-foer-aabning"},{"title":"sn.dk: Forligspartier og EL siger nej til strammere krav for seniorpension (9. okt. 2026)","url":"https://www.sn.dk/art6658489/koebenhavn-kommune/politik/forligspartier-og-el-siger-nej-til-strammere-krav-for-seniorpension"},{"title":"Dansk Erhverv: Stærke tiltag for erhvervslivet i regeringens forslag til ny finanslov","url":"https://www.danskerhverv.dk/presse-og-nyheder/nyheder/2026/oktober/dansk-erhverv-starke-tiltag-for-erhvervslivet-i-regeringens-forslag-til-ny-finanslov--men-ogsa-skarpe-tidsler/"},{"title":"Da.wikipedia: Moderaterne","url":"https://da.wikipedia.org/wiki/Moderaterne"}],"order":6,"color":"#B48CD2","on":"#12161C","blok":"midten","officialName":"Moderaterne","nick":"Moderaterne"},{"id":"v","letter":"V","name":"Venstre","short":"V","founded":"1870","foundedNote":"Venstre blev stiftet i 1870 som den politiske bevægelse for bønder, husmænd og andre, der ville have indflydelse på Christiansborg. Partiet fik sin nuværende form i 1910.","leader":{"name":"Troels Lund Poulsen","title":"Formand for Venstre","since":"2023","born":"1976","bio":"Troels Lund Poulsen er født 30. marts 1976 i Vejle. Han blev formand for Venstre 18. november 2023, efter Jakob Ellemann-Jensen. Han har været forsvarsminister i tidligere regeringer. Efter valget 24. marts 2026 fik han til opgave at forsøge at danne en borgerlig regering, men forhandlingerne brød sammen i slutningen af maj 2026, og Venstre gik i opposition. Han er fortsat formand efter landsmødet i Herning 13.-14. november 2026, hvor han fik stående ovationer."},"role":"opposition","roleNote":"Venstre er i opposition til firkløverregeringen (Socialdemokratiet, SF, Moderaterne og Radikale Venstre), som er en mindretalsregering siden 3. juni 2026. Partiet skal finde flertal for hver sag.","ideology":["liberalisme","borgerlig midte","erhvervs- og landbrugsvenligt","retssikkerhed og tryghed"],"euGroup":"Forny Europa (Renew Europe)","youth":{"name":"Venstres Ungdom","note":"Partiets ungdomsorganisation for unge medlemmer."},"membersCount":"20.336 (2024)","website":"https://www.venstre.dk","oneLiner":"Liberal, erhvervs- og landbrugsvenligt borgerligt parti i opposition, der kæmper for at vinde tilbage efter et historisk dårligt valg.","summary":"Venstre vil have et Danmark, hvor borgerne har frihed til at klare sig selv, og hvor skatten er lav nok til, at det kan betale sig at arbejde og drive virksomhed. Partiet står for en stram udlændingepolitik, retssikkerhed og tryghed, og har traditionelt været tæt på landbruget. Venstre har samtidig taget en grøn omstilling til sig som en del af sin profil, men Troels Lund Poulsen har sagt, at partiet ikke giver regeringen en blankocheck. Over for Liberal Alliance og Konservative er Venstre mere midterorienteret og vil samarbejde med de andre borgerlige partier om en regering. Partiet var i SVM-regeringen, og det har været en belastning for dets vælgertilslutning.","pitch":"Venstre vil have et Danmark, hvor folk kan klare sig selv, og hvor staten hjælper dem, der har brug for det, uden at blande sig i alt. Vi har været i regering og ved, hvordan man får ting gennemført. Vi vil skabe bedre rammer for virksomheder og landmænd og holde styr på udgifterne, så vi har råd til velfærden.","critique":"Modstanderne siger, at Venstre har mistet sin retning. Partiet sad i SVM-regeringen, og mange borgerlige vælgere så det som et løftebrud. Kritikerne peger på, at partiet er presset mellem Liberal Alliance og Socialdemokratiet, og at det har svært ved at vinde vælgere tilbage efter valget 2026. De peger også på intern splid om landbrugspolitikken, som har svækket partiet yderligere.","keyIssues":[{"title":"Landbrug og gødskningsloven","detail":"Venstre stemte for gødskningsloven i september 2026, som fastsætter kvoter for landbrugets kvælstofudledning. Fem af partiets 18 folketingsmedlemmer stemte imod partilinjen. Kritikken fra landbrugets bagland har været kraftig, bl.a. mod kvælstofreguleringen og mod et sprøjteforbud uden kompensation."},{"title":"Grøn omstilling med troværdighed","detail":"På landsmødet i november 2026 talte Troels Lund Poulsen om en 'grøn rejse' og om at genvinde 'grøn troværdighed'. Han sagde, at Venstre ikke giver regeringen en blankocheck, men at partiet mener, at et nationalt sprøjteforbud er nødvendigt."},{"title":"Skat og retfærdighed i skatten","detail":"Venstres forslag B 27 om rette indkomstmodtager og sikring af, at ingen samlet betaler mere i skat, end de tjener, blev vedtaget uændret i 2. behandling 1. oktober 2026. Forslaget handler om dobbeltbeskatning. Partiet vil have lavere skat på arbejde og virksomheder."},{"title":"Blå statsminister og borgerlig regering","detail":"Venstre har peget på Troels Lund Poulsen som borgerlig statsministerkandidat. Efter valget forsøgte han at danne en borgerlig regering med Liberal Alliance og Konservative, men forhandlingerne brød sammen i maj 2026. Partiet kræver fortsat en blå regering frem for en regering ledet af Socialdemokratiet."},{"title":"Mindre stat og effektiv offentlig sektor","detail":"Venstre vil have en mindre og mere effektiv offentlig sektor og mere frihed for borgerne, bl.a. i sundhed og uddannelse."}],"positions":{"udlaendinge":{"score":4,"text":"Venstre vil have en stram udlændingepolitik med krav til integration, arbejde og hurtig udvisning af kriminelle udlændinge. Partiet har været med til at stramme reglerne i SVM-perioden."},"oekonomi":{"score":4,"text":"Venstre vil have lavere skat og mindre stat, og vil have det til at betale sig at arbejde og drive virksomhed. Partiet står for en stabil økonomi og en disciplineret offentlig sektor."},"arbejdsmarked":{"score":4,"text":"Venstre vil have flere i arbejde og er åben for reformer, der øger arbejdsudbuddet, uden at fjerne den danske model med trygge overenskomster."},"velfaerd":{"score":4,"text":"Venstre vil have en velfærd med fokus på resultater og effektivisering og mere valgfrihed for borgerne. Partiet vil bevare det offentlige velfærdssystem, men er åbent for privat medvirken."},"sundhed":{"score":4,"text":"Venstre vil have en offentlig sundhedssektor, men er åben for privat medvirken og valgfrihed, især hvor ventetiderne er lange."},"klima":{"score":3,"text":"Venstre støtter den grønne omstilling, men vil have den til at ramme erhvervsliv og forbrugere så lidt som muligt. Partiet er ved at genvinde sin grønne troværdighed efter splittelsen om gødskningsloven."},"natur_landbrug":{"score":4,"text":"Venstre står for landbrugets interesser og vil have færre og mere forudsigelige krav til landmænd. Partiet stemte for gødskningsloven i september 2026, men har været splittet om kvælstofreguleringen."},"eu":{"score":2,"text":"Venstre er positiv over for EU og det indre marked og er ikke EU-skeptisk. Partiet er medlem af Renew Europe-gruppen i Europa-Parlamentet."},"forsvar":{"score":5,"text":"Venstre vil styrke forsvaret og støtter oprustning, men er ikke det mest ambitiøse parti i den borgerlige blok."},"ret":{"score":4,"text":"Venstre vil have hårdere straf for alvorlig kriminalitet og mere politi, og lægger vægt på tryghed. Samtidig vil partiet have retssikkerhed for borgerne."},"bolig":{"score":4,"text":"Venstre vil have mere marked på boligområdet og færre reguleringer, og vil have kommunerne til at give plads til byggeri."},"uddannelse":{"score":4,"text":"Venstre vil have krav og valgfrihed i uddannelsessystemet og vil give institutionerne mere frihed."}},"history":[{"year":"1870","event":"Venstre stiftes som bevægelse for bønder, husmænd og andre, der ville have indflydelse på Christiansborg."},{"year":"1910","event":"Venstre får sin nuværende form."},{"year":"2021","event":"Stephanie Lose vælges til næstformand i Venstre, efter at Inger Støjberg trådte tilbage."},{"year":"2022","event":"Venstre får 13,3 % og 23 mandater ved folketingsvalget 2022."},{"year":"2023","event":"18. november 2023 bliver Troels Lund Poulsen formand for Venstre, efter Jakob Ellemann-Jensen."},{"year":"2026","event":"Venstre får 10,1 % og 18 mandater ved folketingsvalget 24. marts 2026. Det er partiets dårligste valgresultat i historien."},{"year":"2026","event":"Efter valget forsøger Troels Lund Poulsen at danne en borgerlig regering med LA og Konservative. Forhandlingerne bryder sammen i slutningen af maj 2026, og Venstre går i opposition til firkløverregeringen fra 3. juni 2026."},{"year":"2026","event":"1. oktober 2026: Venstres forslag B 27 om rette indkomstmodtager og skat vedtages uændret i 2. behandling."},{"year":"2026","event":"5. oktober 2026: Venstres målinger i Voxmeter er 5,9 % (feltarbejde 28. september - 4. oktober), og partiet er splittet om gødskningsloven."},{"year":"2026","event":"25. oktober 2026: Hovedbestyrelsen bakker op om ledelsen og forventer, at folketingsgruppen stemmer samlet. 27. oktober 2026 udelukkes Preben Bang Henriksen fra folketingsgruppen."},{"year":"2026","event":"13.-14. november 2026: Venstres landsmøde i Herning. Troels Lund Poulsen afviser Anders Fogh Rasmussens forslag om at fusionere liberale partier."}],"people":[{"name":"Troels Lund Poulsen","role":"Formand","note":"Partiets leder siden 2023 og borgerlig statsministerkandidat efter valget 2026."},{"name":"Stephanie Lose","role":"Næstformand","note":"Næstformand siden 2021, og kritiseret af flere lokalforeninger i november 2026. Formanden har støttet hende skriftligt."},{"name":"Marie Brixtofte","role":"Folketingsmedlem","note":"Fremsatte sammen med Morten Dahlin forslaget B 27 om skat, som blev vedtaget 1. oktober 2026."},{"name":"Preben Bang Henriksen","role":"Løsgænger (udelukket fra gruppen 27. oktober 2026)","note":"Stemte imod partilinjen i gødskningsloven og blev udelukket fra folketingsgruppen, fordi han ikke ville love at stemme med flertallet."},{"name":"Amanda Heitmann","role":"Folketingsmedlem","note":"Stemte imod partilinjen i gødskningsloven i september 2026 og har efterfølgende sagt, at hun vil følge gruppens beslutninger."},{"name":"Anni Matthiesen","role":"Folketingsmedlem","note":"Stemte imod partilinjen i gødskningsloven i september 2026 og har efterfølgende tilsluttet sig gruppens linje."}],"voters":{"summary":"Venstre har historisk haft en bred vælgerbase blandt borgerlige landmænd, selvstændige og middelklassen. Siden 2022 og især efter 2026 er mange vælgere gået til Liberal Alliance og Konservative. Ifølge Altinget har LA overtaget mange utilfredse Venstre-vælgere.","strongholds":"Landdistrikterne og de jyske landområder har traditionelt været stærke for Venstre.","demographics":"Ældre vælgere og landbrugets erhverv er en vigtig del af Venstres vælgerbase. Partiet har mistet tilslutning blandt yngre og i storbyerne."},"election2026":{"note":"Venstre fik 10,1 % og 18 mandater ved valget 24. marts 2026, mod 13,3 % og 23 mandater i 2022. Tabet skyldes, at partiet gik ind i SVM-regeringen, og at mange borgerlige vælgere løb til LA. Efter valget er partiet i opposition og står i målingerne på omkring 6 %. I november 2026 er folketingsgruppen 17 mandater, efter at Søren Gade forlod folketinget i oktober 2026 og Preben Bang Henriksen blev udelukket."},"strengths":["Erfaring fra regeringsmagt og kendskab til Christiansborg","Stærk tradition i landdistrikterne og blandt landbruget","Troels Lund Poulsen har stående ovationer på landsmødet i november 2026 og et bredt netværk i den blå blok","Klar borgerlig profil på skat, erhverv og retssikkerhed"],"weaknesses":["Historisk lav tilslutning i målinger og tab af vælgere til LA","Intern splid om landbrugspolitik og gødskningsloven","Uklar profil efter SVM-perioden","Svært ved at tiltrække yngre vælgere"],"internalTensions":[{"title":"Gødskningsloven og landbrugets vilkår","detail":"Fem folketingsmedlemmer stemte imod partilinjen i september 2026. Det har vist en splid om, hvor hårdt partiet skal forsvare landbrugets interesser over for klimakrav."},{"title":"Lokalforeninger mod Stephanie Lose","detail":"I november 2026 kritiserer lokalforeninger i Sønderjylland og andre steder næstformanden for at have for lidt kontakt til medlemmerne, og for at have fokus på Christiansborg. Troels Lund Poulsen har støttet hende skriftligt."},{"title":"Fusion med andre liberale partier","detail":"Anders Fogh Rasmussen foreslog i november 2026, at Venstre, LA, Moderaterne og Danmarksdemokraterne skal samles i ét parti. Troels Lund Poulsen har afvist det."}],"typicalArguments":[{"claim":"Vi er det eneste borgerlige parti med erfaring fra regeringsmagt, og vi ved, hvordan man får ting gennemført.","counter":"Netop SVM-regeringen er for mange vælgere et løftebrud, og erfaring er ikke nok, hvis partiet ikke har en tydelig retning."},{"claim":"Skatten skal ned, så det kan betale sig at arbejde og drive virksomhed. Ingen skal betale mere i skat, end de tjener.","counter":"Lavere skat kan give mindre plads til velfærd, og kritikere mener, at det især gavner de rigeste."},{"claim":"Landbruget skal have rimelige vilkår, og reguleringen skal være til at leve med.","counter":"Kritikere mener, at landbrugets udledninger af kvælstof og CO2 kræver hårdere regulering, og at det ikke kan udsættes."},{"claim":"Vi er et ansvarligt parti, der vil samarbejde i den blå blok og ikke vil stille urealistiske krav.","counter":"Kritikere mener, at Venstre har vist uklarhed i sin linje og er svækket af, at partiet har stemt for regler, som dets egne vælgere ikke bakker op om."}],"vsDF":{"agree":["Begge partier vil have en stram udlændingepolitik og krav til integration","Begge står for en borgerlig regering frem for en regering ledet af Socialdemokratiet"],"disagree":["Venstre er positiv over for EU og det indre marked, mens DF er EU-skeptisk","Venstre er mere liberal i økonomien og vil have lavere skat og mindre stat, mens DF lægger større vægt på velfærd og ældre"],"note":"Venstre og DF er begge borgerlige partier, men de adskiller sig især i EU-spørgsmålet og i velfærdspolitikken. I november 2026 indgik regeringen en skatteaftale med DF, som Liberal Alliance kritiserede, og Venstre var ikke en del af aftalen."},"vocabulary":[{"term":"Borgerlig midte","meaning":"Det begreb Venstre bruger om sig selv: et parti mellem den konservative højre og det liberale midterfelt."},{"term":"Blå statsminister","meaning":"Kravet om, at en borgerlig politiker skal være statsminister efter næste valg."},{"term":"Grøn troværdighed","meaning":"Troels Lund Poulsens begreb for, at Venstre skal kunne stå ved sin grønne politik over for både erhvervsliv og landbrug."}],"funFacts":["Venstre er et af Danmarks ældste partier, stiftet i 1870.","Venstre fik 10,1 % ved valget i marts 2026, men er i målingerne i efteråret 2026 nede på omkring 6 %."],"sources":[{"title":"Venstre hænger fast i lav Voxmeter-tilslutning efter intern splid (Frederiksborg Amtsavis)","url":"https://frederiksborgamtsavis.sn.dk/article/6655246/politik/venstre-haenger-fast-i-lav-voxmeter-tilslutning-efter-intern-splid"},{"title":"Regeringen præsenterer finanslovsforslag med sikkerhedsfokus (Frederiksborg Amtsavis, 9. okt. 2026)","url":"https://frederiksborgamtsavis.sn.dk/article/6658310/politik/regeringen-praesenterer-finanslovsforslag-med-sikkerhedsfokus"},{"title":"Venstre (Wikipedia)","url":"https://da.wikipedia.org/wiki/Venstre"},{"title":"Folketingsvalget 2026 (Wikipedia)","url":"https://da.wikipedia.org/wiki/Folketingsvalget_2026"},{"title":"Folketingsvalget 2022 (Wikipedia)","url":"https://da.wikipedia.org/wiki/Folketingsvalget_2022"},{"title":"Troels Lund Poulsen (Wikipedia)","url":"https://da.wikipedia.org/wiki/Troels_Lund_Poulsen"},{"title":"Hovedbestyrelsen bakker op om Venstres ledelse (TV 2, 25. okt. 2026)","url":"https://nyheder.tv2.dk/live/politik/2026-10-25-venstre-holder-ekstraordinaert-hovedbestyrelsesmoede"},{"title":"Preben Bang Henriksen færdig i Venstre (TV 2, 27. okt. 2026)","url":"https://nyheder.tv2.dk/politik/2026-10-27-preben-bang-henriksen-faerdig-i-venstre"},{"title":"Søren Gade stopper i Folketinget (DR)","url":"https://www.dr.dk/nyheder/politik/soeren-gade-stopper-i-folketinget"},{"title":"Beslutningsforslag B 27: rette indkomstmodtager og sikring af, at ingen samlet betaler mere i skat (Lovguiden)","url":"https://www.lovguiden.dk/folketinget/sager/beslutningsforslag/105576"},{"title":"Denmark Liberal Leader Takes Over Coalition Talks After PM Fails (Bloomberg, 9. maj 2026)","url":"https://www.bloomberg.com/news/articles/2026-05-09/denmark-liberal-leader-takes-over-coalition-talks-after-pm-fails"},{"title":"Denmark's centre-right coalition talks break down (The Star, 23. maj 2026)","url":"https://www.thestar.com.my/news/world/2026/05/23/denmark039s-centre-right-coalition-talks-break-down-prolonging-political-deadlock"}],"order":8,"color":"#254264","on":"#FFFFFF","blok":"blå","officialName":"Venstre, Danmarks Liberale Parti","nick":"Venstre"},{"id":"la","letter":"I","name":"Liberal Alliance","short":"LA","founded":"2008","foundedNote":"Liberal Alliance blev stiftet 28. august 2008. Partiets forløber, Ny Alliance, blev stiftet 7. maj 2007. LA er et markedsliberalt parti med fokus på lavere skat, mindre stat og personlig frihed.","leader":{"name":"Alex Vanopslagh","title":"Politisk leder for Liberal Alliance","since":"2019","born":"1991","bio":"Alex Vanopslagh er født 17. oktober 1991 i Frankrig. Han blev valgt til politisk leder for Liberal Alliance 9. juni 2019, med opbakning fra partiets folketingsgruppe. Han var tidligere formand for Liberal Alliances Ungdom. Partiet nåede over 15 % i målingerne i maj 2024, faldt herefter, og fik 9,4 % ved valget i 2026. Han er kendt for sin kampagne på TikTok, og han har sagt, at han vil være statsminister, hvis LA bliver det største blå parti."},"role":"opposition","roleNote":"LA er i opposition til firkløverregeringen (S, SF, M og RV). Partiet har krævet en blå statsminister og har kritiseret regeringens skatteaftale med Dansk Folkeparti i november 2026.","ideology":["liberalisme","markedsøkonomi","frihed og individ","forsvar og oprustning"],"euGroup":"EPP (Det Europæiske Folkeparti)","youth":{"name":"Liberal Alliances Ungdom (LAU)","note":"Partiets ungdomsorganisation. Landsformand Tobias Jæger Pagh talte ved landsmødet 11. april 2026."},"membersCount":"6.742 (2024)","website":"https://www.liberalalliance.dk","oneLiner":"Markedsliberalt parti med fokus på lavere skat, mindre stat og frihed, der har vokset blandt unge og vil lede den blå blok.","summary":"Liberal Alliance vil have lavere skat, mindre offentlig sektor og mere frihed for borgerne. Partiet vil have marked og konkurrence på områder som sundhed, uddannelse og boliger, og vil have en stærk stat i kerneopgaver som retssikkerhed og forsvar. LA er mere markedsliberal og mindre traditionelt konservativ end Venstre og Konservative. Partiet har særligt vundet opbakning blandt unge vælgere, både ved valget 2026 og i den digitale kampagne, og det vil lede den blå blok.","pitch":"Liberal Alliance vil have et Danmark med mere frihed, lavere skat og en mindre stat, der ikke blander sig i alt. Vi har vist, at unge og borgere vil have liberale løsninger. Vi vil have en blå regering, der leverer på skat, erhverv og ansvar, og vi venter ikke på, at andre tør.","critique":"Modstanderne siger, at LA's skattelettelser og fokus på marked rammer de svageste og svækker velfærden. Kritikerne peger på, at LA har en hård og polariserende stil, og at partiet tabte vælgere i 2024 efter debatten om kvindelig værnepligt. De mener også, at partiets statsministerdrøm splitter den blå blok, og at partiet er sårbart, fordi det er tæt knyttet til sin leder.","keyIssues":[{"title":"Lavere skat og mindre stat","detail":"LA vil have lavere skat på arbejde og virksomheder og en mindre offentlig sektor. Partiet mener, at det skal kunne betale sig at arbejde, og at den offentlige sektor skal effektiviseres. LA kritiserede i november 2026 regeringens skatteaftale med DF, fordi den ifølge LA gav DF lettelser på benzin og diesel i stedet for varige skattelettelser."},{"title":"Forsvar og oprustning","detail":"LA har fremlagt en finansieret oprustningsplan for forsvaret og argumenterer for, at forsvaret skal prioriteres over udgifter til velfærd. Det er en af partiets centrale mærkesager."},{"title":"Blå statsminister og blå blok","detail":"LA og Danmarksdemokraterne har stillet et ultimativt krav om en blå statsminister, ifølge Altinget 12. maj 2026. Vanopslagh har sagt, at han vil være statsminister, hvis LA bliver det største blå parti."},{"title":"Stram asyl- og udlændingepolitik","detail":"LA har i november 2026 fremsat forslag om at ophæve retten til at søge spontant asyl for personer uden for Danmarks nærområde (B 54), om at flygtninge ikke må få permanent opholdstilladelse direkte efter flygtningeopholdet (B 55), og om at trossamfund ikke må modtage kontante donationer på 15.000 kr. eller derover (B 56)."},{"title":"Frihed for unge og digital kampagne","detail":"LA har vundet opbakning blandt unge vælgere, bl.a. via TikTok. Partiet vil have frihed i uddannelse og boligmarkedet og har fremsat forslaget B 48 om at lovliggøre salg af håndkøbsmedicin via digitale platforme og leveringstjenester."}],"positions":{"udlaendinge":{"score":4,"text":"LA vil have en stram udlændingepolitik. I november 2026 fremsatte partiet forslag om at ophæve retten til spontan asyl for personer uden for Danmarks nærområde (B 54) og om at stoppe direkte overgang fra flygtningestatus til permanent opholdstilladelse (B 55)."},"oekonomi":{"score":5,"text":"LA vil have lavest mulig skat og mindst mulig stat. Partiet vil have skattelettelser på arbejde og virksomheder og vil begrænse offentlige udgifter. Partiet kritiserede regeringens skatteaftale med DF i november 2026, fordi aftalen ikke gav varige skattelettelser."},"arbejdsmarked":{"score":5,"text":"LA vil have mere arbejdsudbud og lavere ydelser og mener, at det skal kunne betale sig at arbejde. Partiet vil have mere fleksibilitet på arbejdsmarkedet."},"velfaerd":{"score":5,"text":"LA vil have mere privat medvirken og valgfrihed i velfærden og vil effektivisere den offentlige sektor. Partiet vil have borgerne til at vælge leverandør og give konkurrence til det offentlige."},"sundhed":{"score":5,"text":"LA vil have mere privat medvirken og konkurrence i sundhedsvæsenet, så borgerne kan vælge behandling. Partiet vil have mindre offentlig styring af sundhedssystemet."},"klima":{"score":4,"text":"LA vil have en grøn omstilling, der er markedsbaseret og ikke rammer forbrugerne hårdt. Partiet vil have teknologi og konkurrence frem for afgifter."},"natur_landbrug":{"score":4,"text":"LA vil have færre krav til landbruget og mindre regulering og vil have markedet til at løse miljøproblemer."},"eu":{"score":3,"text":"LA er positiv over for EU og det indre marked og er ikke EU-skeptisk. Partiet lægger vægt på frihandel og et stærkt europæisk samarbejde om sikkerhed."},"forsvar":{"score":5,"text":"LA vil have en stor oprustning af forsvaret og har fremlagt en finansieret plan for oprustningen. Det er et af partiets klareste profilpunkter."},"ret":{"score":4,"text":"LA vil have hårdere straf for alvorlig kriminalitet og mere politi, og vil ophæve strafrabat, så betingede domme kan udløses (B 53). Samtidig vil partiet have retssikkerhed og begrænsninger på statens magt."},"bolig":{"score":5,"text":"LA vil have mere marked på boligområdet og færre reguleringer, så flere kan få en bolig."},"uddannelse":{"score":5,"text":"LA vil have krav, valgfrihed og privat konkurrence i uddannelsessystemet og vil give institutionerne og eleverne mere frihed."}},"history":[{"year":"2007","event":"Ny Alliance stiftes 7. maj 2007. Partiet bliver forløber for Liberal Alliance."},{"year":"2008","event":"Liberal Alliance stiftes 28. august 2008."},{"year":"2019","event":"9. juni 2019 vælges Alex Vanopslagh som politisk leder for partiet."},{"year":"2022","event":"Liberal Alliance får 7,9 % og 14 mandater ved folketingsvalget 2022."},{"year":"2024","event":"Pernille Vermund forlader Nye Borgerlige og slutter sig til Liberal Alliance i januar 2024."},{"year":"2024","event":"LA når ca. 15,2 % i Altingets snit i maj 2024, men falder til 11,9 % i september 2024. Altinget peger på debatten om kvindelig værnepligt og EU-valgkampen som årsager."},{"year":"2026","event":"Ved valget 24. marts 2026 får LA 9,4 % og 16 mandater, mod 7,9 % og 14 mandater i 2022."},{"year":"2026","event":"11. april 2026 holder LA landsmøde i Tivoli i København. Landsformanden for LA Ungdom Tobias Jæger Pagh taler."},{"year":"2026","event":"12. maj 2026 stiller Vanopslagh og Støjberg (DD) krav om en blå statsminister som et ultimativt krav."},{"year":"2026","event":"3. juni 2026 tiltræder firkløverregeringen. Vanopslagh kritiserer den nye regering for skjulte skattestigninger i en grundlovstale 5. juni 2026."},{"year":"2026","event":"12. november 2026: Regeringen og DF indgår en skatteaftale med lettelser på cirka 11 mia. kr., som Vanopslagh kritiserer, fordi DF ifølge ham var 'billigst til salg'."}],"people":[{"name":"Alex Vanopslagh","role":"Politisk leder","note":"Partiets ansigt udadtil og leder siden 2019. Han har krævet en blå statsminister og var central i kampagnen på TikTok."},{"name":"Ole Birk Olesen","role":"Gruppeformand og finansordfører","note":"Leder LA's folketingsgruppe og er partiets finansordfører. Han deltog i regeringsforhandlingerne i maj 2026."},{"name":"Pernille Vermund","role":"Folketingsmedlem","note":"Kom til LA fra Nye Borgerlige i januar 2024 og er medfremsætter af forslagene B 54, B 55 og B 56 om asyl og trossamfund."},{"name":"Helena Artmann Andresen","role":"Folketingsmedlem; børne- og undervisningsordfører, dyrevelfærdsordfører fra 2026","note":"Medlem af LA's folketingsgruppe og lokalformand for LA Ungdom i Kolding."},{"name":"Freja Brandhøj","role":"Folketingsmedlem","note":"Fremsætter af forslaget B 48 om salg af håndkøbsmedicin via digitale platforme."},{"name":"Jens Meilvang","role":"Folketingsmedlem","note":"Fremsætter af forslaget B 53 om at udløse betingede domme og afskaffe strafrabat."}],"voters":{"summary":"LA har især vundet vælgere blandt unge og overtaget mange utilfredse Venstre-vælgere, ifølge Altinget. Partiet er populært blandt liberale og markedsorienterede vælgere.","strongholds":"Storbyerne og de yngre vælgere har været stærke for LA.","demographics":"LA's vælgere er især unge og mænd, ifølge Altinget."},"election2026":{"note":"LA fik 9,4 % og 16 mandater ved valget 24. marts 2026, mod 7,9 % og 14 mandater i 2022. Fremgangen skyldtes ifølge analyser, at LA hentede vælgere fra Venstre og var stærk på TikTok og blandt unge. Efter valget er LA i opposition, og partiet har krævet en blå statsminister."},"strengths":["Stærk på TikTok og blandt unge vælgere","Klar markedsliberal profil på skat og velfærd","Synlig og markant leder","Evne til at hente vælgere fra Venstre ved valget 2026"],"weaknesses":["Stærkt knyttet til Vanopslagh som person","Tilbagegang i målinger efter 2024","Konfliktfyldt forhold til Venstre og Konservative","Mange kritikere mener, at statsministerdrømmen splitter den blå blok"],"internalTensions":[{"title":"Statsministerdrømmen","detail":"LA's krav om en blå statsminister har skabt kritik i den blå blok. Kritikerne siger, at drømmen splitter blokken, mens partiet på landsmødet i april 2026 fik ny opbakning til den."},{"title":"Konkurrencen med Venstre","detail":"LA har hentet mange vælgere fra Venstre og står i en konflikt om, hvem der skal være den førende borgerlige kraft. Det har også skabt spændinger om kvindelig værnepligt og om SVM-regeringen."}],"typicalArguments":[{"claim":"Lavere skat og mindre stat giver mere frihed og flere i arbejde.","counter":"Kritikere mener, at skattelettelser rammer de svageste og svækker velfærden og offentlige serviceydelser."},{"claim":"Asylreglerne skal strammes, så Danmark ikke tager imod flygtninge uden for Danmarks nærområde.","counter":"Kritikere mener, at en sådan ordning er i strid med internationale forpligtelser og vil flytte problemet, ikke løse det."},{"claim":"Unge vil have frihed og liberale løsninger, og vi taler deres sprog.","counter":"Kritikere siger, at LA's appel til unge bygger på en TikTok-kampagne og ikke på holdbare politiske løsninger."},{"claim":"Vi vil have en blå statsminister, så den blå blok kan vinde.","counter":"Kritikere mener, at LA's statsministerdrøm splitter den blå blok og gør det svært at samle borgerlige vælgere."}],"vsDF":{"agree":["Begge partier vil have en stram udlændingepolitik og krav til integration","Begge stiller krav om en blå statsminister og en borgerlig regering"],"disagree":["LA er markedsliberal og vil have lavere skat og mindre stat, mens DF lægger større vægt på velfærd og ældre","LA er positiv over for EU og frihandel, mens DF er EU-skeptisk","LA vil have mere privat konkurrence i velfærden, mens DF er mere skeptisk over for privatisering"],"note":"LA og DF er begge i den borgerlige opposition og deler kravet om en blå statsminister, men LA er langt mere liberal i økonomi og EU-politik, mens DF er mere velfærdsorienteret og EU-skeptisk. I november 2026 kritiserede Vanopslagh DF for at have været 'billigst til salg' i skatteaftalen med regeringen. DF's Anders Vistisen afviste kritikken og kaldte Vanopslagh 'rigtig bitter'."},"vocabulary":[{"term":"Blå statsminister","meaning":"Kravet om, at en borgerlig politiker skal være statsminister efter næste valg, typisk fra Venstre, Konservative eller LA."},{"term":"Frihed","meaning":"Partiets centrale begreb for individets ret til at vælge og bestemme over eget liv, uden at staten blander sig unødigt."},{"term":"Ultimativt krav","meaning":"LA og DD's krav om en blå statsminister, som ikke kan forhandles væk."}],"funFacts":["Alex Vanopslagh har fået tilnavnet 'TikTok-kongen', fordi LA's kampagne i 2026 i høj grad foregik på TikTok.","LA nåede 15,2 % i Altingets snit i maj 2024, men faldt til 11,9 % i september 2024."],"sources":[{"title":"Ny skatteaftale på plads (TV 2, 12. nov. 2026)","url":"https://nyheder.tv2.dk/live/politik/2026-11-12-ny-skatteaftale-paa-plads?entry=65e419b2-8a92-4210-aa30-9f21f9e9bce3"},{"title":"Liberal Alliance (Wikipedia)","url":"https://da.wikipedia.org/wiki/Liberal_Alliance"},{"title":"Alex Vanopslagh (Wikipedia)","url":"https://da.wikipedia.org/wiki/Alex_Vanopslagh"},{"title":"Folketingsvalget 2026 (Wikipedia)","url":"https://da.wikipedia.org/wiki/Folketingsvalget_2026"},{"title":"Folketingsvalget 2022 (Wikipedia)","url":"https://da.wikipedia.org/wiki/Folketingsvalget_2022"},{"title":"Ole Birk Olesen (Liberal Alliance)","url":"https://www.liberalalliance.dk/politikere/ole-birk-olesen/"},{"title":"Helena Artmann Andresen (Liberal Alliance)","url":"https://www.liberalalliance.dk/helena-artmann-andresen/"},{"title":"Støjberg og Vanopslagh nedtoner stridigheder med V (Altinget, 12. maj 2026)","url":"https://www.altinget.dk/christiansborg/artikel/stoejberg-og-vanopslagh-nedtoner-stridigheder-med-v-vi-har-et-ultimativt-krav-og-det-er-en-blaa-statsminister"},{"title":"Vanopslagh og LA går tilbage. Hvad er gået galt? (Altinget, 13. sept. 2024)","url":"https://www.altinget.dk/artikel/vanopslagh-og-la-gaar-tilbage-hvad-er-gaaet-galt"},{"title":"Tobias Jæger Pagh: tale ved Liberal Alliances landsmøde 2026 (Danske Taler)","url":"https://www.dansketaler.dk/tale/tobias-jaeger-paghs-tale-ved-liberal-alliances-landsmode-2026.pdf"},{"title":"Fire borgerlige partier klar med fælles alternativ til SVM-regeringen (Lovguiden, 8. jan. 2026)","url":"https://www.lovguiden.dk/det-offentlige/liberal-alliance/2026-01-08-fire-borgerlige-partier-klar-med-faelles-alternativ-til-svm-regeringen"}],"order":9,"color":"#3FB2BE","on":"#12161C","blok":"blå","officialName":"Liberal Alliance","nick":"Liberal Alliance"},{"id":"k","letter":"C","name":"Det Konservative Folkeparti","short":"K","founded":"1916","foundedNote":"Det Konservative Folkeparti blev stiftet 22. februar 1916 og er et af Danmarks ældste partier.","leader":{"name":"Mona Juul","title":"Formand for Det Konservative Folkeparti","since":"2024","born":"1967","bio":"Mona Juul er født 20. september 1967 i Aarhus. Hun blev valgt til formand 21. april 2024 på et ekstraordinært landsråd i Herning uden modkandidater, efter at Søren Pape Poulsen døde i marts 2024. I oktober 2025 valgte hun at støtte SVM-regeringens finanslov for 2026 med partiets mandater, hvilket brød med den blå alliance. Hun er fortsat formand i november 2026, og i oktober 2026 kritiserede hun regeringens plan om at loft over rentefradraget i Folketingets åbningsdebat."},"role":"opposition","roleNote":"Konservative er i opposition til firkløverregeringen (S, SF, M og RV). Partiet har gået tættere på midten end de andre blå partier og har sagt, at det ønsker et bedre samarbejde i dansk politik.","ideology":["konservatisme","borgerlig midte","retsstat og tryghed","ansvarlig økonomi"],"euGroup":"EPP (Det Europæiske Folkeparti)","youth":{"name":"Konservativ Ungdom","note":"Partiets ungdomsorganisation for unge medlemmer."},"membersCount":"10.900 (2024)","website":"https://www.konservative.dk","oneLiner":"Borgerligt parti med fokus på tryghed, ansvar og en stærk retsstat, der har gået tættere på midten end de andre blå partier.","summary":"Konservative vil have et Danmark med tryghed, ansvar og en stærk retsstat, hvor folk får hjælp, men også tager ansvar for sig selv. Partiet lægger vægt på kriminalitetsbekæmpelse, en stram udlændingepolitik og en ansvarlig økonomi. Konservative er mindre liberale end Liberal Alliance på skat og marked og mere traditionelle i værdispørgsmål og velfærd. Partiet har vist vilje til at samarbejde med midten, hvilket har gjort det svært at placere præcist i den blå blok.","pitch":"Konservative står for tryghed, ansvar og en stærk stat, der gør det, den skal. Vi vil have færre kriminelle på gaden, en ordentlig udlændingepolitik og en økonomi, der holder. Vi er et parti, der tør tage ansvar, også når det er svært.","critique":"Kritikerne siger, at Konservative har flirtet med midten og er gået væk fra den blå blok. I oktober 2025 valgte partiet at støtte SVM-regeringens finanslov, og det blev af Altinget beskrevet som et brud med det borgerlige samarbejde, der styrkede Venstre. Kritikerne mener også, at partiets profil er uklar, og at de konkrete forslag ofte er uklare.","keyIssues":[{"title":"Retsstat og tryghed","detail":"Konservative vil have hårdere straf for alvorlig kriminalitet og tiltag mod ungdomskriminalitet. Partiet har foreslået at straffe forældre, hvis deres børn begår alvorlig vold, ifølge Sjællandske."},{"title":"Narkotika og unge","detail":"Mona Juul har fremlagt et narkotikaudspil, der skal stoppe unges brug af narkotika. Det går bl.a. ud på hårdere reaktioner over for gentagen besiddelse til eget forbrug, fordi det kan vise et mønster af misbrug."},{"title":"Ansvarlig økonomi og finanslov","detail":"Konservative støttede i oktober 2025 SVM-regeringens finanslov for 2026 med partiets mandater. Partiet vil have en stabil økonomi og lavere skat på arbejde."},{"title":"Rentefradrag og boligmarked","detail":"I Folketingets åbningsdebat 8. oktober 2026 kritiserede Mona Juul regeringens plan om et loft over rentefradraget, som hun mener vil gøre det dyrere at eje sin bolig og sværere at komme ind på boligmarkedet."},{"title":"Blå blok og samarbejde","detail":"Mona Juul har peget på Troels Lund Poulsen som borgerlig statsministerkandidat, og har kritiseret Lars Løkke Rasmussen og Morten Messerschmidt for at blokere for en borgerlig regering efter valget i marts 2026."}],"positions":{"udlaendinge":{"score":4,"text":"Konservative vil have en stram udlændingepolitik med krav til integration og arbejde. Partiet har foreslået, at forældre kan straffes, hvis deres børn begår alvorlig vold."},"oekonomi":{"score":4,"text":"Konservative vil have en stabil økonomi og lavere skat på arbejde, men er mindre liberale end LA. Partiet støttede i 2025 SVM's finanslov, hvilket viser en pragmatisk linje."},"arbejdsmarked":{"score":4,"text":"Konservative vil have flere i arbejde og en fleksibel arbejdsmarkedsmodel, med tryghed for lønmodtagere."},"velfaerd":{"score":3,"text":"Konservative vil have en stærk velfærd, der er målrettet dem, der har brug for hjælp, og vil have mere valgfrihed. Partiet står for en blanding af offentlig drift og privat medvirken."},"sundhed":{"score":3,"text":"Konservative vil have en offentlig sundhedssektor med mere valgfrihed og privat medvirken, især hvor ventetiderne er lange. Partiet fremlagde et sundhedsudspil på sommergruppemødet i september 2025."},"klima":{"score":3,"text":"Konservative støtter den grønne omstilling, men vil have den til at ramme erhvervsliv og forbrugere så lidt som muligt."},"natur_landbrug":{"score":3,"text":"Konservative vil have balance mellem landbrugets vilkår og natur og miljø. Partiets linje er mindre firkantet end Venstres."},"eu":{"score":2,"text":"Konservative er positive over for EU og det indre marked. Partiet er ikke EU-skeptisk, men vil have nationalt selvstyre i udlændinge- og retspolitik."},"forsvar":{"score":5,"text":"Konservative vil have en stærk forsvarsindsats og en større oprustning."},"ret":{"score":5,"text":"Konservative vil have hårdere straffe for alvorlig kriminalitet og mere politi, og lægger vægt på tryghed. Partiet vil samtidig have retssikkerhed for borgerne."},"bolig":{"score":4,"text":"Konservative vil have en blanding af marked og regulering på boligområdet. Partiet kritiserer et loft over rentefradraget, fordi det gør boligejerskab dyrere."},"uddannelse":{"score":4,"text":"Konservative vil have en uddannelse med krav og faglige standarder og mere valgfrihed for elever og studerende."}},"history":[{"year":"1916","event":"Det Konservative Folkeparti stiftes 22. februar 1916."},{"year":"2019","event":"Konservative er i opposition efter valget i 2019 og presser på for en stram skatte- og retspolitik."},{"year":"2022","event":"Konservative får 5,5 % og 10 mandater ved folketingsvalget 2022."},{"year":"2024","event":"Søren Pape Poulsen dør i marts 2024, og 21. april 2024 vælges Mona Juul til formand på et ekstraordinært landsråd i Herning uden modkandidater."},{"year":"2025","event":"I september 2025 fremlægger LA, DD, DF og Konservative sammen 50 forslag til en borgerlig regering, der skal gennemføres i de første 100 dage."},{"year":"2025","event":"23. oktober 2025 indgår Konservative en finanslovsaftale med SVM-regeringen om finansloven for 2026, som den eneste af de blå partier. Mona Juul bryder dermed med den blå alliance."},{"year":"2026","event":"Ved valget 24. marts 2026 får Konservative 7,6 % og 13 mandater."},{"year":"2026","event":"7. april 2026 vælges Mette Abildgaard som gruppeformand for folketingsgruppen og afløser Mona Juul på posten. Helle Bonnesen fortsætter som næstformand."},{"year":"2026","event":"5. maj 2026 udpeger partiet Frederik Bloch Münster som ny politisk ordfører."},{"year":"2026","event":"8. oktober 2026 kritiserer Mona Juul i Folketingets åbningsdebat regeringens plan om et loft over rentefradraget."}],"people":[{"name":"Mona Juul","role":"Formand","note":"Partiets formand siden 2024 og den borgerlige politiker, der i 2025 valgte at støtte SVM-regeringens finanslov."},{"name":"Mette Abildgaard","role":"Gruppeformand (siden 7. april 2026)","note":"Leder folketingsgruppen og er familieordfører, og har afløst Mona Juul som gruppeformand."},{"name":"Helle Bonnesen","role":"Næstformand for folketingsgruppen","note":"Næstformand i folketingsgruppen, som fortsatte i posten efter gruppeformandsskiftet i april 2026."},{"name":"Frederik Bloch Münster","role":"Politisk ordfører (udpeget 5. maj 2026)","note":"Partiets politiske ordfører efter Mette Abildgaard. Han er den, der fører partiets politiske linje i Folketinget."},{"name":"Mai Mercado","role":"Folketingsmedlem, tidligere børne- og socialminister (2016-2019)","note":"En af partiets mest erfarne profiler og et kendt ansigt i debatter om familie, børn og socialpolitik."},{"name":"Marcus Knuth","role":"Folketingsmedlem","note":"Skiftede fra Venstre til Konservative i 2019 og er en af partiets skarpeste stemmer i udlændingedebatten."},{"name":"Sofie Therese Svendsen","role":"Folketingsmedlem, yngste medlem af Folketinget","note":"Blev valgt 24. marts 2026 som 23-årig og er det yngste medlem af det nye Folketing."}],"voters":{"summary":"Konservative har en vælgerbase af borgerlige, der lægger vægt på tryghed, ansvar og en stærk retsstat. Partiet har mistet vælgere til LA og Venstre gennem de senere år, men har vist sig som et stabilt parti i midten af den blå blok.","strongholds":"Storbyernes forstæder og de sjællandske områder har historisk været stærke for Konservative.","demographics":"Vælgerne er typisk ældre og middelklasse, med en overrepræsentation af selvstændige og folk med erhvervsuddannelser."},"election2026":{"note":"Konservative fik 7,6 % og 13 mandater ved valget 24. marts 2026, mod 5,5 % og 10 mandater i 2022. Fremgangen skyldtes ifølge analyser, at partiet samlede borgerlige vælgere, men den blå blok samlede sig ikke om én linje. Efter valget er partiet i opposition, og målinger i efteråret 2026 viser cirka 9,9 %."},"strengths":["Tryghed og retsstat er et klart profilpunkt","Stærk forankring i middelklassen og blandt selvstændige","Mona Juul er en af de få blå ledere, som Statsministeren har rost i Folketinget","Partiet kan samarbejde både med midten og den blå blok"],"weaknesses":["Lille vælgerbase og svag tilslutning i målinger","Uklar profil efter støtten til SVM-regeringens finanslov","Finanslovsaftalen i 2025 gav kritik fra den blå blok","Afhængig af at den blå blok samler sig om en statsministerkandidat"],"internalTensions":[{"title":"Midten eller den blå blok","detail":"Konservative har flirtet med midten og støttede SVM's finanslov i 2025, mens LA og DF holder fast i en blå linje. Det skaber spændinger om, hvor partiet hører hjemme."},{"title":"Tryghed mod samarbejde","detail":"Mona Juul vil have et bedre samarbejde i dansk politik, mens kritikere mener, at partiet svækker den blå blok, når det samarbejder med midten."}],"typicalArguments":[{"claim":"Vi vil have tryghed og hårdere straf, så folk kan føle sig trygge.","counter":"Kritikere mener, at hårdere straf ikke alene løser kriminalitet, og at forebyggelse og resocialisering virker bedre."},{"claim":"Vi tager ansvar, også når det er svært, og støtter regeringen, når det gavner landet.","counter":"Kritikere siger, at partiet svigtede den blå blok, da det støttede SVM's finanslov i 2025."},{"claim":"Et loft over rentefradraget gør det dyrere at eje sin bolig, og det rammer almindelige boligejere.","counter":"Regeringen mener, at et loft skal dæmpe boligpriserne og gøre fordelingen mere rimelig."},{"claim":"Vi vil have et bedre samarbejde i dansk politik, så Danmark kan få en borgerlig regering.","counter":"Kritikere mener, at samarbejde med midten svækker den blå blok, der har brug for en fælles linje for at vinde valget."}],"vsDF":{"agree":["Begge partier vil have en stram udlændingepolitik og krav til integration","Begge er for en stærk retsstat og hårdere straf for alvorlig kriminalitet"],"disagree":["Konservative er mere positive over for EU og det indre marked, mens DF er EU-skeptisk","Konservative har vist vilje til at samarbejde med midten og SVM, mens DF holder fast i en blå linje"],"note":"Konservative og DF er begge borgerlige partier, men Konservative er mere pragmatiske i samarbejdet og i EU-spørgsmål, mens DF lægger større vægt på velfærd og er mere EU-skeptisk. I november 2026 indgik regeringen en skatteaftale med DF, som Konservative ikke var en del af."},"vocabulary":[{"term":"Retsstat","meaning":"At staten følger lovene, og at borgerne har rettigheder over for magten. Konservative bruger begrebet om tryghed og retssikkerhed."},{"term":"Ansvar","meaning":"Partiets begreb for, at borgerne skal tage ansvar for sig selv og deres familie, og at staten træder til, når det er nødvendigt."},{"term":"Blå familie","meaning":"Mona Juuls begreb for de blå partier. Hun har sagt, at det kræver mere arbejde at samle den blå familie."}],"funFacts":["I oktober 2025 var Konservative det eneste blå parti, der indgik finanslovsaftale med SVM-regeringen.","Mona Juul blev valgt til formand 21. april 2024 uden modkandidater."],"sources":[{"title":"Folketingets åbningsdebat (TV 2, 8. okt. 2026)","url":"https://nyheder.tv2.dk/live/politik/2026-10-08-folketingets-aabningsdebat"},{"title":"Det Konservative Folkeparti (Wikipedia)","url":"https://da.wikipedia.org/wiki/Det_Konservative_Folkeparti"},{"title":"Mona Juul (Wikipedia)","url":"https://da.wikipedia.org/wiki/Mona_Juul"},{"title":"Folketingsvalget 2026 (Wikipedia)","url":"https://da.wikipedia.org/wiki/Folketingsvalget_2026"},{"title":"Folketingsvalget 2022 (Wikipedia)","url":"https://da.wikipedia.org/wiki/Folketingsvalget_2022"},{"title":"Mona Juul (lex.dk)","url":"https://lex.dk/Mona_Juul"},{"title":"Regeringen indgår finanslovsaftale med Konservative (Altinget, 23. okt. 2025)","url":"https://www.altinget.dk/artikel/regeringen-indgaar-finanslovsaftale-med-konservative-stor-strategisk-sejr-for-venstre-siger-politisk-redaktoer"},{"title":"Støjberg og Vanopslagh nedtoner stridigheder med V (Altinget, 12. maj 2026)","url":"https://www.altinget.dk/christiansborg/artikel/stoejberg-og-vanopslagh-nedtoner-stridigheder-med-v-vi-har-et-ultimativt-krav-og-det-er-en-blaa-statsminister"},{"title":"Konservative vil straffe indvandrerforældre for børnenes kriminalitet (Sjællandske)","url":"https://www.sn.dk/art6645845/koebenhavn-kommune/politik/konservative-vil-straffe-indvandrerforaeldre-for-boernenes-kriminalitet"}],"order":7,"color":"#96B226","on":"#12161C","blok":"blå","officialName":"Det Konservative Folkeparti","nick":"Konservative"},{"id":"df","letter":"O","name":"Dansk Folkeparti","short":"DF","founded":"1995","foundedNote":"Partiet blev stiftet 6. oktober 1995, da Pia Kjærsgaard og Kristian Thulesen Dahl brød ud af Fremskridtspartiet. De kritiserede partiets anarkistiske tilstand og 'alt eller intet'-politik og ville have en parlamentarisk linje med udlændingekritik og velfærd i centrum.","leader":{"name":"Morten Messerschmidt","title":"Formand for Dansk Folkeparti","since":"2022","born":"1980","bio":"Messerschmidt blev valgt til formand på et ekstraordinært årsmøde i Herning i januar 2022 med 499 af 828 delegerede stemmer og tiltrådte 23. januar 2022 efter Kristian Thulesen Dahl. Han var medlem af Europa-Parlamentet fra 2009 til 2019, medlem af Folketinget 2005-2009 og igen fra 2019. Ved valget 24. marts 2026 fik han 50.819 personlige stemmer i Sjællands Storkreds, det højeste antal personlige stemmer i valget."},"role":"opposition","roleNote":"DF er ikke regeringsparti. Firkløverregeringen (Socialdemokratiet, SF, Moderaterne og Radikale Venstre) har været regering siden 3. juni 2026 med støtte fra Enhedslisten og Alternativet. DF har 16 mandater efter valget 2026 og forhandler enkeltsager med regeringen, senest om brændstofafgiften.","ideology":["udlændingekritisk","EU-skeptisk","velfærdsnationalistisk","ældre- og prisfokus","nationalkonservativ"],"euGroup":"Patriots for Europe (partiets ene mandat i Europa-Parlamentet efter valget i 2024)","youth":{"name":"Dansk Folkepartis Ungdom (DFU)","note":"DFU er partiets ungdomsorganisation. Christian Bülow blev valgt til landsformand i 2022. Aldersgrænser og kontingent for DFU er beskrevet i df-extra.json."},"membersCount":"under 10.000 (september 2021)","website":"https://danskfolkeparti.dk/","oneLiner":"Udlændingekritisk velfærdsparti med EU-skepsis, prisfokus og ældre i fokus. Fik 9,1 % ved valget 2026.","summary":"Dansk Folkeparti vil først og fremmest begrænse indvandringen, især fra ikke-vestlige lande, og bevare den danske velfærdsstat til dem, der har tilknytning til landet. Partiet vil have Danmark ud af de dybere dele af EU-samarbejdet og beholde kronen. Partiets mærkesager på hjemmesiden er Udlændinge, Priser, Ældre og Familie. I 2026 har DF især gjort billigere benzin og diesel til sin økonomiske profil. Forskellen til Venstre og Liberal Alliance er, at DF vægter velfærd og udlændingepolitik højere end skattelettelser og marked. Forskellen til Socialdemokratiet er, at DF vil stramme udlændingepolitikken langt mere og er EU-skeptisk. Partiet kalder sig selv 'blå bloks bløde hjerte' på sin hjemmeside.","pitch":"Vi siger det, mange tænker: Danmark skal være Danmark, og vi skal have styr på indvandringen. Vi vil have billigere benzin og diesel, flere penge til de ældre og en pension, man kan leve af. Vi vil ikke have EU's dybere samarbejde og vil beholde kronen. Vi er ikke bange for at sige det højt, og 16 mandater efter valget 2026 viser, at mange danskere er enige.","critique":"Kritikerne mener, at DF's udlændingepolitik rammer langt bredere end kriminelle og ikke-integrerede. Forslag som den retroaktive fjernelse af permanent opholdstilladelse kan ramme også lovligt bosatte og velintegrerede. De peger på, at 'remigration' er et begreb, DF har lånt fra bevægelsen Generation Identitær, og at partiets tone har ændret sig over for ikke-vestlige danskere. De siger også, at DF's skiftende standpunkter om pensionsalder og regeringsdeltagelse viser et parti, der vil have magt uden at stå ved sine løfter.","keyIssues":[{"title":"Udlændinge og remigration","detail":"DF har fremlagt en 22-punkts plan for remigration, som blev præsenteret før valgudskrivelsen i 2026. Den 19. marts 2026 foreslog partiet at afskaffe permanent opholdstilladelse for de fleste udlændinge, der ikke er tæt familie til en dansk statsborger. Nye tilladelser skal kun fornys med ren straffeattest og selvforsørgelse, og udlændinge uden arbejde skal kunne udvises. Kritikere og jurister peger på, at forslaget kan have retroaktiv virkning, og at det er uklart, om dansk ret tillader det."},{"title":"Priser og afgifter på benzin og diesel","detail":"Billigere brændstof er DF's vigtigste økonomiske mærkesag i 2026. Den 8. maj 2026 lancerede partiet et borgerforslag om at sænke afgifterne på benzin og diesel og momsen til EU's minimumsniveau. Aftalen med regeringen fra 11.–12. november 2026 sænker afgiften med omkring 2 kroner pr. liter fra 2027 i et år. Den finansieres ved en senere indfasning af selskabsskatten og mellemskatten."},{"title":"Ældre og velfærd","detail":"DF har 'Ældre' som en af fire mærkesager på sin hjemmeside med målet 'En værdig behandling af vores ældre'. Partiet har gentagne gange krævet flere penge til ældre og sundhedsvæsen og prioriterer velfærd over skattelettelser."},{"title":"Pension og seniorpension","detail":"DF vil have en lavere pensionsalder for dem med nedslidte job og har sagt nej til at hæve pensionsalderen. Partiet er en af tre partier, der i oktober 2026 meldte ud, at de vil blokere regeringens forslag om skærpede krav til seniorpension. Regeringen regner med en besparelse på omkring 800 mio. kr. om året."},{"title":"EU-skepsis og suverænitet","detail":"DF er EU-skeptisk. Partiet vil ikke afgive suverænitet til EU, er imod euroen og vil beholde kronen, og er imod EU-medlemskab for Tyrkiet. Partiets ene mandat i Europa-Parlamentet sidder i Patriots for Europe-gruppen. DF fik 6,37 % ved EU-valget i 2024."},{"title":"Forsvar og Ukraine","detail":"DF støtter ikke ubegrænset hjælp til Ukraine. Partiet har sagt, at støtten til Ukraine har en 'udløbsdato', og er imod Ukraines NATO-medlemskab, så længe krigen står på. I 2025 gik Messerschmidt ind for at skalere ned den danske militære støtte. Alex Ahrendtsen er partiets forsvarsordfører."},{"title":"Islam, tørklæde og religiøse praksisser","detail":"I marts 2026 stillede Messerschmidt krav om, at DF kun skulle indgå i en regering, hvis flere muslimer forlod Danmark, end der kom. Venstres leder Troels Lund Poulsen afviste kravet med, at religion ikke skal styre dansk indvandringspolitik."}],"positions":{"udlaendinge":{"score":5,"text":"Den strammeste linje i Folketinget. DF vil kraftigt reducere ikke-vestlig indvandring, afskaffe permanent opholdstilladelse for de fleste udlændinge uden tæt dansk familietilknytning og indføre remigration. Partiet vil også revurdere statsborgerskaber givet inden for de seneste 20 år og udvise udlændinge uden arbejde."},"oekonomi":{"score":3,"text":"Blandet linje. DF vil sænke afgifterne på brændstof og finansiere det ved at indfase selskabsskat og mellemskat senere. Partiet vil bruge det offentlige til ældre og velfærd og er hverken et klassisk liberalt skatteparti eller et socialdemokratisk omfordelingsparti."},"arbejdsmarked":{"score":2,"text":"Mere tryghed end arbejdsudbud. DF vil have en lavere pensionsalder for nedslidte, er imod at hæve pensionsalderen og er i oktober 2026 gået imod skærpede krav til seniorpension sammen med Venstre og Liberal Alliance. Partiet vil samtidig have, at udlændinge uden arbejde skal kunne udvises."},"velfaerd":{"score":2,"text":"Mere offentligt, men kun til dem med tilknytning. DF kalder sig forsvarer af velfærdsstaten. Partiets forslag fra marts 2026 går ud på at udelukke udlændinge fra visse ydelser, fx førtidspension."},"sundhed":{"score":2,"text":"Offentlig sundhed med flere midler. DF har støttet øgede udgifter til pensioner og sundhed. Partiets sundhedsordfører er Jan Herskov, der har ansvaret for sundhed og psykiatri."},"klima":{"score":4,"text":"Prisfokus frem for hurtig omstilling. DF's klimapolitik i 2026 handler især om billigere benzin og diesel. Aftalen med regeringen i november 2026 sænker afgiften midlertidigt i ét år fra 2027. Partiet vil have, at almindelige familier ikke skal betale for en klimapolitik, de ikke har været med til at bestemme."},"natur_landbrug":{"score":4,"text":"Frivillig beskyttelse af grundvand. Partiets miljø- og landbrugsordfører er Rune Bønnelykke, og klimaordfører er Malte Larsen. Ifølge en kronik fra Danva i marts 2026 er DF med på en frivillig model under grøn trepart, hvor landmænd og vandværker selv holder særligt sårbare grundvandsområder fri for sprøjtning. Josephine Alstrup Kofod er partiets dyrevelfærdsordfører. Partiet går ind for hårdere straffe for dyremishandling."},"eu":{"score":5,"text":"Den mest EU-skeptiske gruppe i Folketinget. DF vil have Danmark ud af det dybere EU-samarbejde, beholde kronen, er imod euroen og er imod Tyrkiets optagelse i EU. Partiets mandat i Europa-Parlamentet sidder i Patriots for Europe-gruppen. Malte Larsen er partiets EU-ordfører, og Mette Thiesen er udenrigsordfører."},"forsvar":{"score":3,"text":"Skeptisk over for mere hjælp til Ukraine, men ikke imod dansk forsvar som sådan. DF har sagt, at støtten til Ukraine har en udløbsdato, og Messerschmidt gik i 2025 ind for at skalere ned den militære støtte. Alex Ahrendtsen er partiets forsvarsordfører."},"ret":{"score":5,"text":"Hårdere udvisning og strengere krav til udlændinge. Forslagene fra marts 2026 kræver ren straffeattest for at få fornyet opholdstilladelse. I november 2026 har 16 DF-medlemmer fremsat B 16 og B 17, der vil stramme adgangen til dansk indfødsret og gøre det muligt at frakende indfødsret for kriminalitet. Anders Vistisen er finans- og retsordfører. Partiets hjemmeside lover 'mere tryghed i hverdagen'."},"bolig":{"score":3,"text":"Mærkesagen Priser er i 2026 knyttet til brændstof og ikke til boliger. De seneste dokumenterede boligudspil fra DF er fra 2018 og 2019. I 2019 foreslog partiet at fordoble puljen til renovering af almene boliger fra 10 til 20 mia. kr., finansieret af Landsbyggefonden. I 2018 afviste DF, at almindelige lejere skulle betale for regeringens 'ghettoudspil'. Christian Kirk er partiets boligordfører."},"uddannelse":{"score":3,"text":"Josephine Alstrup Kofod er partiets børne- og undervisningsordfører. Alex Ahrendtsen var i 2024 undervisningsordfører og foreslog, at skolerne selv kan give karakterer fra 4. klasse. I 2026 har DF fremsat B 42, der vil opdatere skolernes sikkerhedsberedskab og udarbejde undervisningsforløb om Muhammedkrisen til folkeskolen."}},"history":[{"year":"1995","event":"6. oktober: Pia Kjærsgaard og Kristian Thulesen Dahl bryder med Fremskridtspartiet, og Dansk Folkeparti stiftes. Det første landsmøde i Vissenbjerg 1. juni 1996 valgte Kjærsgaard som formand."},{"year":"2001","event":"DF får 12,0 % og 22 mandater og støtter Venstre-Konservative-regeringen under Anders Fogh Rasmussen uden at gå ind i regeringen, mod at udlændingepolitikken strammes. Støtten holder til valget i 2011."},{"year":"2007","event":"Folketingsvalget giver 13,9 % og 25 mandater. Det er partiets højeste resultat før 2015."},{"year":"2011","event":"12,3 % og 22 mandater. Det er første tilbagegang efter fremgangen fra 2007."},{"year":"2015","event":"DF får 21,1 % og 37 mandater, partiets bedste valg nogensinde, og bliver det næststørste parti i Folketinget."},{"year":"2019","event":"8,7 % og 16 mandater, et tab på 21 mandater. DF rykker ned på tredjepladsen og går i opposition."},{"year":"2022","event":"Januar: Morten Messerschmidt vinder formandsvalget på et ekstraordinært årsmøde i Herning med 499 af 828 delegerede stemmer og tiltræder 23. januar efter Kristian Thulesen Dahl."},{"year":"2022","event":"Folketingsvalget giver partiets værste resultat: 2,6 % og 5 mandater. Peter Skaarup og flere andre folketingsmedlemmer forlader partiet og slutter sig til Danmarksdemokraterne."},{"year":"2024","event":"Europa-Parlamentsvalget giver 6,37 % og 1 mandat. DF tilslutter sig Patriots for Europe-gruppen efter valget."},{"year":"2026","event":"24. marts: DF får 9,1 % og 16 mandater, vokser i alle 92 kredse og mere end tredobler sin tilslutning fra 2022. Messerschmidt siger efter valget, at kampagnen fortsætter, og at valget var et delmål for ham."}],"people":[{"name":"Morten Messerschmidt","role":"Formand","note":"Formand siden 23. januar 2022 og medlem af Folketinget for Sjællands Storkreds. Han har bestemt partiets kurs efter 2022, herunder den hårdere remigrationslinje. Han var DF's politiske ordfører, indtil Peter Kofod overtog rollen 14. april 2026."},{"name":"Alex Ahrendtsen","role":"Gruppeformand (fra april 2026) og forsvarsordfører","note":"Overtog gruppeformandsposten fra Peter Kofod i april 2026, ifølge Altinget. Han er partiets forsvarsordfører og var tidligere undervisningsordfører."},{"name":"Peter Kofod","role":"Politisk ordfører (fra 14. april 2026), på barsel fra oktober 2026","note":"Var gruppeformand fra november 2022 og overtog posten som politisk ordfører i april 2026. Han er gået på barsel fra oktober 2026, og Christian Kirk har overtaget posten i hans sted. Derfor står han ikke på gruppens liste lige nu."},{"name":"Christian Kirk","role":"Stedfortræder for Peter Kofod, boligordfører","note":"Er suppleant for Peter Kofod i Folketinget og har midlertidigt overtaget rollen som politisk ordfører under barslen. Han er partiets boligordfører."},{"name":"Mikkel Bjørn","role":"Udlændinge-, indfødsrets- og integrationsordfører","note":"Er partiets ordfører for udlændinge, indfødsret og integration. Han er en af hovedpersonerne bag forslagene om at frakende indfødsret for kriminalitet og om at ændre adgangen til statsborgerskab."},{"name":"Anders Vistisen","role":"Finans- og retsordfører og chief whip","note":"Er partiets finans- og retsordfører og chief whip ifølge Altinget i juli 2026. Han har fremsat forslaget om at indlede en opløsningssag mod Hizb ut-Tahrir og vil ifølge Altinget have DF op på omkring 20 % ved næste valg."},{"name":"Pia Kjærsgaard","role":"Stifter og tidligere formand (1996-2012)","note":"Var DF's første formand og den person, der byggede partiets udlændingelinje op. Hun annoncerede i september 2024, at hun ikke genopstiller, og hun står ikke på DF's folketingsliste efter valget i 2026. Hun er regionsrådsmedlem i Region Østdanmark."}],"voters":{"summary":"DF's fremgang i 2026 kom især fra andre partiers vælgere. Ifølge TV 2 i oktober 2026 har 11 % af Liberal Alliances vælgere, 19 % af Danmarksdemokraternes vælgere og 8 % af Venstres vælgere skiftet til DF, og 67 % af Borgernes Parti's vælgere siger, at de nu stemmer DF. 91 % af dem, der stemte DF i marts, vil gøre det igen. Anders Vistisen peger på SF- og socialdemokratiske vælgere som næste målgruppe (Altinget, 16. juli 2026).","strongholds":"Messerschmidt blev valgt i Sjællands Storkreds, og DF gik frem i alle 92 kredse ved valget i 2026.","demographics":"Der er ikke offentliggjort en fordeling af DF's vælgere efter alder, køn eller uddannelse for valget i 2026 i de kilder, der ligger til grund for denne fil. Valgundersøgelser fra DR, TV 2 eller Epinion efter valget vil kunne give den fordeling."},"election2026":{"note":"Ved folketingsvalget 24. marts 2026 fik DF 9,1 % og 16 mandater, op fra 2,6 % og 5 mandater i 2022. DF var ifølge Altinget den klare vinder og gik frem i alle 92 kredse. Siden valget er vælgere kommet fra Venstre, Liberal Alliance, Danmarksdemokraterne og Borgernes Parti. Messerschmidt kaldte valget et delmål, og DF er ikke med i firkløverregeringen."},"strengths":["Et klart og genkendeligt budskab om udlændinge, priser og ældre, som mange vælgere forstår.","Et tydeligt budskab, der er let at dele, også på sociale medier.","Faste lokalforeninger og storkredsforeninger med vedtægter, der gør organisationen forudsigelig for medlemmer og vælgere.","Et stærkt resultat i 2026 med 16 mandater, lige så mange som Liberal Alliance, og fremgang i alle kredse."],"weaknesses":["Stor afhængighed af formanden, og flere interne opgør om kurs og personer siden 2021.","Juridisk tvivl om flere forslag, herunder retroaktive ændringer af opholdstilladelser.","Kritikere, også borgerlige som Simon Emil Ammitzbøll-Bille i Altinget, mener, at DF er blevet et fløjparti, der har mistet indflydelse på finansloven.","Uklare svar på konkrete spørgsmål, fx om pensionsalderen, hvor DF ikke kunne give et entydigt svar i en Altinget-artikel fra 2026."],"internalTensions":[{"title":"Uro om udlændingepolitikken i 2021","detail":"Den 19. september 2021 skrev Altinget, at Pia Kjærsgaard ærgrede sig over uro i partiet og spurgte, hvorfor 'vores allervigtigste mærkesag' skulle sættes spørgsmålstegn ved. Hun ville have stoppet den offentlige debat om partiets udlændingelinje, fordi den ifølge hende skadede målingerne."},{"title":"Formandsvalget i 2022","detail":"Før Messerschmidt blev valgt i januar 2022, var der et opgør mellem ham og Martin Henriksen. Kjærsgaard støttede Messerschmidt, mens Marie Krarup og Bent Bøgsted støttede Henriksen. Henriksen sagde, at Kjærsgaard ikke ville være med i ledelsen, hvis han blev formand."},{"title":"Kritik af kursen i 2024","detail":"Simon Emil Ammitzbøll-Bille, tidligere LA-politiker, skrev i Altinget 28. august 2024, at Messerschmidt flytter DF længere til højre og har 'soldet arven op' efter Kjærsgaard. Det er en meningsytring fra en modstander, men den viser den indre debat om kursen."},{"title":"Rollefordelingen i 2026","detail":"Den 14. april 2026 overtog Peter Kofod den politiske ordførerpost fra Messerschmidt. Altinget skrev, at det er nyt for DF at adskille ordførerposten fra formandsposten. I oktober 2026 gik Kofod på barsel, og Christian Kirk overtog posten."}],"typicalArguments":[{"claim":"Vi har fået tilliden, fordi vi siger det, andre ikke tør. Når danskerne giver os 16 mandater, er det et mandat til at stramme udlændingepolitikken.","counter":"Vælgerne har stemt på DF's prismål og ældrepolitik, ikke nødvendigvis på remigration. Et forslag om at fjerne permanent ophold for lovlige borgere, der har boet i landet i årevis, er ikke en del af et klart valgløfte."},{"claim":"Vi vil bare have, at den, der kommer hertil, bidrager til velfærdsstaten, og at kriminelle udlændinge skal ud.","counter":"Forslag, der rammer alle med udenlandsk statsborgerskab eller opholdstilladelse, rammer også mange, der aldrig har begået kriminalitet. Kriminalitetsstatistikken fordelt på herkomst bør læses med hensyn til alder, køn og social baggrund."},{"claim":"Vi er ikke imod folk. Vi er imod, at Danmark bliver for stort og for forskelligt for vores velfærd.","counter":"Det er svært at se forskellen i praksis, når forslagene retter sig mod permanent ophold, statsborgerskab og tørklæder. Kritikere siger, at DF's retorik rammer danskere med udenlandsk baggrund, der er velintegrerede."},{"claim":"Vi har sænket afgifterne på benzin og diesel, så almindelige familier får mere i lønningsposen.","counter":"Afgiftssænkningen er midlertidig i ét år og skal finansieres ved en senere indfasning af selskabsskat og mellemskat. Det betyder, at pengene skal hentes andre steder, og det rammer også pensionister, som Faglige Seniorer har peget på."},{"claim":"Vi er det eneste borgerlige parti, der vil have en lavere pensionsalder for dem, der er nedslidte.","counter":"Modstandere argumenterer for, at en højere pensionsalder er nødvendig for at holde velfærdsstaten bæredygtig. DF har ikke givet et klart svar på, om partiet selv ville hæve pensionsalderen, hvis det sad i en regering."}],"vocabulary":[{"term":"Remigration","meaning":"DF's betegnelse for at få udlændinge, der ikke er integreret eller ikke har arbejde, til at forlade Danmark. Kritikere peger på, at begrebet kommer fra bevægelsen Generation Identitær."},{"term":"Mærkesag","meaning":"En sag, partiet prioriterer højest. DF's hjemmeside nævner fire: Udlændinge, Priser, Ældre og Familie."},{"term":"Blå bloks bløde hjerte","meaning":"DF's selvbeskrivelse på hjemmesiden. Partiet ser sig selv som den blå blok's velfærds- og folkelige side."},{"term":"Ikke de fremmede, ikke EU, ikke eksperterne - danskerne!","meaning":"Et slogan fra Messerschmidt, som står i banneret på DF's hjemmeside. Det sætter danskerne op mod både udlændinge, EU og eksperter."},{"term":"Fløjparti","meaning":"Et parti, der står uden for regeringsdannelse og finanslov, men som påvirker debatten. Det er Ammitzbøll-Bille's ord om DF i 2024."},{"term":"Borgerforslag","meaning":"Et forslag, der kræver 50.000 underskrifter for at komme til behandling i Folketinget. DF lancerede et sådant om brændstofafgifter den 8. maj 2026."}],"funFacts":["DF's 2015-resultat på 21,1 % og 37 mandater er partiets bedste valg nogensinde og gjorde det til det næststørste parti i Folketinget. I 2022 faldt det til 2,6 % og 5 mandater.","Partiet blev stiftet i 1995, efter at to folketingsmedlemmer brød ud af Fremskridtspartiet i en konflikt om kurs og ledelse.","Ved valget i 2026 fik Messerschmidt 50.819 personlige stemmer i Sjællands Storkreds, det højeste antal personlige stemmer i valget."],"sources":[{"title":"Dansk Folkeparti: forside","url":"https://danskfolkeparti.dk/"},{"title":"Dansk Folkeparti: politik og ordførere","url":"https://danskfolkeparti.dk/politik"},{"title":"Dansk Folkeparti: bliv medlem","url":"https://danskfolkeparti.dk/bliv-medlem"},{"title":"Dansk Folkeparti: 'DF brager frem til valget 2026'","url":"https://danskfolkeparti.dk/nyheder/df-brager-frem-til-valget-2026/"},{"title":"Wikipedia (da): Dansk Folkeparti","url":"https://da.wikipedia.org/wiki/Dansk_Folkeparti"},{"title":"Wikipedia (da): Morten Messerschmidt","url":"https://da.wikipedia.org/wiki/Morten_Messerschmidt"},{"title":"Wikipedia (en): Danish People's Party","url":"https://en.wikipedia.org/wiki/Danish_People%27s_Party"},{"title":"Wikipedia (en): Peter Kofod","url":"https://en.wikipedia.org/wiki/Peter_Kofod"},{"title":"Altinget: Peter Kofod erstatter Morten Messerschmidt som politisk ordfører i DF (14. april 2026)","url":"https://www.altinget.dk/christiansborg/artikel/peter-kofod-erstatter-morten-messerschmidt-som-politisk-ordfoerer-i-df"},{"title":"Altinget: DF's politiske ordfører går på barsel (9. oktober 2026)","url":"https://www.altinget.dk/artikel/dfs-politiske-ordfoerer-gaar-paa-barsel"},{"title":"Altinget: Overblik over DF's ordførerskaber (23. april 2026)","url":"https://www.altinget.dk/christiansborg/artikel/overblik-dansk-folkeparti-praesenterer-ordfoererskaber"},{"title":"Altinget: Peter Kofod bliver gruppeformand i DF (8. november 2022)","url":"https://www.altinget.dk/artikel/peter-kofod-bliver-gruppeformand-i-df"},{"title":"Altinget: Messerschmidt blev valgets stemmesluger (25. marts 2026)","url":"https://www.altinget.dk/artikel/messerschmidt-blev-valgets-stemmesluger-kampagnen-fortsaetter-det-her-valg-var-et-delmaal-for-ham"},{"title":"Altinget: Messerschmidts nye indpisker har en plan (16. juli 2026)","url":"https://www.altinget.dk/artikel/messerschmidts-nye-indpisker-har-en-plan-der-skal-lokke-utilfredse-sfere-og-socialdemokrater-over-til-df"},{"title":"Altinget: Pia Kjærsgaard ærgrer sig over uro i partiet (19. september 2021)","url":"https://www.altinget.dk/artikel/pia-kjaersgaard-aergrer-sig-over-uro-i-partiet-hvorfor-skal-der-saettes-spoergsmaalstegn-ved-vores-allervigtigste-maerkesag"},{"title":"Altinget: Efter formandsopgøret venter et endnu mere destruktivt drama i DF (11. januar 2022)","url":"https://www.altinget.dk/artikel/efter-formandsopgoeret-venter-et-endnu-mere-destruktivt-drama-i-dansk-folkeparti"},{"title":"Altinget: Messerschmidt svigter Pia Kjærsgaard (28. august 2024)","url":"https://www.altinget.dk/artikel/messerschmidt-svigter-pia-kjaersgaard"},{"title":"Altinget: Pia Kjærsgaard genopstiller ikke til Folketinget (13. september 2024)","url":"https://www.altinget.dk/artikel/pia-kjaersgaard-genopstiller-ikke-til-folketinget"},{"title":"Altinget: Når DF taler om remigration, henter de ordene fra en højreradikal bevægelse (9. marts 2026)","url":"https://www.altinget.dk/etik/artikel/naar-dansk-folkeparti-taler-om-remigration-henter-de-ordene-fra-kontroversiel-hoejreradikal-bevaegelse"},{"title":"The Local: Danish far-right party wants to strip permanent residency (19. marts 2026)","url":"https://www.thelocal.dk/20260319/danish-far-right-party-wants-to-strip-permanent-residency-from-foreign-nationals"},{"title":"TV 2: Venstre bløder vælgere til to overraskende partier (oktober 2026)","url":"https://nyheder.tv2.dk/politik/2026-10-23-venstre-bloeder-vaelgere-til-to-overraskende-partier"},{"title":"Arbejderen: Finanslovsforslaget for 2027 (16. oktober 2026)","url":"https://www.arbejderen.dk/indland/finanslovsforslaget-for-2027-indeholder-baade-store-investeringer-og-haarde-nedskaeringer/"},{"title":"nyheder.dk: Afgift på benzin og diesel sænkes med to kroner (12. november 2026)","url":"https://www.nyheder.dk/nyheder/saenker-afgifter-pa-benzin-og-diesel/2539451"},{"title":"Folketingets sagsdata (oda.ft.dk): B 16, B 17, B 42, B 60, B 61","url":"https://oda.ft.dk/api/Sag(106183)"},{"title":"Altinget: DF bløder medlemmer (18. september 2021)","url":"https://www.altinget.dk/artikel/df-bloeder-medlemmer-rammer-laveste-antal-i-14-aar"},{"title":"Altinget: DF vil give karakterer fra 4. klasse (9. februar 2024)","url":"https://www.altinget.dk/artikel/df-vil-give-karakterer-fra-4-klasse"},{"title":"Tekniq: DF vil fordoble pulje til renovering (11. oktober 2019)","url":"https://www.tekniq.dk/nyheder/df-vil-fordoble-pulje-til-renovering/"},{"title":"Altinget: DF: Ghetto-regning skal ikke bare sendes videre til lejerne (17. april 2018)","url":"https://www.altinget.dk/artikel/df-ghetto-regning-skal-ikke-bare-sendes-videre-til-lejerne"},{"title":"Altinget/Danva: Sprøjteforbud (18. marts 2026)","url":"https://www.altinget.dk/foedevarer/artikel/danva-massivt-vaelgerflertal-vil-have-sproejteforbud"}],"order":11,"color":"#EAC73E","on":"#12161C","blok":"blå","officialName":"Dansk Folkeparti","nick":"DF"},{"id":"dd","letter":"Æ","name":"Danmarksdemokraterne","short":"DD","founded":"2022","foundedNote":"Partiet blev stiftet 23. juni 2022 af Inger Støjberg, efter at hun i 2021 var idømt 60 dages fængsel i en ministeransvarssag og havde afsonet med fodlænke. Det fik bogstavet Æ i juli 2022 og 14 mandater ved første valg 1. november 2022.","leader":{"name":"Inger Støjberg","title":"Partiformand","since":"2022","born":"1973","bio":"Født 1973 i Hjerk ved Skive. Medlem af Venstres Ungdom fra 1993 og næstformand i Venstre, indtil hun trådte tilbage i december 2020 og forlod partiet i februar 2021. Blev i december 2021 idømt 60 dages fængsel i en ministeransvarssag og afsonede med fodlænke. Stiftede Danmarksdemokraterne i juni 2022 og har været partiets klare figur siden."},"role":"opposition","roleNote":"Danmarksdemokraterne er uden for regeringen og er ikke formelt støtteparti for firkløverregeringen. Partiet har i maj 2026 sagt, at det vil være støtteparti for en regering ledet af den borgerlige side. I efteråret 2026 fremsætter partiet forslag om udlændinge, afgifter og kultur og stemmer ofte sammen med DF og LA.","ideology":["Nationalkonservatisme","Liberalisme","Højrepopulisme"],"euGroup":"ECR (Europæiske Konservative og Reformister), med ét mandat i Europa-Parlamentet valgt i 2024","youth":{"name":"Danmarksdemokraternes Ungdom","note":"Partiets ungdomsorganisation."},"website":"https://danmarksdemokraterne.dk","oneLiner":"Stram udlændingepolitik, nær sundhed og produktion i hele landet, fra Inger Støjbergs parti stiftet i 2022.","summary":"Danmarksdemokraterne vil have en markant stram udlændingepolitik, hvor udlændinge skal tilpasse sig dansk kultur og samfund. Partiet vil flytte fokus fra de store byer til provinsen med bedre adgang til læger, mobildækning og veje. Det vil bruge høje skatteindtægter til velfærd som ældrepleje og fastholde den såkaldte Arne-pension for mennesker, der er slidt ned tidligt. Klimapolitik må ikke unødigt ramme erhverv og landbrug, og partiet taler om Produktionsdanmark med vægt på små og mellemstore virksomheder. Efter valgnederlaget i marts 2026 vil Støjberg udvide partiets base ud over Jylland.","pitch":"Vi tager udlændingeproblemet alvorligt og siger det højt. Vi vil have læger, mobildækning og veje i hele landet, ikke kun i storbyerne. Dem der har slidt sig op, skal kunne gå tidligt på pension, og de høje skatter skal bruges på ældreplejen. Hvis du vil have en stram udlændingepolitik og en stemme for provinsen, er det her, vi står.","critique":"Kritikerne siger, at partiet næsten kun har ét stort emne, nemlig udlændingepolitik, og at det ikke har en bred nok profil til at blive et regeringsparti. De peger på, at partiet har mistet over en fjerdedel af sine stemmer fra 2022 til 2026 (8,1 pct. til 5,8 pct.), og at Støjbergs dom fra 2021 gør hende svag som leder for et parti, der vil være med til at regere. Altinget-kommentatorer mener, at partiet ikke har råd til at profilere sig på andet end udlændinge.","keyIssues":[{"title":"Hjemsendelse og asyl","detail":"Partiet har i november 2026 fremsat forslaget B 57 om en håndfast hjemsendelsespolitik og forslaget B 52 om at fjerne muligheden for at søge spontant asyl i Danmark. Asylansøgere skal i stedet henvises til et dansk modtagecenter i et tredjeland."},{"title":"Stram linje over for ekstremisme","detail":"Partiet har fremsat forslaget B 61 om forbud mod Hizb ut-Tahrir (13. november 2026)."},{"title":"Lavere brændstofafgifter","detail":"Forslaget B 58 vil sænke benzin-, diesel- og gasafgifterne og forlænge det forhøjede befordringsfradrag (13. november 2026). Partiet har også spurgt regeringen, om den er enig i at sænke afgifterne (F 1, 21. oktober 2026)."},{"title":"Velfærd og ældrepleje","detail":"Partiet vil have nationale standarder for dansk i ældreplejen (B 19) og ældres ret til at vælge kød i måltiderne (B 20). Det har også spurgt til underernæring blandt ældre (F 6, 12. november 2026)."},{"title":"Provinsen og nærhed","detail":"Partiet vil flytte ressourcer og opmærksomhed fra de store byer til provinsen med bedre adgang til læger, mobildækning og veje."}],"positions":{"udlaendinge":{"score":5,"text":"Partiet vil have en markant stram udlændingepolitik og forventer, at udlændinge tilpasser sig dansk kultur og samfund. Det vil fjerne muligheden for spontan asyl i Danmark (B 52), gennemføre en håndfast hjemsendelsespolitik (B 57) og have Mohamed Abdirahman Kahn udvist (B 11)."},"oekonomi":{"score":3,"text":"Partiet vil sænke benzin-, diesel- og gasafgifterne og forlænge det forhøjede befordringsfradrag (B 58). Partiet stemte i november 2026 imod nulmoms på bøger (L 36 B) og imod L 5 om gødskning i land- og skovbruget og L 16 om beløbsordningen. Det går ind for Produktionsdanmark, dvs. små og mellemstore virksomheder og selvstændige."},"arbejdsmarked":{"score":2,"text":"Partiet vil fastholde Arne-pensionen, den tidlige pension for mennesker, der er slidt ned. Det giver tryghed for slidte, men partiet har ikke fremsat forslag om at øge arbejdsudbuddet."},"velfaerd":{"score":2,"text":"Partiet vil bruge høje skatteindtægter på velfærd, fx ældrepleje. Det har fremsat forslag om danskkundskaber for medarbejdere i ældreplejen (B 19) og ældres ret til kød i madservicen (B 20)."},"sundhed":{"score":2,"text":"Partiet lægger vægt på 'nær sundhed' og bedre adgang til læger i provinsen. Forslag i 2026 handler om hjemtransport af afdøde patienter (B 43), at BPA-hjælpere må udføre lette sundhedsopgaver (B 7) og om at gøre ledsagerordningen for blinde permanent (B 9)."},"klima":{"score":4,"text":"Partiet vil ikke have klimapolitik, der unødigt rammer erhverv og landbrug. Det vil afskaffe reparationsgrænsen for elbiler (B 10) og genindføre dispensation til højtryksspuling af asbesttage (B 3)."},"natur_landbrug":{"score":5,"text":"Partiet vil have færre krav til landbruget. Det stemte imod gødningsloven (L 5) og vil frakende Danmarks Naturfredningsforening retten til alene at rejse fredningssager (B 27)."},"eu":{"score":4,"text":"Partiet sidder i ECR-gruppen i Europa-Parlamentet, en EU-kritisk gruppe. I Folketinget stemte partiet imod EU's migrations- og asylpagt (L 15, 27. august 2026)."},"forsvar":{"score":4,"text":"Partiet har ikke fremsat forsvarsforslag i efteråret 2026, og forsvar er ikke et af partiets profilområder."},"ret":{"score":5,"text":"Partiet vil forbyde Hizb ut-Tahrir (B 61) og udvide børneattesten til at omfatte seksuelle overgreb og vold mod personer under 18 år (B 8). Det har også fremsat et tildækningsforbud på uddannelsessteder (L 41)."},"bolig":{"score":3,"text":"Partiet vil have 15.000 flere parkeringspladser i Københavns Kommune inden 2035 og undtage kommunale parkeringsanlæg fra anlægsloftet (B 37). Partiet går ind for mindre regulering af boligsektoren."},"uddannelse":{"score":3,"text":"Partiet vil forbyde kommuner at udbyde modersmålsundervisning i sprog uden for EU/EØS (B 15) og har fremsat et tildækningsforbud på uddannelsessteder (L 41). Kampagnen 'DE SKAL UD!' retter sig mod dominanskultur på erhvervsuddannelserne."}},"history":[{"year":"2020","event":"Støjberg trækker sig som næstformand i Venstre i december og forlader Venstre i februar 2021."},{"year":"2021","event":"Støjberg idømmes i december 60 dages fængsel i en ministeransvarssag og erklæres uskikket til at sidde i Folketinget."},{"year":"2022","event":"Partiet stiftes 23. juni 2022 og får bogstavet Æ 7. juli. Ved valget 1. november 2022 får det 8,1 pct. og 14 mandater."},{"year":"2024","event":"I marts kommer Mads Fuglede fra Venstre og Kim Edberg som løsgænger, og partiet har 16 mandater. Ved EP-valget vinder partiet ét mandat med Kristoffer Storm som spidskandidat."},{"year":"2025","event":"Partiet får 123 byrådsmandater og 7 regionsrådsmandater ved kommunalvalget. I september præsenterer partiet udspillet 'Flere hjem, færre hertil' med 45 udlændingestramninger på landsmødet i Herning."},{"year":"2026","event":"Ved folketingsvalget 24. marts 2026 falder partiet til 5,8 pct. og 10 mandater, en tilbagegang på fire mandater."},{"year":"2026","event":"I maj 2026 meldte Støjberg ud, at partiet vil være støtteparti for en borgerlig-ledet regering og ikke vil sidde i regeringen."},{"year":"2026","event":"Ved landsmødet i Herning i oktober 2026 lægger Støjberg størstedelen af sin tale på udlændingepolitik og siger, at partiet vil udvide sin base ud over Jylland."},{"year":"2026","event":"I november 2026 stemmer partiet imod nulmoms på bøger sammen med LA, og det fremsætter forslag om benzinafgiften og Hizb ut-Tahrir."}],"people":[{"name":"Inger Støjberg","role":"Partiformand og folketingsmedlem","note":"Partiets dominerende figur, dømt i 2021 og stifter af partiet i 2022."},{"name":"Susie Jessen","role":"Politisk ordfører og folketingsmedlem","note":"Har fremsat lovforslaget om tildækningsforbud på uddannelsessteder (L 41) og fik partiets mandat i Sjælland ved valget 2026."},{"name":"Dennis Flydtkjær","role":"Folketingsmedlem","note":"Fremsætter forslag om hjemsendelse, asyl og Hizb ut-Tahrir."},{"name":"Hans Kristian Skibby","role":"Folketingsmedlem","note":"Står bag forslaget om lavere benzin- og dieselafgifter (B 58) og forslaget om elbil-reparation (B 10)."},{"name":"Mads Fuglede","role":"Folketingsmedlem, kom fra Venstre i 2024","note":"Fremsatte forslaget om en ny national strategi for bølgekraft (B 46)."},{"name":"Karina Adsbøl","role":"Folketingsmedlem","note":"Har fremsat forslag om ledsagerordningen for blinde og om Familieretshuset (F 5)."},{"name":"Marlene Harpsøe","role":"Folketingsmedlem","note":"Fremsætter forslag om ældreplejen, herunder underernæring blandt ældre (F 6)."}],"voters":{"summary":"Danmarksdemokraternes vælgere er typisk ældre og bor uden for de største byer. Partiet kom fra Venstre og DF og har især vundet vælgere, der vil have en stram udlændingepolitik. I Voxmeter 9. nov. 2026 står partiet til 6,1 pct., lidt over valgresultatet fra marts.","strongholds":"Jylland og provinsen er partiets oprindelige stærke område, og Støjberg vil nu udvide basen til andre dele af landet.","demographics":"Vælgerne er typisk ældre og har ofte tilknytning til små virksomheder, håndværk og landbrug, som det ses for nationalkonservative partier i almindelighed."},"election2026":{"note":"Partiet fik 5,8 pct. og 10 mandater ved valget 24. marts 2026, ned fra 8,1 pct. og 14 mandater i 2022. Altinget (26. marts 2026) tilskriver tilbagegangen primært Dansk Folkeparti, der kørte en stærk kampagne med en velfyldt kampagnekasse. Støjberg har selv sagt, at kampagnevilkårene ikke var gunstige, og at partiet må udvide sin base."},"strengths":["Klar profil på udlændingepolitik, som gør partiet genkendeligt","Fremgang i målinger og ny medlemstilgang efter valget: 6,1 pct. i Voxmeter 9. nov. 2026","Samlet ledelse under Støjberg uden synlige fløjkampe, ifølge Altinget"],"weaknesses":["Har mistet over en fjerdedel af stemmerne siden 2022","Afhængig af Støjberg som den eneste stærke profil","Begrænset profil uden for udlændingepolitik, ifølge en Altinget-kommentar"],"internalTensions":[{"title":"Støjberg som dominerende skikkelse","detail":"Partiet er samlet om Støjberg, men det er sårbart, hvis hun træder tilbage. Altinget beskriver partiet som uden fløjkampe, men med hende som den klare figur."},{"title":"Udvidelse af basen","detail":"Støjberg vil bredde partiet ud over 'jydepartiet'-stemplet. En Altinget-kommentator mener, at partiet ikke har råd til at profilere sig på andet end udlændinge."}],"typicalArguments":[{"claim":"Udlændinge skal tilpasse sig dansk kultur og samfund, og udlændingepolitikken skal strammes markant.","counter":"Kritikere siger, at partiet har ét stort emne, og at en stram linje alene ikke løser de udfordringer, partiet peger på."},{"claim":"Provinsen er blevet glemt af storbyerne, og ressourcerne skal flyttes ud.","counter":"Modstandere siger, at flytning af ressourcer uden konkrete budgetter er et løfte uden indhold."},{"claim":"Høje skatteindtægter skal bruges på velfærd som ældrepleje.","counter":"Kritikere mener, at høje skatter svækker erhvervslivet, og at det modsiger partiets egen linje om småerhverv og lavere brændstofafgifter."},{"claim":"Klimapolitikken må ikke unødigt ramme erhverv og landbrug.","counter":"Modstandere mener, at landbrugets udledning kræver krav, og at en svækket klimaindsats koster mere på sigt."},{"claim":"Brændstofafgifterne skal sænkes, så almindelige familier kan betale for at køre på arbejde.","counter":"Kritikere mener, at lavere afgifter øger forbruget og klimaudledningen, og at effekten er midlertidig."}],"vsDF":{"agree":["Forslaget om afskaffelse af koranloven fik støtte fra både DD og DF, men blev forkastet 1. oktober 2026.","Begge partier stemte imod EU's migrations- og asylpagt (L 15, 27. august 2026), imod gødningsloven (L 5) og imod V 1, statsministerens åbningsredegørelse (8. oktober 2026)."],"disagree":["Nulmoms på bøger (L 36 B, 12. november 2026): DD stemte imod sammen med LA, mens DF stemte for.","Statsrevisorernes valg (B 16, 3. september 2026): DD stemte alene imod, mens DF stemte for.","Benzin- og dieselafgift: DF fik i november 2026 en aftale med regeringen om en midlertidig sænkning på ca. 2 kr. pr. liter. DD er ikke med i aftalen og har selv fremsat forslaget B 58.","EU-gruppe: DD sidder i ECR, mens DF sidder i ID-gruppen."],"note":"DD og DF konkurrerer om de samme udlændingefokuserede vælgere. Altinget (26. marts 2026) tilskriver DD's tilbagegang til DF's kampagne. DF har en parlamentarisk aftale med regeringen om afgifter, mens DD står udenfor og forsøger at vinde pladsen som det borgerlige støtteparti ved at fremsætte egne forslag."},"vocabulary":[{"term":"Produktionsdanmark","meaning":"Partiets begreb for en produktionsdrevet dansk økonomi med fokus på små og mellemstore virksomheder og selvstændige."},{"term":"Flere hjem, færre hertil","meaning":"Titlen på partiets udspil med 45 udlændingestramninger, præsenteret i september 2025."},{"term":"Arne-pensionen","meaning":"Tidlig pension for mennesker, der er slidt ned, som partiet vil fastholde."},{"term":"DE SKAL UD!","meaning":"Kampagne på partiets forside mod dominanskultur på erhvervsuddannelserne."}],"funFacts":["Støjberg blev i 2021 idømt 60 dages fængsel i en ministeransvarssag og afsonede med fodlænke hjemme i Hadsund. Det er baggrunden for partiets stiftelse.","Partiet fik bogstavet Æ 7. juli 2022, kort efter stiftelsen.","Partiets forside beskriver det som et parti for hele Danmark, ikke kun for storbyerne."],"sources":[{"title":"Danmarksdemokraterne, forside","url":"https://danmarksdemokraterne.dk/forside"},{"title":"Danmarksdemokraterne (da.wikipedia)","url":"https://da.wikipedia.org/wiki/Danmarksdemokraterne"},{"title":"Inger Støjberg (lex.dk)","url":"https://lex.dk/Inger_Støjberg"},{"title":"Folketingets forslag og forespørgsler fra DD (oda.ft.dk)","url":"https://www.ft.dk/samling/20261/beslutningsforslag/B57/index.htm"},{"title":"Folketingets afstemninger (oda.ft.dk)","url":"https://www.ft.dk/samling/20261/lovforslag/L36/index.htm"},{"title":"Efter vælgerlussing vil Støjberg udvide basen (Altinget, 23. okt. 2026)","url":"https://www.altinget.dk/artikel/efter-vaelgerlussing-vil-stoejberg-udvide-basen-vi-er-ikke-et-jydeparti"},{"title":"Holstein missede ét svar (Altinget, 23. okt. 2026)","url":"https://www.altinget.dk/artikel/holstein-missede-et-svar-kender-du-stoejbergs-vaelgere-bedre-end-ham"},{"title":"DFs benzinstunt og kampagnekasse stjal DDs momentum (Altinget, 26. mar. 2026)","url":"https://www.altinget.dk/christiansborg/artikel/dfs-benzinstunt-og-velpolstrede-kampagnekasse-stjal-danmarksdemokraternes-momentum-siger-partiprofiler"},{"title":"Støjberg og Vanopslagh nedtoner stridigheder med V (Altinget, 12. maj 2026)","url":"https://www.altinget.dk/christiansborg/artikel/stoejberg-og-vanopslagh-nedtoner-stridigheder-med-v-vi-har-et-ultimativt-krav-og-det-er-en-blaa-statsminister"},{"title":"I Herning søgte Støjberg tilbage til sit yndlingsemne (Altinget, 27. sep. 2025)","url":"https://www.altinget.dk/klima/artikel/i-herning-soegte-stoejberg-tilbage-til-sit-yndlingsemne-vi-har-brug-for-at-smide-den-fodlaenke"},{"title":"Benzin og diesel bliver billigere med ny skatteaftale (ing.dk)","url":"https://ing.dk/artikel/medie-benzin-og-diesel-bliver-billigere-med-ny-skatteaftale"},{"title":"Voxmeter-målinger (politpro.eu)","url":"https://politpro.eu/da/danmark/analyseinstitutter/voxmeter"}],"order":10,"color":"#7896D2","on":"#12161C","blok":"blå","officialName":"Danmarksdemokraterne","nick":"Danmarksdemokraterne"},{"id":"el","letter":"Ø","name":"Enhedslisten","short":"EL","founded":"1989","foundedNote":"Partiet blev stiftet i april 1989 som et samarbejde mellem Venstresocialisterne, Danmarks Kommunistiske Parti og Socialistisk Arbejderparti. Partiet har ingen formand men en kollektiv ledelse, og det er det eneste parti i Folketinget uden formand.","leader":{"name":"Pelle Dragsted","title":"Politisk ordfører, de facto leder i den kollektive ledelse","since":"2023","born":"1975","bio":"Født 1975 i København. Historiker fra Københavns Universitet (2001) og master i retorik og kommunikation fra Aarhus Universitet (2016). Partiets internationale sekretær i 2005, pressechef i 2009 og rådgiver 2011–2015. Folketingsmedlem 2015–2019 og igen fra 2022. Efterfulgte Mai Villadsen som politisk ordfører i august 2023 og er partiets klare talsmand. Dømt i 1998 for hærværk ved Sandholm-lejren; har siden taget afstand fra vold."},"role":"støtteparti","roleNote":"Enhedslisten støtter firkløverregeringen (Socialdemokratiet, SF, Moderaterne og Radikale Venstre) udefra og er ikke med i regeringen. Dragsted har sagt, at målet om gratis tandlæge i 2035 står ord for ord i regeringsgrundlaget. Partiet forhandler finansloven for 2027 (L 73) og har sagt, at det ikke vil stemme for en finanslov med SU-forringelser for hjemmeboende og skærpede dagpengekrav for nyuddannede.","ideology":["Rød-grøn","Socialistisk","Ligheds- og velfærdspolitik"],"euGroup":"The Left (GUE/NGL) i Europa-Parlamentet","youth":{"name":"Rød-Grøn Ungdom","note":"Partiet har ingen formel ungdomsorganisation, men samarbejder med Rød-Grøn Ungdom siden 2020. Samarbejdet med Socialistisk Ungdomsfront blev ophørt i 2025."},"membersCount":"8.395 (2024)","website":"https://enhedslisten.dk","oneLiner":"Støtteparti for regeringen med kollektiv ledelse: gratis tandlæge, gratis transport for unge og opgør med ulighed.","summary":"Enhedslisten vil have et mere lige samfund med stærk velfærd, gratis tandlæge og gratis bus og tog for unge. Partiet vil betale for det ved at fjerne skattelettelser til høje indkomster og modsætte sig en selskabsskattesænkning fra 2030. Enhedslisten har kollektiv ledelse, og Pelle Dragsted er den klare talsmand. Partiet støtter firkløverregeringen udefra, men er ikke med i regeringen. Partiet er EU-kritisk, men i maj 2026 blev udmeldelse af EU gjort til et perspektiv i stedet for et mål i sig selv.","pitch":"Vi står for, at det ikke er rimeligt, at nogle har alt, mens andre ikke har råd til tandlæge eller bus. Vi vil have gratis tandlæge, gratis transport for unge og bedre dagpenge, og vi finansierer det ved at droppe skattelettelser til de højeste indkomster. Vi støtter regeringen, når den gør det rigtige, og siger nej, når den ikke gør.","critique":"Kritikerne siger, at kravene ikke er finansierede, og at partiet kan gøre en regering afhængig af sig uden at tage ansvar for den. De peger på interne konflikter, herunder en fraktion, der blev fordømt på en ekstraordinær generalforsamling i december 2024. Ved årsmødet i maj 2026 var der delegerede, der var kritiske over for at give Lars Løkke Rasmussen en ministerpost.","keyIssues":[{"title":"Gratis tandlæge","detail":"Partiet kræver en konkret plan. Dragsted siger, at målet om gratis tandlæge for alle i 2035 står ord for ord i regeringsgrundlaget, og at op til 1,5 mio. danskere skal dækkes i perioden (12. juni 2026)."},{"title":"Gratis transport for unge","detail":"Gratis bus og tog for under 22-årige fra næste år. Regeringsgrundlaget har afsat 2 mia. kr. til gratis offentlig transport for unge under 22 år, men uden tidsplan (29. september 2026)."},{"title":"Ingen SU- og dagpengeforringelser","detail":"Partiet vil droppe forslaget om at fjerne SU for hjemmeboende studerende, hvis forældre tjener over ca. 710.000 kr., og de skærpede dagpengekrav for nyuddannede (20. oktober 2026)."},{"title":"Ingen skattelettelser til høje indkomster","detail":"Partiet vil droppe en skattelettelse til indkomster over ca. 58.000 kr. brutto om måneden og modsætter sig en selskabsskattesænkning på tre procentpoint fra 2030 (20. oktober 2026)."},{"title":"Seniorpension","detail":"Partiet kalder regeringens forslag om at stramme seniorpensionen 'asocialt', og det glædede partiet, da regeringen droppede det (20. oktober 2026)."}],"positions":{"udlaendinge":{"score":1,"text":"Partiet stemte 27. august 2026 for at gennemføre dele af EU's migrations- og asylpagt (L 15) og stemte 1. oktober 2026 for at afskaffe koranloven."},"oekonomi":{"score":1,"text":"Partiet vil droppe skattelettelser til indkomster over ca. 58.000 kr. om måneden og modsætter sig en selskabsskattesænkning på tre procentpoint fra 2030."},"arbejdsmarked":{"score":1,"text":"Partiet vil ikke have dagpengene forringet for nyuddannede, og det vil ikke have seniorpensionen stramt. Dragsted kalder seniorpensionsforslaget 'asocialt'. Partiet ønsker en kortere kvalifikationsperiode til dagpenge."},"velfaerd":{"score":1,"text":"Partiets hovedkrav er gratis tandlæge og gratis bus og tog for unge under 22 år. Det er den mest offentlige linje i Folketinget."},"sundhed":{"score":1,"text":"Gratis tandlæge for alle i 2035 er partiets krav i regeringsgrundlaget. Partiet vil have offentlig finansiering."},"klima":{"score":1,"text":"Partiet vil have en hurtig og vidtgående grøn omstilling. Det har fremsat forslaget B 39 om et midlertidigt stop for nye datacentre (2. november 2026) og forslaget B 62 om forbud mod datacentres tilslutning til gasnettet (13. november 2026). Det står udenfor den grønne skattereform, som regeringen har indgået med andre partier."},"natur_landbrug":{"score":1,"text":"Partiet er med i borgerforslagene om forbud mod industriel svineproduktion (B 30) og om udledning af urenset spildevand (B 29), begge fremsat i oktober 2026."},"eu":{"score":4,"text":"Partiet er EU-kritisk, men i maj 2026 blev udmeldelse af EU gjort til et perspektiv i stedet for et mål i sig selv. Partiet stemte 27. august 2026 for EU's migrations- og asylpagt (L 15). Dragsted har skrevet, at han stemmer nej til en folkeafstemning om forsvarsforbeholdet."},"forsvar":{"score":2,"text":"Partiet stemte i 2023 for militær oprustning og er kritisk over for forsvarsforbeholdet. Forsvar er ikke et centralt emne i partiets fremsatte forslag i efteråret 2026."},"ret":{"score":1,"text":"Partiet stemte imod at skærpe reglerne for udvisning af udenlandske kriminelle med ubetinget fængselsstraf på mindst et år (L 17 A, 3. september 2026)."},"bolig":{"score":1,"text":"Før valget i 2026 gjorde Dragsted huslejepriser til et topkrav for partiet, og partiet vil have lavere boligudgifter for lejere."},"uddannelse":{"score":1,"text":"Partiet vil ikke have SU fjernet for hjemmeboende studerende, og det vil have gratis transport for unge under 22 år."}},"history":[{"year":"1989","event":"Partiet stiftes i april som et samarbejde mellem Venstresocialisterne, DKP og SAP."},{"year":"1994","event":"Partiet får 6 mandater og bliver støtteparti for Socialdemokratiets regering."},{"year":"2001","event":"Partiet stifter sin ungdomsorganisation SUF og taber et mandat ved valget."},{"year":"2011","event":"Partiet får 12 mandater og indgår en finanslovsaftale med den nye regering."},{"year":"2012","event":"Partiet stemmer for en finanslov for første gang i januar. I juni stopper støtten til regeringen over en skattereform."},{"year":"2019","event":"Partiet er en del af det parlamentariske grundlag for Mette Frederiksens regering frem til 2022."},{"year":"2023","event":"Pelle Dragsted bliver politisk ordfører i august. En fraktion bryder ud i protest, og partiet stemmer for militær oprustning."},{"year":"2024","event":"Ved en ekstraordinær generalforsamling 14. december fordømmes fraktionens handlinger, og reglerne for udelukkelse strammes."},{"year":"2025","event":"Samarbejdet med Socialistisk Ungdomsfront ophører."},{"year":"2026","event":"Ved folketingsvalget 24. marts 2026 får partiet 6,3 pct. og 11 mandater, to flere end i 2022."},{"year":"2026","event":"I maj 2026 ved årsmødet i Valby kræver Dragsted, at de partier, der forhandler regering, nærmer sig hinanden. Ved samme årsmøde blev målet om udmeldelse af EU gjort til et perspektiv."},{"year":"2026","event":"Firkløverregeringen dannes 3. juni 2026, og Enhedslisten støtter den udefra. I juni siger Dragsted, at gratis tandlæge i 2035 står i regeringsgrundlaget."},{"year":"2026","event":"I september 2026 kræver Dragsted gratis bus og tog for unge som hovedkrav i finanslovsforhandlingerne. I oktober 2026 siger partiet, at det ikke vil stemme for en finanslov med SU- og dagpengeforringelser."}],"people":[{"name":"Pelle Dragsted","role":"Politisk ordfører og folketingsmedlem","note":"Partiets klare talsmand. Han forhandler finansloven med regeringen og står bag kravene om gratis tandlæge og gratis transport for unge."},{"name":"Eva Flyvholm","role":"Folketingsmedlem og EU-ordfører","note":"Fremsætter forslaget om et midlertidigt stop for nye datacentre (B 39)."},{"name":"Lisbeth Torfing","role":"Folketingsmedlem","note":"Fremsætter forslaget om forbud mod datacentres tilslutning til gasnettet og fossile generatorer (B 62)."},{"name":"Peder Hvelplund","role":"Folketingsmedlem og medlem af den kollektive ledelse","note":"En af de personer, der står for partiets kollektive ledelse."},{"name":"Sinem Dybvad Demir","role":"Folketingsmedlem","note":"Stemte imod L 15, EU's migrationspagt, mens partiet som helhed stemte for."},{"name":"Rosa Lund","role":"Folketingsmedlem","note":"Medlem af partiets folketingsgruppe."}],"voters":{"summary":"Enhedslistens vælgere er typisk yngre, uddannede og ofte ansat i den offentlige sektor. Partiet har en stærk position blandt vælgere, der vil have mere velfærd og større lighed. I Voxmeter 9. nov. 2026 står partiet til 8,9 pct., over valgresultatet på 6,3 pct. i marts.","strongholds":"Storbyerne, særligt de centrale bydele i København og Aarhus.","demographics":"Yngre, uddannede og offentligt ansatte er overrepræsenteret, og partiet har en stor andel af vælgere under 40 år."},"election2026":{"note":"Partiet fik 6,3 pct. og 11 mandater ved valget 24. marts 2026, to flere end i 2022. Partiet har haft indflydelse på velfærdsspørgsmål i de seneste år og har nu sat gratis tandlæge og gratis transport for unge som sine vigtigste krav."},"strengths":["Stabil opbakning på 6–9 pct. og 11 mandater","Klar profil på velfærd og lighed: gratis tandlæge og transport for unge er faste krav","Stærk parlamentarisk front med Pelle Dragsted som talsmand"],"weaknesses":["Ingen formand, og den kollektive ledelse gør det svært at pege på én leder","Konflikter i partiet, herunder fraktionsbruddet i 2023 og den strammede udelukkelsesregel i 2024","Støtte udefra giver begrænset indflydelse uden ministerposter","Målet om udmeldelse af EU er blødt op i maj 2026, hvilket er omstridt i partiet"],"internalTensions":[{"title":"Regeringsstøtte og Løkke","detail":"Dragsted har bagland for at arbejde for et flertal, men ikke alle delegerede vil have en regering med Lars Løkke Rasmussen som minister (ved årsmødet i maj 2026)."},{"title":"Fraktionskonflikt 2023–2024","detail":"En fraktion brød ud i 2023 i protest. Ved en ekstraordinær generalforsamling i december 2024 blev fraktionens handlinger fordømt, og reglerne for udelukkelse blev strammet."},{"title":"EU-udmeldelse","detail":"Ledelsen foreslog i maj 2026 at droppe målet om udmeldelse. Kompromiset siger, at udmeldelse ikke er et mål i sig selv, men at den kan blive relevant, hvis EU bevæger sig i en centralistisk retning."}],"typicalArguments":[{"claim":"Gratis tandlæge og gratis transport for unge er ikke luksus, men lighed, og det står i regeringsgrundlaget.","counter":"Modstandere siger, at gratis ydelser koster milliarder, og at regeringen kun har afsat 2 mia. kr. til transport uden tidsplan."},{"claim":"Skattelettelser til de højestlønnede skal væk, og pengene skal bruges på velfærd.","counter":"Kritikere mener, at høje skatter på højtlønnede svækker arbejdsudbuddet og investeringerne."},{"claim":"Seniorpension og dagpenge må ikke forringes, for det rammer de slidte og de unge.","counter":"Modstandere mener, at stramninger er nødvendige for at holde velfærdssystemet bæredygtigt og øge arbejdsudbuddet."},{"claim":"EU er ikke et mål i sig selv. Partiet er kritisk, men vil ikke ud, medmindre EU bliver mere centralistisk.","counter":"Kritikere mener, at en betinget udmeldelse er uklar, og at partiet ikke har en klar EU-politik."},{"claim":"Den grønne omstilling skal være hurtig og vidtgående, og datacentre må ikke få lov til at bruge fossile generatorer.","counter":"Modstandere siger, at et stop for nye datacentre skader Danmarks digitale konkurrenceevne og investeringer."}],"vsDF":{"agree":["Afskaffelse af koranloven: EL og DF stemte begge for (B 6, 1. oktober 2026). Forslaget blev forkastet.","Begge partier stemte imod styrkelse af hjemrejsestøtteordningen og repatrieringsordningen (L 17 B, 3. september 2026)."],"disagree":["EU's migrations- og asylpagt (L 15, 27. august 2026): EL stemte for, mens DF stemte imod.","Gødningsloven (L 5, 3. september 2026): EL stemte for, mens DF stemte imod.","Beløbsordningen for certificerede virksomheder (L 16, 3. september 2026): EL stemte for, mens DF stemte imod.","EU-gruppe: EL sidder i The Left, mens DF sidder i ID-gruppen."],"note":"EL og DF deler en EU-kritisk tilgang og et ønske om at beskytte de slidte ældre, men de er uenige om udlændinge, klima, skat på høje indkomster og EU-gruppe. EL står udenfor den grønne skattereform og har kritiseret, at regeringen ikke gør mere for klimaet. DF har lavet en benzinafgiftsaftale med regeringen, som EL ikke er med i."},"vocabulary":[{"term":"Kollektiv ledelse","meaning":"Partiet har ingen formand. Ledelsen er fordelt på flere personer, og den politiske ordfører er den klare talsmand."},{"term":"Støtteparti","meaning":"Et parti, der ikke er med i regeringen, men som sikrer regeringen flertal i Folketinget."},{"term":"Regeringsgrundlaget","meaning":"Den politiske platform, som firkløverregeringen har vedtaget. Dragsted siger, at gratis tandlæge står i den ord for ord."},{"term":"Forståelsespapir","meaning":"En skriftlig aftale mellem partier om regeringsgrundlag eller støtte."}],"funFacts":["Enhedslisten er det eneste parti i Folketinget uden formand.","Partiet er med i The Left-gruppen i Europa-Parlamentet (GUE/NGL).","Partiet stemte i august 2026 for EU's migrations- og asylpagt, mens DF og DD stemte imod."],"sources":[{"title":"Enhedslisten (da.wikipedia)","url":"https://da.wikipedia.org/wiki/Enhedslisten"},{"title":"Pelle Dragsted (lex.dk)","url":"https://lex.dk/Pelle_Dragsted"},{"title":"Enhedslisten, forside","url":"https://enhedslisten.dk"},{"title":"Folketingets forslag fra EL (oda.ft.dk)","url":"https://www.ft.dk/samling/20261/beslutningsforslag/B39/index.htm"},{"title":"Folketingets afstemninger (oda.ft.dk)","url":"https://www.ft.dk/samling/20261/beslutningsforslag/B6/index.htm"},{"title":"Gratis bus og tog for unge som krav til finanslov (Ritzau, 29. sep. 2026)","url":"https://nordvestnyt.sn.dk/article/6651587/politik/stoetteparti-har-gratis-bus-og-tog-for-unge-som-hovedkrav-til-finanslov"},{"title":"Enhedslisten vil have mere end forringelse af seniorpension væk fra finanslov (Ritzau, 20. okt. 2026)","url":"https://frederiksborgamtsavis.sn.dk/article/6664906/politik/el-vil-have-mere-end-forringelse-af-seniorpension-vaek-fra-finanslov"},{"title":"Pelle Dragsted holder fast trods vaklen i regeringen (Altinget, 12. jun. 2026)","url":"https://www.altinget.dk/artikel/pelle-dragsted-holder-fast-trods-vaklen-i-regeringen-gratis-tandlaege-er-en-forudsaetning-for-vores-stoette"},{"title":"Dragsted har baglandets støtte, men ikke alle ønsker en regering med Løkke (Altinget, 26. maj 2026)","url":"https://www.altinget.dk/christiansborg/artikel/dragsted-har-baglandets-stoette-men-ikke-alle-oensker-en-regering-med-loekke"},{"title":"Enhedslisten parkerer ambitionen om et dansk farvel til EU (Altinget, maj 2026)","url":"https://www.altinget.dk/civilsamfund/artikel/enhedslisten-parkerer-ambitionen-om-et-dansk-farvel-til-eu-udmeldelse-er-ikke-et-maal-i-sig-selv"},{"title":"Pelle Dragsted om forsvarsforbeholdet (Altinget)","url":"https://www.altinget.dk/artikel/pelle-dragsted-jeg-stemmer-nej-men-tvivlen-har-naget-mig"},{"title":"Benzin og diesel bliver billigere med ny skatteaftale (ing.dk, 11. nov.)","url":"https://ing.dk/artikel/medie-benzin-og-diesel-bliver-billigere-med-ny-skatteaftale"},{"title":"Voxmeter-målinger (politpro.eu)","url":"https://politpro.eu/da/danmark/analyseinstitutter/voxmeter"}],"order":1,"color":"#E6801A","on":"#12161C","blok":"rød","officialName":"Enhedslisten – De Rød-Grønne","nick":"Enhedslisten"},{"id":"alt","letter":"Å","name":"Alternativet","short":"ALT","founded":"2013","foundedNote":"Alternativet blev præsenteret 27. november 2013 på en pressekonference på Christiansborg. Uffe Elbæk stiftede partiet sammen med Josephine Fock. Det ville have en grøn, værdibaseret politik uden for de traditionelle blokke.","leader":{"name":"Franciska Rosenkilde","title":"Partiformand / politisk leder","since":"2021","bio":"Tidligere kultur- og fritidsborgmester i København. Blev valgt til politisk leder i februar 2021, efter at Josephine Fock havde trukket sig i november 2020. Hun er stadig leder i 2026 (Altinget, maj og sommer 2026). I januar 2026 sagde hun, at hun ser Pia Olsen Dyhr som mere oplagt partner end Mette Frederiksen."},"role":"støtteparti","roleNote":"Alternativet er støtteparti for firkløverregeringen (S, SF, M og RV), der blev dannet 3. juni 2026. Partiet har ingen ministre, men er en del af det flertal, regeringen skal bruge for at få sine forslag igennem.","ideology":["grønt","værdibaseret","trivselspolitik","dyrevelfærd"],"euGroup":"ingen MEP (partiet har ingen mandater i Europa-Parlamentet)","youth":{"name":"Alternativets Unge","note":"Partiets ungdomsorganisation, stiftet i december 2016."},"website":"https://alternativet.dk","oneLiner":"Grønt parti, der vil måle politik på trivsel, klima og fællesskab, ikke kun på økonomi.","summary":"Alternativet vil have politik, der giver trivsel, grøn omstilling og et stærkt fællesskab. Partiet vil ikke kun vurdere politik ud fra økonomisk effekt, men også ud fra om det skaber trivsel og gavner klimaet og miljøet. Partiet står for dyrevelfærd, stærkere kontrol med landbruget og en mere åben udlændingepolitik end S. Det adskiller partiet fra andre grønne ved at lægge vægt på trivsel frem for vækst, og fra de traditionelle partier ved at være et bevidst værdiparti. Alternativet fik 5 mandater ved valget i 2026 og er støtteparti for regeringen.","pitch":"Vi siger det, de andre ikke siger: at økonomi er et middel og ikke et mål. Vi vil have politik, der gør danskerne trives, passer på naturen og klimaet og styrker fællesskabet. Og vi er klar til at støtte en regering, der lytter til os.","critique":"Kritikerne peger på, at Alternativet ikke har en færdig økonomisk politik. Partiets økonomiske hovedkrav om gennemgående økonomisk omstilling er ifølge Altinget (12. maj 2026) endnu ikke konkret. Tidligere folketingsmedlem Christina Olumeko har spurgt, om partiet har andet end grise på dagsordenen (Altinget). Kritikerne mener også, at partiet er for lille til at betyde reelt noget, når det står uden for regeringen.","keyIssues":[{"title":"Dyrevelfærd og kontrol","detail":"Alternativet vil afsætte 200 mio. kr. til at styrke kontrollen med dyrevelfærd i finansloven for 2027. Rosenkilde har kaldt det 'dybt kritisk', at omkring 1.500 opfølgende kontroller fra 2025 og første halvdel af 2026 ikke er udført, og kalder grisesagen en rød linje (sn.dk)."},{"title":"Trivsel som målestok for politik","detail":"Alternativet vil have politik vurderet ud fra trivsel, klima og fællesskab, ikke kun ud fra økonomisk effekt. Rosenkilde har sagt, at partiet kan 'bøje sig' på andre økonomiske tiltag, hvis de får det (Altinget, 12. maj 2026)."},{"title":"Datacentre og grøn omstilling","detail":"Alternativet har stillet forespørgsel F 4 (opdateret 4. nov. 2026) om, hvordan regeringen vil sikre, at nye datacentre dækker reelle samfundsbehov, og at deres energiforbrug ikke underminerer den grønne omstilling."},{"title":"Udlændingepolitik","detail":"Rosenkilde har sagt, at et samarbejde med S kræver 'markante ændringer' i udlændingeretorikken (Altinget, 6. jan. 2026). Alternativet stemte imod skærpede udvisningsregler (L 17 A, 3. sept. 2026)."},{"title":"Landdistrikter","detail":"Alternativet foreslår 50.000 kr. ekstra til lokalområdet, hver gang en familie flytter permanent til et mindre landdistrikt (sn.dk)."}],"positions":{"udlaendinge":{"score":1,"text":"Alternativet vil have en mere åben og menneskelig udlændingepolitik end S. Rosenkilde har sagt, at et samarbejde med S kræver markante ændringer i udlændingeretorikken (Altinget, 6. jan. 2026). Partiet stemte 3. sept. 2026 imod skærpede udvisningsregler (L 17 A) og imod en styrkelse af hjemrejsestøtten (L 17 B)."},"oekonomi":{"score":2,"text":"Alternativet vil vurdere politik ud fra trivsel, klima og fællesskab, ikke kun økonomisk effekt. Partiet har et økonomisk hovedkrav om gennemgående økonomisk omstilling, og Rosenkilde har sagt, at partiet kan give køb på andre økonomiske tiltag, hvis de får det (Altinget, 12. maj 2026). Partiet stemte for nulmoms på bøger (L 36, 12. nov. 2026)."},"arbejdsmarked":{"score":2,"text":"Alternativet lægger vægt på trivsel og fællesskab i arbejdslivet. Partiets vigtigste økonomiske og sociale prioritet i 2026 har været trivsel og en mere bred vurdering af politik."},"velfaerd":{"score":2,"text":"Alternativet vægter trivsel og fællesskab højt og har fremsat forslag om 50.000 kr. ekstra til lokalområder ved tilflytning til mindre landdistrikter (sn.dk). Partiet har fokus på dyrevelfærd og kontrol med landbruget."},"sundhed":{"score":2,"text":"Rosenkilde har gjort sig selv til partiets sundhedsprofil i en Altinget-artikel. Partiets fokus er trivsel og forebyggelse."},"klima":{"score":1,"text":"Alternativet vil prioritere klimaet i finansloven og have en grøn akutpakke. Partiet mener, at den grønne omstilling er gået helt i stå under den forrige regering (Altinget)."},"natur_landbrug":{"score":1,"text":"Alternativet vil have stærkere kontrol med dyrevelfærd og landbrug. Rosenkilde har kaldt grisesagen en rød linje, og partiet vil afsætte 200 mio. kr. til at styrke kontrollen i finansloven for 2027 (sn.dk)."},"eu":{"score":2,"text":"Alternativet er et europæisk orienteret parti, men har ingen mandater i Europa-Parlamentet. Partiet stemte 27. aug. 2026 imod at gennemføre dele af EU's migrationspagt (L 15)."},"forsvar":{"score":2,"text":"Alternativet har ikke fremsat en særlig forsvarsplan i 2026. Partiet har tidligere været skeptisk over for store forsvarsudgifter."},"ret":{"score":1,"text":"Alternativet er generelt optaget af forebyggelse og trivsel. Partiet stemte 3. sept. 2026 imod skærpede udvisningsregler (L 17 A) og imod, at en ung gerningspersons alder ikke skal kunne formildende (B 8)."},"bolig":{"score":2,"text":"Alternativet har ikke fremsat en særlig boligpolitik i 2026. Partiets prioriteter ligger i trivsel, klima og dyrevelfærd."},"uddannelse":{"score":2,"text":"Alternativet stemte imod L 21 om misbrug af studieophold 3. sept. 2026 og lægger generelt vægt på trivsel og fællesskab i uddannelse."}},"history":[{"year":"2013","event":"Alternativet præsenteres 27. november 2013 på Christiansborg af Uffe Elbæk og Josephine Fock."},{"year":"2016","event":"Alternativets Unge stiftes i december 2016."},{"year":"2020","event":"Josephine Fock træder tilbage som politisk leder i november 2020."},{"year":"2021","event":"Franciska Rosenkilde vælges som ny politisk leder på et ekstraordinært landsmøde i februar 2021."},{"year":"2022","event":"Efter valget i 2022 sidder Alternativet i opposition med 6 mandater og 3,3 pct. af stemmerne."},{"year":"2026","event":"Ved valget 24. marts 2026 får Alternativet 2,6 pct. og 5 mandater, 1 mandat mindre end i 2022."},{"year":"2026","event":"3. juni 2026 bliver Alternativet støtteparti for firkløverregeringen efter 69 dages regeringsforhandlinger."},{"year":"2026","event":"3. sept. 2026 stemmer Alternativet imod skærpede udvisningsregler (L 17 A) og imod en styrkelse af hjemrejsestøtten (L 17 B)."},{"year":"2026","event":"6. oktober 2026 trækker Alternativet støtten til Henrik Frandsen (M) som formand for Folketinget."}],"people":[{"name":"Franciska Rosenkilde","role":"politisk leder","note":"Partiets ansigt udadtil og den person, der forhandler om støtte til regeringen. Var kultur- og fritidsborgmester i København før sin tid i Folketinget."},{"name":"Torsten Gejl","role":"folketingsmedlem","note":"Oplyste 6. oktober 2026 over for TV 2, at partiet trækker støtten til Henrik Frandsen (M) som formand for Folketinget."},{"name":"Elise Sydendal","role":"folketingsmedlem","note":"Har stillet forespørgsel F 4 om datacentre og den grønne omstilling (opdateret 4. nov. 2026)."},{"name":"Anna Bjerre","role":"folketingsmedlem","note":"Medlem af Alternativets folketingsgruppe efter valget i 2026."},{"name":"Signe Wenneberg","role":"folketingsmedlem","note":"Medlem af Alternativets folketingsgruppe efter valget i 2026."}],"voters":{"summary":"Alternativets vælgere er typisk unge, grønne og urbane, og mange har en højere uddannelse. De stemmer på partiet for klima, dyrevelfærd og en mere værdibaseret politik. Partiet har svært ved at nå ud til vælgere uden for de store byer.","strongholds":"Alternativet er stærkest i de store byer og universitetsbyerne, især i København og Aarhus.","demographics":"Vælgerne er typisk under 45 år, har længere uddannelse og er ofte kvinder. Partiet har færre vælgere blandt ældre og lavt uddannede."},"election2026":{"note":"Alternativet fik 2,6 pct. og 5 mandater ved valget 24. marts 2026, mod 6 mandater og 3,3 pct. i 2022. Partiet gik tilbage under valgkampen. Rosenkilde har efterfølgende opfordret partiet til at være mere tydeligt og insisterende og vise, at det har mere politik end det grønne (Altinget, 11. maj 2026)."},"strengths":["Støtteparti for regeringen, som giver mulighed for indflydelse på finansloven","Stærk profil på dyrevelfærd og trivsel","Stabil ledelse under Rosenkilde siden 2021"],"weaknesses":["Kun 5 mandater og tæt på spærregrænsen på 2 pct.","Står uden for regeringen og må forhandle om indflydelse","Økonomisk hovedkrav er endnu ikke konkretiseret"],"internalTensions":[{"title":"Grøn spændetrøje","detail":"Altinget har skrevet om, at Alternativet i Vejle forsøgte at slippe sin grønne spændetrøje. Det afspejler en spænding mellem partiets grønne kerne og ønsket om en bredere politik."},{"title":"Partiets retning","detail":"Tidligere folketingsmedlem Christina Olumeko har kaldt på selvransagelse i partiet. Spørgsmålet er, om partiet vil være et bredt værdiparti eller et grønt specialparti."}],"typicalArguments":[{"claim":"Politik skal måles på trivsel, ikke kun på økonomisk vækst.","counter":"Kritikere mener, at trivsel er svært at måle, og at en økonomi uden vækst har svært ved at finansiere velfærden."},{"claim":"Dyrevelfærd og kontrol skal prioriteres, og 200 mio. kr. skal sikre det.","counter":"Kritikere mener, at dyrevelfærd ikke er et stort nok emne i en finanslov med store udfordringer, og at pengene bør gå til klima eller sundhed."},{"claim":"Vi har indflydelse som støtteparti, og vi bruger den til at presse regeringen på klima og udlændinge.","counter":"Kritikere siger, at Alternativet er for lille til at betyde reelt noget, og at støtten giver regeringen flertal, uden at partiet får det, det vil have."},{"claim":"Vi siger nej, når vi mener, det er nødvendigt, også til poster i Folketinget.","counter":"Kritikere mener, at partiet ved at trække støtten til Henrik Frandsen skaber usikkerhed om, hvor pålidelige støttepartierne er for regeringen."},{"claim":"Vi vil ikke være bundet af regeringen.","counter":"Partiet er støtteparti, og Rosenkilde har sagt, at Alternativet 'ikke kun er bundet til at lave politik med regeringen' (sommer 2026), hvilket kan opfattes som uklart over for vælgerne."}],"vsDF":{"agree":["Nulmoms på bøger (L 36, vedtaget 12. nov. 2026): både Alternativet og Dansk Folkeparti stemte for.","Koranloven (B 6, 1. okt. 2026): både Alternativet og Dansk Folkeparti stemte for at afskaffe den.","Hjemrejsestøtten (L 17 B, 3. sept. 2026): både Alternativet og Dansk Folkeparti stemte imod forslaget.","EU's migrationspagt (L 15, 27. aug. 2026): både Alternativet og Dansk Folkeparti stemte imod at gennemføre dele af den, men af helt forskellige grunde."],"disagree":["Udvisning (L 17 A, 3. sept. 2026): Dansk Folkeparti stemte for skærpelsen, Alternativet stemte imod.","Store bededag (B 3, 1. okt. 2026): Dansk Folkeparti stemte for at genindføre den, Alternativet stemte imod.","Højtalerforstærket bøn (B 11, 3. sept. 2026): Dansk Folkeparti stemte for forbuddet, Alternativet stemte imod.","Tobaks- og alderskontrol (L 12 B, 27. aug. 2026): Alternativet stemte for, Dansk Folkeparti stemte imod."],"note":"Alternativet og Dansk Folkeparti stemmer sammen i nogle værdispørgsmål som koranloven, men er modsatte på udvisning, religiøse helligdage og de fleste stramninger over for udlændinge."},"vocabulary":[{"term":"Trivsel","meaning":"Alternativets nøglebegreb: politik skal vurderes ud fra, om den gør danskerne trives, ikke kun ud fra økonomisk effekt."},{"term":"Grøn spændetrøje","meaning":"Et udtryk, Altinget har brugt om Alternativets forsøg på at slippe for at være et rent grønt parti."},{"term":"Blokpolitik","meaning":"Når partier vælger at støtte eller modsætte sig en politik ud fra, hvilken blok de tilhører, og ikke ud fra indhold. Alternativet og Enhedslisten har anklaget regeringen for blokpolitik ved forhandlingsbordet (Altinget, 24. jul. 2025)."},{"term":"Spærregrænsen","meaning":"Den 2 pct.-grænse, et parti skal over for at få mandater i Folketinget. Alternativet har ligget tæt på den."}],"funFacts":["Josephine Fock var politisk leder før Franciska Rosenkilde, som blev valgt i februar 2021 efter Focks afgang i november 2020.","Alternativet fik 91.770 stemmer ved valget i 2026 og 117.567 i 2022. Partiet har ingen mandater i Europa-Parlamentet.","Alternativet har været støtteparti for regeringen, men er ikke i regering, og partiet har ingen ministre."],"sources":[{"title":"Folketinget: Forslag og forespørgsler fra Alternativet (F 4)","url":"https://www.ft.dk/samling/20261/forespoergsel/F4/index.htm"},{"title":"Folketinget: L 17 om udvisning (3. sept. 2026)","url":"https://www.ft.dk/samling/20252/lovforslag/L17/index.htm"},{"title":"Folketinget: B 6 om at afskaffe koranloven","url":"https://www.ft.dk/samling/20252/beslutningsforslag/B6/index.htm"},{"title":"Folketinget: L 36 om nulmoms på bøger","url":"https://www.ft.dk/samling/20261/lovforslag/L36/index.htm"},{"title":"Altinget: Alternativet stiller økonomisk hovedkrav til nye regeringsforhandlinger (12. maj 2026)","url":"https://www.altinget.dk/artikel/efter-afbrudte-forhandlinger-stiller-alternativet-nyt-hovedkrav-om-dansk-oekonomi"},{"title":"Altinget: Franciska Rosenkilde: Pia Olsen Dyhr er klart mere oplagt for os end Mette Frederiksen (6. jan. 2026)","url":"https://www.altinget.dk/christiansborg/artikel/franciska-rosenkilde-pia-olsen-dyhr-er-klart-mere-oplagt-for-os-end-mette-frederiksen"},{"title":"Altinget: Alternativet trækker støtten til Henrik Frandsen som ny folketingsformand (6. okt. 2026)","url":"https://www.altinget.dk/artikel/alternativet-traekker-stoetten-til-henrik-frandsen-foer-aabning"},{"title":"sn.dk: Alternativet vil afsætte 200 millioner kroner til dyrevelfærden","url":"https://www.sn.dk/art6638371/koebenhavn-kommune/politik/alternativet-vil-afsaette-200-millioner-til-dyrevelfaerden"},{"title":"Da.wikipedia: Alternativet","url":"https://da.wikipedia.org/wiki/Alternativet"},{"title":"Lex.dk: Regeringen Mette Frederiksen III (ministerliste)","url":"https://lex.dk/Regeringen_Mette_Frederiksen_III"}],"order":3,"color":"#2B8738","on":"#FFFFFF","blok":"rød","officialName":"Alternativet","nick":"Alternativet"},{"id":"bp","letter":"H","name":"Borgernes Parti","short":"BP","founded":"2024","foundedNote":"Partiet blev stiftet i 2024 af Lars Boje Mathiesen, der i marts 2023 var blevet afsat og ekskluderet som formand for Nye Borgerlige. Navnet Borgernes Parti – Lars Boje Mathiesen blev godkendt 28. august 2024.","leader":{"name":"Lars Boje Mathiesen","title":"Partiformand og eneste folketingsmedlem for partiet","since":"2024","born":"1975","bio":"Født 1975 i Skive og opvokset i Ribe. Folkeskolelærer til 2019 og freelancemusiker fra 2001. Medlem af Liberal Alliance i Aarhus Byråd fra 2013 og forlod partiet i 2016. Valgt til Folketinget for Nye Borgerlige i 2019 og 2022. Formand i februar 2023, afsat og ekskluderet i marts 2023. Stiftede Borgernes Parti i 2024 og meldte sig i december 2025 som statsministerkandidat."},"role":"opposition","roleNote":"Borgernes Parti er uden for regeringen og er ikke støtteparti. Partiet har kun ét folketingsmedlem, Lars Boje Mathiesen. De tre andre partivalgte er i dag løsgængere: Jacob Harris (ekskluderet 28. marts 2026), Emilie Schytte (udmeldt 4. april 2026) og Nadja Natalie Isaksen (udmeldt 3. maj 2026). Partiet har ansat Morten Dehn som politisk ordfører, men han er ikke folketingsmedlem.","ideology":["Liberalisme (økonomisk)","Anti-establishment","Restriktiv udlændingepolitik"],"euGroup":"Ingen mandater i Europa-Parlamentet","website":"https://borgernesparti.dk","oneLiner":"Liberal økonomi, restriktiv udlændingepolitik og magten tilbage til borgerne, stiftet af Lars Boje Mathiesen i 2024.","summary":"Borgernes Parti vil give magten tilbage til borgerne, og det er partiets kerneslogan. Partiet vil have mindre stat og mindre kontrol og bureaukrati, og det vil have en stram udlændingepolitik med 'Danmark skal forblive dansk' som ledetema. Det taler mod det, partiet kalder klimahysteri, og vil have mere atomkraft og en energipolitik, der ikke bygger på vind og sol alene. Partiet er bevidst anti-establishment og vil have en forvaltningsdomstol. Ved valget i 2026 fik partiet 2,1 pct. og fire mandater, men tre af dem er i dag løsgængere, og partiet har kun ét folketingsmedlem tilbage.","pitch":"Vi er for dem, der føler, at systemet ikke lytter til dem. Vi vil have magten tilbage til borgerne, lavere skatter og en stram udlændingepolitik, og vi tør sige det højt. Vi er ikke en del af det gamle establishment, og vi lover kun det, vi kan holde.","critique":"Kritikerne siger, at partiet er et enkeltmandsprojekt, der er afhængigt af Lars Boje Mathiesens person. De peger på, at tre af de fire valgte medlemmer har forladt partiet inden for fem uger efter valget. Mathiesen har den laveste personlige popularitet, som Epinion nogensinde har målt på en dansk topolitiker. Analytikere i Politiken, Berlingske og B.T. kalder kollapset uden fortilfælde. Altinget-debattører peger på, at partier bygget på én karismatisk person hurtigt falder.","keyIssues":[{"title":"Magten tilbage til borgerne","detail":"Partiets kerneslogan. Partiet vil have en forvaltningsdomstol og mindre stat, og det vil have lavere skatter og mindre bureaukrati. Det er partiets generelle linje, uden at alle dele er udmøntet i konkrete forslag."},{"title":"Danmark skal forblive dansk","detail":"Partiets stærkeste tema er udlændinge og integration. Partiet taler om massiv indvandring og fejlslagen integration. Under overskriften 'Befri Danmark fra Islam' har partiet stemt for at afskaffe koranloven (B 6, 1. oktober 2026)."},{"title":"Et opgør med klimahysteriet","detail":"Partiet siger, at Danmark ikke har en klimakrise, men en energikrise. Det vil have billigere energi og mener, at grøn energi fra vind og sol er dyr og ustabil. Partiet har også argumenteret for atomkraft."},{"title":"Frihed og ansvar","detail":"Partiet vil have frie borgere med ansvar for egen lykke. Det har også fremsat idéen om at begrænse folketingsperioderne til ti år (februar 2024)."}],"positions":{"udlaendinge":{"score":5,"text":"Partiet siger, at Danmark skal forblive dansk, og at landet er truet af massiv indvandring og fejlslagen integration. Det stemte 1. oktober 2026 for at afskaffe koranloven. Det har fremsat forslaget B 38 om at fratage en person dansk indfødsret (11. november 2026)."},"oekonomi":{"score":4,"text":"Partiet vil have mindre stat, lavere skatter og mindre kontrol og bureaukrati. Det stemte 12. november 2026 for nulmoms på bøger og afskaffelse af kaffeafgiften (L 36 A og B)."},"arbejdsmarked":{"score":3,"text":"Partiets linje er mindre stat og større ansvar for egen lykke. Der er ingen konkrete arbejdsmarkedsforslag i partiets fremsatte forslag i efteråret 2026."},"velfaerd":{"score":4,"text":"Partiets generelle linje er mindre stat og mere ansvar hos borgerne. Partiets hjemmeside har ingen konkrete velfærdsforslag."},"sundhed":{"score":4,"text":"Partiets hjemmeside har et afsnit om sundhedspolitik, men uden konkrete forslag. Den generelle linje om mindre stat gælder også her."},"klima":{"score":5,"text":"Partiet siger, at Danmark ikke har en klimakrise, men en energikrise. Det afviser, at grøn energi kan sikre forsyningen, og det har argumenteret for atomkraft."},"natur_landbrug":{"score":4,"text":"Natur, miljø og landbrug er nævnt på partiets hjemmeside, men uden konkrete forslag."},"eu":{"score":4,"text":"Partiet har ingen mandater i Europa-Parlamentet. I Folketinget stemte det 27. august 2026 imod EU's migrations- og asylpagt (L 15), sammen med DF, DD og LA."},"forsvar":{"score":3,"text":"Forsvar er nævnt på partiets hjemmeside som område, men uden konkret indhold."},"ret":{"score":5,"text":"Partiet vil have en forvaltningsdomstol. Det stemte for at fratage en person dansk indfødsret med forslaget B 38 (11. november 2026)."},"bolig":{"score":4,"text":"Boligpolitik har ingen konkrete forslag på partiets hjemmeside. Den generelle linje om mindre regulering gælder også her."},"uddannelse":{"score":4,"text":"Uddannelse har ingen konkrete forslag på partiets hjemmeside. Den generelle linje om mindre stat gælder også her."}},"history":[{"year":"2019","event":"Lars Boje Mathiesen vælges til Folketinget for Nye Borgerlige."},{"year":"2023","event":"Mathiesen bliver formand for Nye Borgerlige i februar, men bliver afsat og ekskluderet i marts 2023."},{"year":"2024","event":"I april annoncerer Mathiesen et nyt parti. Navnet Borgernes Parti – Lars Boje Mathiesen godkendes 28. august 2024, og partiet indsamler i december 2024 omkring 20.000 underskrifter."},{"year":"2025","event":"I marts præsenteres Allan Feldt som første kandidat. Han trækker sig i september 2025. I december 2025 meldte Mathiesen sig som statsministerkandidat."},{"year":"2026","event":"Ved folketingsvalget 24. marts 2026 fik partiet 2,1 pct. og fire mandater: Lars Boje Mathiesen, Jacob Harris, Nadja Natalie Isaksen og Emilie Schytte."},{"year":"2026","event":"Den 28. marts 2026 ekskluderes Jacob Harris. Partiet begrunder det med, at han brød den loyalitetserklæring, han havde underskrevet, og gav urigtige oplysninger. Det kom samtidig frem, at en kurator havde indstillet ham og hans hustru til konkurskarantæne. Harris bliver som løsgænger i Folketinget."},{"year":"2026","event":"Den 4. april 2026 melder Emilie Schytte sig ud af partiet. Hun siger, at hun ikke længere kan stå inde for partiets retorik. Hun bliver som løsgænger i Folketinget."},{"year":"2026","event":"Den 3. maj 2026 melder Nadja Natalie Isaksen sig ud af partiet. Hun siger, at partiet ikke er blevet, som hun håbede, at der mangler et ordentligt grundlag for politisk arbejde, og at fokus har flyttet sig fra politik. Hun bliver som løsgænger i Folketinget."},{"year":"2026","event":"Analytikere i Politiken, Berlingske og B.T. kalder kollapset uden fortilfælde. Mathiesen er tilbage som eneste medlem af partiets folketingsgruppe."},{"year":"2026","event":"Den 2. juli 2026 ansætter partiet Morten Dehn som politisk ordfører. Han er ikke folketingsmedlem, og han skal hjælpe Mathiesen med det parlamentariske arbejde."},{"year":"2026","event":"Ved Voxmeter 9. nov. 2026 står partiet til 0,4 pct., ned fra 2,1 pct. ved valget."}],"people":[{"name":"Lars Boje Mathiesen","role":"Partiformand og eneste folketingsmedlem for partiet","note":"Har stiftet partiet og er valgt i Østjylland. Statutterne giver ham en fireårig formandsperiode og vetoret."},{"name":"Morten Dehn","role":"Politisk ordfører, ikke folketingsmedlem","note":"Ansat 2. juli 2026 for at hjælpe formanden med det parlamentariske arbejde."},{"name":"Jacob Harris","role":"Løsgænger i Folketinget, valgt for BP i 2026","note":"Ekskluderet 28. marts 2026. Han fik 2.307 personlige stemmer."},{"name":"Emilie Schytte","role":"Løsgænger i Folketinget, valgt for BP i 2026","note":"Meldte sig ud 4. april 2026 og kritiserede partiets formand. Hun fik 533 personlige stemmer."},{"name":"Nadja Natalie Isaksen","role":"Løsgænger i Folketinget, valgt for BP i 2026","note":"Meldte sig ud 3. maj 2026. Hun fik 1.301 personlige stemmer. Navnet staves også Nadja Natalie Isaksen."},{"name":"Cecilie Liv Hansen","role":"Løsgænger i Folketinget, kom fra Liberal Alliance","note":"Er ikke valgt for Borgernes Parti. Hun blev ekskluderet fra Liberal Alliance og sidder som uafhængig."},{"name":"Preben Bang Henriksen","role":"Løsgænger i Folketinget, tidligere Venstre","note":"Sidder som uafhængig og er ikke valgt for Borgernes Parti."}],"voters":{"summary":"Borgernes Parti er et protestparti, der samler op efter Nye Borgerlige. Vælgerne er typisk misfornøjede med det etablerede politiske system og bor oftere uden for de største byer. Partiet står i Voxmeter 9. nov. 2026 til 0,4 pct., ned fra 2,1 pct. ved valget.","strongholds":"Uden for de største byer, især i Østjylland, hvor Mathiesen blev valgt.","demographics":"Vælgerne er typisk utilfredse med de etablerede partier og har en blandet uddannelsesprofil, som for protestpartier i almindelighed."},"election2026":{"note":"Partiet fik 2,1 pct. og fire mandater ved valget 24. marts 2026 og kom over spærregrænsen efter midnat. Efter valget brød partiet hurtigt sammen: tre af de fire valgte forlod partiet eller blev ekskluderet inden for fem uger. Analytikere kalder det uden fortilfælde, og Altinget peger på, at et parti bygget op omkring én person mangler organisation og en bred bevægelse."},"strengths":["Kom i Folketinget ved valget i 2026","Klar anti-establishment-profil, der appellerer til vælgere, der føler sig overset","Tydelig linje på udlændinge og klima med få, enkle budskaber"],"weaknesses":["Afhængigt af én person, Lars Boje Mathiesen, med ét folketingsmedlem tilbage","Tre af de fire valgte medlemmer er forladt partiet inden for fem uger","Rekordlav personlig popularitet for Mathiesen ifølge Epinion","Statutterne giver formanden fire år og vetoret, hvilket gør det svært at afsætte ham"],"internalTensions":[{"title":"Frafald efter valget","detail":"Jacob Harris blev ekskluderet 28. marts 2026, Emilie Schytte meldte sig ud 4. april og Nadja Natalie Isaksen 3. maj. Partiets folketingsgruppe er dermed reduceret til formanden alene."},{"title":"Formandens løn og vetoret","detail":"I april 2026 var formandens løn og partiets vedtægter omstridte. Vedtægterne giver Mathiesen fire år som formand, en vetoret og mulighed for en millionløn. Harris kritiserede, at Mathiesen først rådede ham til at tage orlov og siden pressede ham til at træde tilbage."},{"title":"Rasmus Munch Søndergaard","detail":"Søndergaard udviklede meget af partiets udlændingepolitik, men faldt senere ud med Mathiesen."}],"typicalArguments":[{"claim":"Magten skal tilbage til borgerne, og det politiske establishment har lyttet for lidt til vælgerne.","counter":"Kritikere siger, at partiet selv er et enkeltmandsprojekt, og at en anti-establishment-linje ikke er et program."},{"claim":"Danmark skal forblive dansk, og udlændingepolitikken skal strammes.","counter":"Modstandere siger, at en stram linje uden konkrete lovforslag er et slogan, og at partiet ikke har vist, hvordan den skal gennemføres."},{"claim":"Klimapolitikken er blevet til hysteri, og Danmark har en energikrise, ikke en klimakrise.","counter":"Kritikere mener, at partiet afviser klimavidenskaben, og at det mangler et troværdigt alternativ til grøn energi."},{"claim":"Mindre stat og lavere skatter giver borgerne mere frihed.","counter":"Modstandere siger, at lavere skatter betyder ringere velfærd, og at partiet ikke har vist, hvordan det finansieres."}],"vsDF":{"agree":["Afskaffelse af koranloven: BP og DF stemte begge for (B 6, 1. oktober 2026). Forslaget blev forkastet.","BP og DF stemte begge imod EU's migrations- og asylpagt (L 15, 27. august 2026), imod gødningsloven (L 5) og imod V 1 (8. oktober 2026)."],"disagree":["Grønlandsk spiralsag (L 11, 27. august 2026): BP stemte for godtgørelse, mens DF stemte imod.","Id-kort på byggepladser (L 19, 3. september 2026): DF stemte for, mens BP stemte imod.","Rykkergebyr ved told- og skatteforvaltningen (L 8, 3. september 2026): DF stemte for, mens BP stemte imod.","Organisation: BP er bygget op om én person med ét folketingsmedlem tilbage. DF er stiftet i 1995 og har en stabil parlamentarisk gruppe. Altinget (19. maj 2026) peger på, at BP's problem er personafhængigheden."],"note":"BP og DF deler en restriktiv udlændingepolitik og en anti-establishment-retorik. Forskellen ligger i organisation og økonomi: BP er et personligt projekt med en liberal økonomi, mens DF er et etableret parti med en historisk velfærdsprofil. BP's klimalinje er tydeligere end DF's i partiets egne udsagn."},"vocabulary":[{"term":"Magten tilbage til borgerne","meaning":"Partiets kerneslogan."},{"term":"Forvaltningsdomstol","meaning":"Et domstolsnet, der prøver forvaltningens afgørelser. Partiet vil have det."},{"term":"Klimahysteri","meaning":"Partiets betegnelse for en klimapolitik, det mener er overdreven."},{"term":"Løsgænger","meaning":"Folketingsmedlem, der ikke længere er medlem af sit oprindelige parti."}],"funFacts":["Partiet fik 4 mandater ved valget i 2026, men var i maj 2026 nede på ét, da tre medlemmer forlod partiet eller blev ekskluderet.","Partiet havde oprindeligt foreslået navnet Danmarks Bedste Parti, men det blev afvist i juni 2024.","Morten Dehn er politisk ordfører uden at være folketingsmedlem, hvilket gør BP til det eneste parti i Folketinget med en politisk ordfører uden for Folketinget."],"sources":[{"title":"Borgernes Parti, forside","url":"https://borgernesparti.dk"},{"title":"Borgernes Parti (lex.dk)","url":"https://lex.dk/Borgernes_Parti"},{"title":"Lars Boje Mathiesen (lex.dk)","url":"https://lex.dk/Lars_Boje_Mathiesen"},{"title":"Borgernes Parti (da.wikipedia)","url":"https://da.wikipedia.org/wiki/Borgernes_Parti"},{"title":"Folketingets forslag fra BP (oda.ft.dk)","url":"https://www.ft.dk/samling/20261/beslutningsforslag/B38/index.htm"},{"title":"Folketingets afstemninger (oda.ft.dk)","url":"https://www.ft.dk/samling/20261/lovforslag/L36/index.htm"},{"title":"Overblik: De har forladt Borgernes Parti (TV 2)","url":"https://nyheder.tv2.dk/live/politik/2026-02-26-folketingsvalg-2026/overblik--de-har-forladt-borgernes-parti?entry=a081d35d-62ef-4db3-ac05-d8972f66ee6d"},{"title":"Nadja Natalie Isaksen forlader Borgernes Parti (TV 2, 3. maj 2026)","url":"https://nyheder.tv2.dk/politik/2026-05-03-nadja-natalie-isaksen-forlader-borgernes-parti"},{"title":"Nyvalgt folketingskandidat smidt ud af Borgernes Parti (DR, 28. mar. 2026)","url":"https://www.dr.dk/nyheder/politik/folketingsvalg/nyvalgt-folketingskandidat-borgernes-parti-smidt-ud-af-partiet"},{"title":"Analytikere: Nedsmeltning i Borgernes Parti er uden fortilfælde (Nordjyske, 4. maj 2026)","url":"https://nordjyske.dk/nyheder/politik/analytikere-nedsmeltning-i-borgenes-parti-er-uden-fortilfaelde/6022176"},{"title":"Borgernes Partis kollaps viser, at indignation ikke er nok (Altinget, 4. maj 2026)","url":"https://www.altinget.dk/artikel/borgernes-partis-kollaps-viser-at-indignation-ikke-er-nok-til-at-bygge-et-politisk-projekt"},{"title":"Historiestuderende: Lars Bojes kollaps er del af en europæisk tendens (Altinget, 19. maj 2026)","url":"https://www.altinget.dk/artikel/historiestuderende-lars-bojes-kollaps-er-del-af-en-europaeisk-tendens"},{"title":"Borgernes Parti ansætter politisk ordfører (Altinget, 2. jul. 2026)","url":"https://www.altinget.dk/christiansborg/artikel/borgernes-parti-ansaetter-politisk-ordfoerer"},{"title":"Lars Boje lover at give den gas i Folketinget (Altinget, 1. apr. 2026)","url":"https://www.altinget.dk/christiansborg/artikel/lars-boje-vil-ryste-de-etablerede-partier-jeg-skylder-ikke-nogen-noget"},{"title":"Lars Boje freder sig selv (TV 2, 8. apr. 2026)","url":"https://nyheder.tv2.dk/politik/2026-04-08-lars-boje-freder-sig-selv-kan-ikke-vaeltes-i-fire-aar"},{"title":"Partifælle forsvarer Lars Bojes løn (TV 2, 11. apr. 2026)","url":"https://nyheder.tv2.dk/politik/2026-04-11-partifaelle-forsvarer-lars-bojes-loen-720000-kroner-er-ingen-penge-i-vore-dage"},{"title":"Vedtægter sikrer Lars Boje fire år som formand (Altinget)","url":"https://www.altinget.dk/christiansborg/artikel/lars-boje-mathiesen-faar-fire-aar-paa-posten-vetoret-og-mulighed-for-millionloen-i-nye-vedtaegter-for-borgernes-parti"},{"title":"Voxmeter-målinger (politpro.eu)","url":"https://politpro.eu/da/danmark/analyseinstitutter/voxmeter"}],"order":12,"color":"#5F6B7A","on":"#FFFFFF","blok":"blå","officialName":"Borgernes Parti","nick":"Borgernes Parti"}],"dfExtra":{"argumentBank":[{"topic":"udlaendinge","question":"Er 'remigration' bare et pænt ord for at sende folk ud af landet, også dem der er her lovligt og har boet her i årevis?","dfPosition":"DF vil have en markant lavere indvandring, især fra ikke-vestlige lande, og en remigrationspolitik, der får flere udlændinge til at vende tilbage. Partiets 22-punkts plan blev præsenteret kort før valget i 2026. Den 19. marts 2026 foreslog DF, at permanent opholdstilladelse kun gives til udlændinge tæt knyttet til en dansk statsborger, og at alle andre får fornyelige tilladelser, der kræver ren straffeattest og selvforsørgelse.","dfBestArgument":"Danske borgere har ret til at bestemme, hvor mange der kommer til landet, og hvem der får lov til at blive. Velfærdsstaten bygger på, at de, der bor her, også bidrager til den. Hvis et samfund ikke kan styre sin indvandring, mister det tilliden, og så rammer det også dem, der har integreret sig godt og skal konkurrere med dem, der ikke har.","bestCounter":"Forslaget om at fjerne permanent ophold for mange lovligt bosatte er retroaktivt, og det er uklart, om dansk ret tillader det. Det rammer også dem, der har fået opholdet efter mange års lovlig ophold, og som er i arbejde og uden kriminalitet. Kritikere mener, at begrebet 'remigration' er lånt fra bevægelsen Generation Identitær. En kronikør i Altinget (9. marts 2026) hævder, at næsten halvdelen af DF's forslag kan genfindes i en liste, bevægelsen sendte til Folketingets medlemmer i 2020.","dfReply":"Vi har ikke en retroaktiv hensigt. Vi vil have en model, der gør det tydeligt, hvem der kan blive. De fleste, der har boet her længe og passer deres arbejde og er uden kriminalitet, har ikke noget at frygte. Vi vil have, at Folketinget tager ansvar for indvandringen, og så kan vi diskutere, hvordan det konkret gøres. Hvad angår ordet, er det et begreb, der bruges i den offentlige debat, og vi lader os ikke bestemme af dem, der vil bruge det som skræmmebillede.","facts":[{"fact":"Den 19. marts 2026 foreslog DF, at permanent opholdstilladelse skal afskaffes for de fleste udlændinge, der ikke er tæt knyttet til en dansk statsborger, og at gældende tilladelser kan trækkes tilbage retroaktivt. DF havde ikke et tal for, hvor mange der ville blive ramt, og det er uklart, om loven tillader det.","source":{"title":"The Local: Danish far-right party wants to strip permanent residency from foreign nationals (19. marts 2026)","url":"https://www.thelocal.dk/20260319/danish-far-right-party-wants-to-strip-permanent-residency-from-foreign-nationals"}},{"fact":"DF præsenterede en 22-punkts plan for remigration kort før valgudskrivelsen i 2026. Kronikøren Mathias Hee Pedersen hævder, at næsten halvdelen af planens punkter kan genfindes i en liste med 30 forslag, som bevægelsen Generation Identitær sendte til alle folketingsmedlemmer i 2020.","source":{"title":"Altinget: Når DF taler om remigration, henter de ordene fra en højreradikal bevægelse (9. marts 2026)","url":"https://www.altinget.dk/etik/artikel/naar-dansk-folkeparti-taler-om-remigration-henter-de-ordene-fra-kontroversiel-hoejreradikal-bevaegelse"}}],"pitfall":"Det er forkert at sige, at DF vil 'smide alle indvandrere ud', og det er lige så forkert at sige, at DF kun vil have kriminelle ud. DF's konkrete forslag i marts 2026 rammer særligt permanente opholdstilladelser og statsborgerskab. Forslaget er et forslag, ikke en lov."},{"topic":"ret","question":"Hvad siger tallene om udlændinge og kriminalitet, og hvorfor skal DF så stramme så meget?","dfPosition":"DF mener, at udlændinge med kriminelle domme skal udvises, og at der skal være ren straffeattest for at blive i landet. Mikkel Bjørn og Anders Vistisen har i november 2026 fremsat forslag om at frakende indfødsret for kriminalitet (B 17).","dfBestArgument":"Staten har en pligt til at beskytte borgerne, og en udvisning af dem, der bryder loven, er både retfærdig og logisk. Tilliden til retssystemet falder, hvis man ikke tager udvisning alvorligt.","bestCounter":"Forskelle i kriminalitet forklares i høj grad af alder, køn, social baggrund og bopæl, og når man tager højde for det, bliver forskellen mindre. Forslag, der rammer alle med udenlandsk statsborgerskab, rammer desuden dem, der aldrig har begået kriminalitet. Justitsministeriets rapport 'Kriminalitet og herkomst 2023' er et officielt grundlag for debatten.","dfReply":"Vi siger ikke, at alle udlændinge er kriminelle. Vi siger, at de, der er dømt, skal ud, og at det ikke må være svært at få det gennemført. Tallene viser, at der er et problem, og vi kan ikke løse det ved at lade være med at kigge på dem. Hvis kriminaliteten er højere, skal vi gøre noget ved det, uanset om forklaringen er alder, køn eller bopæl.","facts":[{"fact":"Justitsministeriet har udgivet rapporten 'Kriminalitet og herkomst 2023', som ser på kriminalitet fordelt på herkomst og er en af de officielle kilder til debatten.","source":{"title":"Justitsministeriet: Kriminalitet og herkomst 2023 (pdf)","url":"https://www.justitsministeriet.dk/wp-content/uploads/2025/05/Kriminalitet-og-herkomst-2023-WT.pdf"}},{"fact":"B 17 fra DF, 'frakendelse af indfødsret på grund af kriminalitet', blev registreret 13. november 2026 og er fremsat af 16 DF-medlemmer, herunder Mikkel Bjørn og Anders Vistisen.","source":{"title":"Folketingets sagsdata: B 17 (oda.ft.dk)","url":"https://oda.ft.dk/api/Sag(106183)"}}],"pitfall":"Den ene side siger, at 'udlændinge begår mest kriminalitet', og den anden siger, at 'der er ingen forskel'. Begge dele er for skarpe. Forskellen i de officielle tal er reel, men den skal forklares med alder, køn og social baggrund. Tjek altid, om der er tale om dømte, sigtede eller anmeldte, og hvilken periode tallet dækker."},{"topic":"udlaendinge","question":"DF siger, at de ikke er imod folk, der er integreret. Men hvad med velintegrerede danskere med udenlandsk baggrund, som føler sig forkert set? Er DF imod dem?","dfPosition":"DF hævder, at partiet ikke er imod enkeltpersoner, men imod at Danmark bliver for forskelligt, og at integrationen mislykkes. Partiet taler om kriminelle og ikke-integrerede. DF's forslag fra marts 2026 om permanent ophold og statsborgerskab rammer ifølge partiet systemet, ikke enkeltpersoner.","dfBestArgument":"Der findes mange velintegrerede danskere med udenlandsk baggrund, og de bidrager til samfundet. Men en lov skal laves til alle, og når man kun kigger på den enkelte, mister man overblikket. Hvis vi ikke styrer indvandringen, bliver integrationen sværere for alle, også for dem, der allerede har gjort det godt.","bestCounter":"Forslagene rammer velintegrerede, fordi de er bygget op om opholdstid, statsborgerskab og ydelser, ikke om integration i praksis. Den nuværende ordning kræver allerede 4 til 8 års lovligt ophold til permanent ophold, og borgere med en fængselsstraf over seks måneder kan ikke få statsborgerskab. Hvis DF vil stramme yderligere, rammer det også dem, der har været i arbejde i årevis.","dfReply":"Vi er ikke imod dem. Vi er imod, at man kan blive dansk og have ret til at blive her, uden at have vist, at man vil være her. Hvis man har et job, er ren i straffeattesten og bidrager, så har man ikke noget at frygte. De, der har det hårdt, er dem, der ikke passer ind, og det er dem, vi vil have fokus på.","facts":[{"fact":"Den nuværende regel er permanent ophold efter 4 til 8 års lovligt ophold alt efter forhold. Statsborgerskab nægtes til personer med en fængselsstraf over seks måneder, og ansøgere skal have arbejdet fuld tid i mindst 3,5 af de seneste 4 år.","source":{"title":"The Local: Danish far-right party wants to strip permanent residency from foreign nationals (19. marts 2026)","url":"https://www.thelocal.dk/20260319/danish-far-right-party-wants-to-strip-permanent-residency-from-foreign-nationals"}},{"fact":"Knap 4.800 syrere har fået permanent opholdstilladelse siden 2015, og 1.845 syrere fik statsborgerskab mellem 2014 og 2025 (Ritzau-tal, gengivet af The Local). DF's forslag vil ramme netop denne gruppe, og Anders Vistisen sagde, at den store gruppe af syrere i landet vil blive sendt hjem.","source":{"title":"The Local: Danish far-right party wants to strip permanent residency from foreign nationals (19. marts 2026)","url":"https://www.thelocal.dk/20260319/danish-far-right-party-wants-to-strip-permanent-residency-from-foreign-nationals"}}],"pitfall":"Det er forkert at sige, at DF's forslag kun rammer 'ikke-integrerede'. Forslagene handler om formelle kriterier som opholdstid, statsborgerskab og ydelser, og de rammer også velintegrerede, der ikke har dansk familie. Det er også forkert at sige, at DF slet ikke skelner: DF taler om kriminelle og 'ikke-integrerede' og skriver ren straffeattest som krav. Spørgsmålet er, om kriterierne er præcise nok til at skelne."},{"topic":"andet","question":"Hvad er DF's holdning til islam og muslimer, og er det ikke bare islamofobi?","dfPosition":"DF fokuserer på indvandring og ikke på religion som sådan, men i marts 2026 stillede Messerschmidt krav om, at DF kun skulle indgå i en regering, hvis flere muslimer forlod Danmark, end der kom.","dfBestArgument":"DF siger, at det ikke er religionen, men integrationen og indvandringen, der er problemet. Et samfund har ret til at sætte krav til dem, der bliver borgere, og kravet om netto-udvandring er et forsøg på at få kontrol med indvandringen, der også er en demokratisk prioritet.","bestCounter":"Venstres leder Troels Lund Poulsen afviste kravet med, at religion ikke skal styre dansk indvandringspolitik. Kritikere mener, at et krav om netto-udvandring af muslimer i praksis rammer en bestemt religion, og at det er svært at adskille fra religiøs diskrimination.","dfReply":"Vi taler om indvandring og ikke om tro. Vi er ikke imod, at folk praktiserer deres religion. Vi siger, at vi vil have færre indvandrere fra lande, hvor integrationen ikke er lykkedes godt nok. Det er en politisk vurdering, ikke en religiøs.","facts":[{"fact":"Messerschmidt krævede i marts 2026, at DF kun skulle indgå i en regering, hvis den kunne sikre, at flere muslimske indvandrere forlod Danmark, end der kom. Venstres leder Troels Lund Poulsen afviste kravet.","source":{"title":"The Local: Danish far-right party wants to strip permanent residency from foreign nationals (19. marts 2026)","url":"https://www.thelocal.dk/20260319/danish-far-right-party-wants-to-strip-permanent-residency-from-foreign-nationals"}},{"fact":"Kronikøren Mathias Hee Pedersen skriver, at Messerschmidts ultimatum blev fremsat den 1. marts 2026.","source":{"title":"Altinget: Når DF taler om remigration, henter de ordene fra en højreradikal bevægelse (9. marts 2026)","url":"https://www.altinget.dk/etik/artikel/naar-dansk-folkeparti-taler-om-remigration-henter-de-ordene-fra-kontroversiel-hoejreradikal-bevaegelse"}}],"pitfall":"Det er forkert at sige, at DF vil forbyde 'islam' eller 'muslimer' i Danmark. DF's konkrete forslag handler om indvandring og opholdstid. Omvendt er det forkert at sige, at DF slet ikke har en religiøs dimension, når det drejer sig om kravet om netto-udvandring af muslimer fra marts 2026."},{"topic":"eu","question":"Hvordan kan et parti, der vil have Danmark ud af det dybere EU-samarbejde, have en ret til at tale om Danmarks interesser?","dfPosition":"DF er EU-skeptisk og vil ikke have, at Danmark giver mere suverænitet til EU. Partiet er imod euroen, vil beholde kronen og er imod EU-medlemskab for Tyrkiet. DF mener, at de vigtige beslutninger skal tages i Folketinget og ikke i Bruxelles.","dfBestArgument":"Danske vælgere har ret til at afgøre, hvem der laver lovene i Danmark. EU's indflydelse vokser, og det er en demokratisk udfordring, når beslutninger træffes længere væk fra borgerne. Kronen har givet Danmark stabilitet, og en folkeafstemning i 2000 viste, at danskerne ikke ønskede euroen.","bestCounter":"Danmark har en undtagelse fra euroen, og de fleste danske beslutninger om EU-regler er fortsat taget i Folketinget. Erhvervslivet og eksporten er tæt knyttet til det indre marked, og en større distance kan koste jobs. Kritikere siger, at DF's EU-kritik er en parolesag, der ikke svarer på, hvad alternativet til EU er.","dfReply":"Vi vil ikke melde os ud af EU, men vi vil have, at Folketinget bestemmer mere. Det indre marked kan man godt have uden at give afkald på sin egen lovgivning. Og hvis erhvervslivet skal være med, skal de ikke være bange for, at vi tager vores beslutninger selv.","facts":[{"fact":"DF fik 6,37 % og 1 mandat ved Europa-Parlamentsvalget i 2024 og er i gruppen Patriots for Europe. Partiet er imod euroen, vil beholde kronen og er imod Tyrkiets EU-medlemskab.","source":{"title":"Wikipedia (en): Danish People's Party","url":"https://en.wikipedia.org/wiki/Danish_People%27s_Party"}}],"pitfall":"Det er forkert at sige, at DF vil melde Danmark ud af EU. Partiet vil have Danmark ud af de dybere dele af samarbejdet, ikke ud af EU. Og det er forkert at sige, at Danmark ingen indflydelse har i EU, fordi Danmark selv er med i beslutningsprocessen."},{"topic":"velfaerd","question":"DF siger, at de vil passe på de ældre. Men hvordan betaler man det, når skatteprocenten skal sænkes?","dfPosition":"DF vil have mere penge til ældre og sundhed og kalder sig velfærdsstatens forsvarer. 'Ældre' er en af fire mærkesager på partiets hjemmeside, med målet 'En værdig behandling af vores ældre'. DF vil udelukke udlændinge fra visse ydelser for at beskytte velfærden for danskere.","dfBestArgument":"Det er de ældre, der har bygget Danmark, og de skal have en værdig alderdom. Hvis man lægger en stor del af udgifterne over på skatteyderne uden at sikre dem, der virkelig har brug for det, svigter man dem. Velfærden skal være til danskerne, og den må ikke blive en ydelse, der står åben for alle uanset tilknytning.","bestCounter":"Det er ikke kun et spørgsmål om vilje, men om finansiering: skatter og afgifter, der sænkes, samtidig med at udgifterne vokser, skal dækkes et andet sted. Kritikere mener, at DF's regnestykker mangler, især på finansieringssiden. Forslaget om at udelukke udlændinge fra visse ydelser rammer også ældre udlændinge, der har betalt skat.","dfReply":"Vi har prioriteret ældre over skattelettelser i vores politik, og vi vil bruge det offentlige til at sikre de ældre. Hvis der skal findes penge, skal det være ved at stramme på dem, der ikke har tilknytning, og ved at fjerne unødvendige udgifter. Vi siger også, at vi vil have ansvar for finansieringen, og vi er klar til at diskutere det.","facts":[{"fact":"DF's hjemmeside nævner 'En værdig behandling af vores ældre' som en af partiets fire mærkesager.","source":{"title":"Dansk Folkeparti: forside","url":"https://danskfolkeparti.dk/"}},{"fact":"DF har støttet øgede udgifter til pensioner og sundhed, og partiet beskriver sig som forsvarer af velfærdsstaten, som det mener skal beskyttes ved at udelukke indvandrere fra den.","source":{"title":"Wikipedia (en): Danish People's Party","url":"https://en.wikipedia.org/wiki/Danish_People%27s_Party"}}],"pitfall":"Det er forkert at sige, at DF ikke har nogen plan for finansieringen. Partiets økonomiske forslag findes, men de skal læses kritisk. Og det er forkert at sige, at velfærdsudgifter til ældre automatisk bliver billigere, hvis man stopper udlændinge. Ældreudgifter er høje for alle og stiger med alderen."},{"topic":"arbejdsmarked","question":"Hvorfor er DF imod at hæve pensionsalderen, når vi lever længere og har færre i arbejde?","dfPosition":"DF vil have en lavere pensionsalder for dem med nedslidte job og er imod at hæve pensionsalderen. I oktober 2026 var DF en af tre partier, der meldte ud, at de vil blokere regeringens skærpede krav til seniorpension.","dfBestArgument":"Det er ikke rimeligt, at en murer eller en plejemedarbejder skal arbejde til 70, fordi nogle andre har kontorjob. Der er mange, der slides ned, og de har ret til at gå tidligere på pension. Det er en retfærdighedsdebat, ikke bare et regnestykke.","bestCounter":"Når folk lever længere, er det rimeligt, at pensionsalderen følger med, ellers bliver velfærdsstaten dyrere. Hvis man sænker pensionsalderen generelt, rammer det arbejdsudbuddet, og det skal de unge og de ældre betale for. Regeringen anslår, at de skærpede krav til seniorpension sparer omkring 800 mio. kr. om året.","dfReply":"Vi siger ikke, at pensionsalderen skal være 60 for alle. Vi siger, at der skal være en ordning for dem, der har slidt sig op. Vi vil ikke have, at de, der har lavet hårdt fysisk arbejde, skal konkurrere om pensionen på lige fod med dem, der sidder ved et skrivebord. Det kan godt være dyrere, men det er retfærdigt.","facts":[{"fact":"I oktober 2024 truede Messerschmidt med at stemme imod en højere pensionsalder og med at trække DF ud af velfærdsforliget. Da DF blev spurgt, om partiet ville støtte en pensionsalder på 70, svarede Peter Kofod, at det 'ikke er et spørgsmål, vi har diskuteret i denne valgperiode'.","source":{"title":"Altinget: Messerschmidt truede med at nedlægge veto (30. oktober 2024)","url":"https://www.altinget.dk/arbejdsmarked/artikel/messerschmidt-truede-med-at-nedlaegge-veto-nu-kan-df-ikke-svare-paa-om-partiet-vil-forhoeje-danskernes-pension"}},{"fact":"Venstre, Liberal Alliance og DF har udtalt, at de vil blokere regeringens forslag om skærpede krav til seniorpension. Regeringen anslår en besparelse på omkring 800 mio. kr. om året.","source":{"title":"Arbejderen: Finanslovsforslaget for 2027 (16. oktober 2026)","url":"https://www.arbejderen.dk/indland/finanslovsforslaget-for-2027-indeholder-baade-store-investeringer-og-haarde-nedskaeringer/"}}],"pitfall":"Det er forkert at sige, at DF vil have alle på pension ved 60. Partiet taler om nedslidte og om at gå tidligere på pension i særlige tilfælde. Og det er forkert at sige, at DF ikke har en pensionspolitik. Den er kontroversiel, og partiet har ikke entydigt svaret på, om pensionsalderen skal hæves."},{"topic":"klima","question":"Hvordan kan DF kalde sig et ansvarligt parti, når de vil sænke afgifterne på benzin og diesel?","dfPosition":"DF vil have billigere brændstof og har gjort det til sin vigtigste økonomiske sag i 2026. Partiet lancerede i maj 2026 et borgerforslag om at sænke afgifter og moms til EU's minimumsniveau. Partiet mener, at almindelige familier ikke skal betale for en klimapolitik, de ikke har været med til at bestemme.","dfBestArgument":"Mange danskere bruger bil hver dag, og de har ikke råd til højere brændstofpriser. Når priserne stiger, rammer det dem, der bor langt fra arbejdet, og det er ikke rimeligt. Afgifter skal være til at forstå, og de skal ikke være en skjult skat på dem, der har mindst.","bestCounter":"Brændstofafgifter er et af de få værktøjer til at styre CO2-udledning, og en midlertidig sænkning gør det dyrere at nå klimamålene. Sænkningen er finansieret ved en senere indfasning af selskabsskatten og mellemskatten, og den gælder i et år. Kritikere siger, at afgiftssænkningen er en måde at vinde støtte på, ikke en varig løsning.","dfReply":"Vi har en klimapolitik, der ikke rammer almindelige mennesker først. Vi vil ikke have, at danskerne skal betale mere for at køre på deres eget arbejde, før der findes alternativer. Og vi har lovet, at afgiftssænkningen er midlertidig, og det er den.","facts":[{"fact":"Regeringen og DF har indgået en aftale om at sænke afgiften på benzin og diesel med omkring 2 kroner pr. liter fra 2027. Sænkningen gælder et år og finansieres ved en senere indfasning af selskabsskatten og mellemskatten.","source":{"title":"nyheder.dk: Afgift på benzin og diesel sænkes med to kroner i ny skatteaftale (12. november 2026)","url":"https://www.nyheder.dk/nyheder/saenker-afgifter-pa-benzin-og-diesel/2539451"}},{"fact":"DF lancerede i maj 2026 et borgerforslag om at sænke afgiften på benzin og diesel og momsen til EU's minimumsniveau. Partiets egen side nævner den største prissænkelse i Danmarks historie den 13. november 2026.","source":{"title":"Dansk Folkeparti: forside","url":"https://danskfolkeparti.dk/"}}],"pitfall":"Det er forkert at sige, at DF vil afskaffe brændstofafgiften helt. Forslaget er at sænke den til EU's minimum, og aftalen med regeringen sænker afgiften med omkring 2 kroner pr. liter i et år. Og det er forkert at sige, at afgiftssænkningen ikke har nogen effekt på klimaet. Det er en afvejning, og begge sider kan vise tal, der støtter deres synspunkt."},{"topic":"forsvar","question":"Hvorfor vil DF ikke støtte Ukraine fuldt ud, når Rusland har invaderet et europæisk land?","dfPosition":"DF siger, at støtten til Ukraine har en udløbsdato, og er imod, at Ukraine bliver medlem af NATO, så længe krigen står på. Messerschmidt gik i 2025 ind for at skalere ned den danske militære støtte. Alex Ahrendtsen er partiets forsvarsordfører.","dfBestArgument":"Danmark kan ikke give alt til alle. Vi skal først sikre vores eget forsvar og vores velfærd, og vi skal have en tydelig strategi, der tager hensyn til vores budget. Det er en ansvarlig holdning, og mange danskere deler bekymringen for statens udgifter.","bestCounter":"Ukraine kæmper for sin egen sikkerhed og for Europas sikkerhed, og en lukning af støtten kan gøre det lettere for Rusland at vinde. Det er også billigere at støtte Ukraine nu end at skulle forsvare Europa senere. Kritikere mener, at DF's linje er populistisk og underminerer dansk sikkerhedspolitik.","dfReply":"Vi er ikke imod Ukraine, men vi er imod et ubegrænset blankocheck. Vi vil have en klar plan, en slutdato og en diskussion om, hvad der er en rimelig andel af vores budget. Og vi vil have en plan for vores eget forsvar, så vi ikke står uden.","facts":[{"fact":"DF har sagt, at støtten til Ukraine har en udløbsdato, og partiet er imod Ukraines NATO-medlemskab, så længe krigen står på. I 2025 gik Messerschmidt ind for at skalere ned den danske militære støtte.","source":{"title":"Wikipedia (en): Danish People's Party","url":"https://en.wikipedia.org/wiki/Danish_People%27s_Party"}}],"pitfall":"Det er forkert at sige, at DF er imod at støtte Ukraine helt. Partiets linje er, at støtten skal begrænses og have en udløbsdato. Og det er forkert at sige, at DF er for Rusland. Det er en politisk afvejning, ikke en støtte til angriberen."},{"topic":"bolig","question":"DF vil passe på lejerne, men har de faktisk sagt noget om boligpriser og almene boliger?","dfPosition":"DF's dokumenterede boligudspil er fra 2018 og 2019. I 2018 afviste partiet, at almindelige lejere i almene boliger skulle betale for regeringens 'ghettoudspil'. I 2019 foreslog partiet at fordoble puljen til renovering af almene boliger fra 10 til 20 mia. kr. Christian Kirk er partiets boligordfører.","dfBestArgument":"Almene boliger skal være til dem, der har brug for dem, og lejerne har allerede betalt til deres egen renovering. Det er urimeligt at lade lejerne betale for en politik, der handler om at ændre bolig- og bebyggelsesmønstre, og de ældre og de svageste bør beskyttes mod at blive presset ud.","bestCounter":"Renovering af almene boliger er dyrt, og en fordobling af puljen kræver penge, der enten skal findes andre steder eller lånes. Kritikere mener, at 'ghettoudspillet' i praksis skulle finansieres via Landsbyggefonden, hvor lejerne betaler gennem deres indbetalinger.","dfReply":"Vi har sagt, at lejerne ikke skal betale for regeringens ghettopolitik, og vi vil have, at renoveringen af de almene boliger bliver prioriteret. Det er ikke kun et spørgsmål om penge, men om at sikre, at de boliger, der findes, også er gode og sikre at bo i.","facts":[{"fact":"I 2019 foreslog DF at fordoble puljen til renovering af almene boliger fra 10 til 20 mia. kr., finansieret via Landsbyggefonden, hvor det årlige beløb skal hæves fra 2,5 mia. kr. til 5 mia. kr. over fire år.","source":{"title":"Tekniq: DF vil fordoble pulje til renovering (11. oktober 2019)","url":"https://www.tekniq.dk/nyheder/df-vil-fordoble-pulje-til-renovering/"}},{"fact":"I april 2018 skrev DF's erhvervspolitiske ordfører Hans Kristian Skibby, at DF ikke vil støtte regeringens finansiering af 'ghettoudspillet', som tager 12 mia. kr. fra Landsbyggefonden, og at DF ikke vil have, at almindelige lejere betaler regningen.","source":{"title":"Altinget: DF: Ghetto-regning skal ikke bare sendes videre til lejerne (17. april 2018)","url":"https://www.altinget.dk/artikel/df-ghetto-regning-skal-ikke-bare-sendes-videre-til-lejerne"}}],"pitfall":"Det er forkert at sige, at DF ikke har sagt noget om boliger, fordi partiet har lagt sin 2026-vægt på brændstof. Og det er forkert at sige, at DF vil have boligpriserne helt frit. De konkrete udspil er fra 2018 og 2019, og de er ikke opdateret til 2026."},{"topic":"andet","question":"Messerschmidt er jo dømt for EU-svindel, ikke? Hvordan kan man stole på ham?","dfPosition":"Messerschmidt har været genstand for sager om EU-midler, og han er blevet frifundet i Meld/Feld-sagen.","dfBestArgument":"En person er uskyldig, indtil det modsatte er bevist, og Messerschmidt er blevet frifundet i den sag, der afgjorde hans ansvar i Meld/Feld-sagen. Politiske modstandere bruger ofte gamle sager som våben, og det er ikke rimeligt at bedømme ham på det.","bestCounter":"Sagen om EU-midler har været politisk omstridt, og det er en alvorlig sag for en partiformand, også selv om han blev frifundet i Meld/Feld-sagen.","dfReply":"Der er en frifindelse i Meld/Feld-sagen, og anklagemyndigheden valgte ikke at anke den. Det er den konklusion, vi står ved. Vi vil ikke lade gamle sager bestemme vores politik.","facts":[{"fact":"Altinget skrev den 3. januar 2023, at Messerschmidt blev frifundet i Meld/Feld-sagen i byretten, og at anklagemyndigheden efter 14 dages betænkningstid besluttede ikke at anke frifindelsen.","source":{"title":"Altinget: Messerschmidt-sagen er slut: Anklagemyndigheden anker ikke dommen (3. januar 2023)","url":"https://www.altinget.dk/eu/artikel/messerschmidt-sagen-er-slut-anklagemyndigheden-anker-ikke-dommen"}}],"pitfall":"Det er forkert at sige, at Messerschmidt er 'dømt for EU-svindel' uden at nævne, at han blev frifundet i Meld/Feld-sagen, og at anklagemyndigheden ikke ankede. Tjek domstolenes afgørelser, før du bruger det i en video."},{"topic":"uddannelse","question":"Skal børn i folkeskolen have karakterer fra 4. klasse, og hvad vil DF med skolerne?","dfPosition":"DF vil give skolerne mulighed for at give karakterer fra 4. klasse, hvor skolerne selv beslutter, hvornår eleverne får karakterer. DF har i 2026 fremsat B 42, der vil opdatere skolernes sikkerhedsberedskab og udarbejde undervisningsforløb om Muhammedkrisen.","dfBestArgument":"Karakterer fra 4. klasse giver forældrene og eleverne et klart billede af, hvor de står, og skolerne kan selv vurdere, hvornår det giver mening. Det er et valg for den enkelte skole, og det er ikke en nationalt pålagt ordning.","bestCounter":"Kritikere siger, at karakterer i en tidlig alder skaber mere præstationspres, og at det især rammer børn, der har brug for tid. Det er uklart, om forslaget vil bidrage til bedre læring.","dfReply":"Det er et valg for skolen, og vi vil evaluere ordningen, før den eventuelt bliver landsdækkende. Vi vil have, at skolerne har mulighed for at gøre det, hvis de mener, det er rigtigt for deres elever.","facts":[{"fact":"DF foreslog i februar 2024, at skolerne må give karakterer fra 4. klasse. I dag må skolerne ikke give karakterer før 8. klasse. Ordningen skulle evalueres efter nogle år, før den eventuelt blev landsdækkende. Alex Ahrendtsen var DF's undervisningsordfører.","source":{"title":"Altinget: DF vil give karakterer fra 4. klasse (9. februar 2024)","url":"https://www.altinget.dk/artikel/df-vil-give-karakterer-fra-4-klasse"}},{"fact":"B 42, 'skolesikkerhedsberedskabsplanerne og undervisningsforløb om Muhammedkrisen', blev registreret 12. november 2026, og Josephine Alstrup Kofod er en af forslagsstillerne.","source":{"title":"Folketingets sagsdata: B 42 (oda.ft.dk)","url":"https://oda.ft.dk/api/Sag(106411)"}}],"pitfall":"Det er forkert at sige, at karakterer fra 4. klasse er et krav fra DF til alle skoler. Forslaget er, at skolerne selv kan vælge at give karakterer, og at ordningen først skal evalueres. Det er også forkert at sige, at tidlige karakterer automatisk giver mere pres. Det er en af de centrale uenigheder i debatten."}],"joinDF":{"membership":"Medlemskab af Dansk Folkeparti koster 300 kr. om året. Tilmelding sker på partiets medlemsside, hvor man opretter en konto med sine personlige oplysninger og betaler kontingentet. Medlemmer får adgang til partiets arrangementer, en stemme i partiets politik og valg af kandidater, medlemsbladet Dansk Folkeblad og nyheder fra Christiansborg. Medlemmers aldersgrænse og krav om dansk statsborgerskab står i partiets vedtægter.","dfu":"Dansk Folkepartis Ungdom er partiets ungdomsorganisation. Aldersgrænse, kontingent og den nuværende landsformand fremgår af DFU's egne vedtægter og på dfu.dk.","localOrg":"Dansk Folkeparti er centralt styret, og kritikere peger på, at magten er koncentreret i toppen. Medlemmer har ifølge partiets egen side en stemme i valget af kandidater, og partiets forsvarere siger, at den centrale linje giver en ensartet politik og større gennemslagskraft. Altinget beskrev i 2022 ledelseskampen som et opgør om kurs og personer, ikke om lokal opbakning.","youngProfiles":[{"name":"Chris Bjerknæs","note":"Blev i februar 2017 valgt til landsformand for Dansk Folkepartis Ungdom på DFU's årsmøde."},{"name":"Mads Korsholm","note":"Er kampagnechef for Dansk Folkeparti, ifølge Altinget i december 2024. Han har tidligere været kampagnechef i Liberal Alliance og står bag partiets humoristiske og provokerende sociale medier."}],"sources":[{"title":"Dansk Folkeparti: bliv medlem","url":"https://danskfolkeparti.dk/bliv-medlem"},{"title":"Altinget: DFU's nye formand (13. februar 2017)","url":"https://www.altinget.dk/artikel/dansk-folkepartis-ungdom-har-faaet-ny-formand"},{"title":"Altinget: Han gjorde Vanopslagh til TikTok-konge og blev fyret. Nu vil Mads Korsholm gøre Messerschmidt populær (3. december 2024)","url":"https://www.altinget.dk/christiansborg/artikel/han-gjorde-vanopslagh-til-kongen-af-tiktok-og-blev-fyret-nu-vil-mads-korsholm-skabe-en-fest-i-df-og-goere-messerschmidt-populaer"},{"title":"Altinget: Peter Kofod bliver gruppeformand i DF (8. november 2022)","url":"https://www.altinget.dk/artikel/peter-kofod-bliver-gruppeformand-i-df"}]},"dfOnSocialMedia":"Altinget skrev i december 2024, at DF har en strategi, der bruger vrede, forargelse og humor på de sociale medier for at få nye vælgere. Mads Korsholm, DF's kampagnechef, siger: 'Man er nødt til at gøre noget vildt, hvis man vil ud med sine budskaber.' Artiklen nævner ikke TikTok, Facebook, Instagram eller YouTube som separate kanaler i det synlige uddrag og har ikke tal for følgere eller rækkevidde. Partiets resultater på de sociale medier kan derfor ikke måles ud fra de kilder, der ligger til grund for denne fil.","sources":[{"title":"Dansk Folkeparti: forside","url":"https://danskfolkeparti.dk/"},{"title":"Dansk Folkeparti: politik og ordførere","url":"https://danskfolkeparti.dk/politik"},{"title":"Altinget: Peter Kofod erstatter Morten Messerschmidt som politisk ordfører i DF (14. april 2026)","url":"https://www.altinget.dk/christiansborg/artikel/peter-kofod-erstatter-morten-messerschmidt-som-politisk-ordfoerer-i-df"},{"title":"Altinget: Messerschmidt truede med at nedlægge veto (30. oktober 2024)","url":"https://www.altinget.dk/arbejdsmarked/artikel/messerschmidt-truede-med-at-nedlaegge-veto-nu-kan-df-ikke-svare-paa-om-partiet-vil-forhoeje-danskernes-pension"},{"title":"Altinget: Når DF taler om remigration (9. marts 2026)","url":"https://www.altinget.dk/etik/artikel/naar-dansk-folkeparti-taler-om-remigration-henter-de-ordene-fra-kontroversiel-hoejreradikal-bevaegelse"},{"title":"The Local: Danish far-right party wants to strip permanent residency (19. marts 2026)","url":"https://www.thelocal.dk/20260319/danish-far-right-party-wants-to-strip-permanent-residency-from-foreign-nationals"},{"title":"Justitsministeriet: Kriminalitet og herkomst 2023","url":"https://www.justitsministeriet.dk/wp-content/uploads/2025/05/Kriminalitet-og-herkomst-2023-WT.pdf"},{"title":"nyheder.dk: Afgift på benzin og diesel sænkes med to kroner (12. november 2026)","url":"https://www.nyheder.dk/nyheder/saenker-afgifter-pa-benzin-og-diesel/2539451"},{"title":"Arbejderen: Finanslovsforslaget for 2027 (16. oktober 2026)","url":"https://www.arbejderen.dk/indland/finanslovsforslaget-for-2027-indeholder-baade-store-investeringer-og-haarde-nedskaeringer/"},{"title":"Altinget: Messerschmidt-sagen er slut (3. januar 2023)","url":"https://www.altinget.dk/eu/artikel/messerschmidt-sagen-er-slut-anklagemyndigheden-anker-ikke-dommen"},{"title":"Altinget: DF vil give karakterer fra 4. klasse (9. februar 2024)","url":"https://www.altinget.dk/artikel/df-vil-give-karakterer-fra-4-klasse"},{"title":"Tekniq: DF vil fordoble pulje til renovering (11. oktober 2019)","url":"https://www.tekniq.dk/nyheder/df-vil-fordoble-pulje-til-renovering/"},{"title":"Altinget: DF: Ghetto-regning skal ikke bare sendes videre til lejerne (17. april 2018)","url":"https://www.altinget.dk/artikel/df-ghetto-regning-skal-ikke-bare-sendes-videre-til-lejerne"},{"title":"Wikipedia (en): Danish People's Party","url":"https://en.wikipedia.org/wiki/Danish_People%27s_Party"},{"title":"Folketingets sagsdata (oda.ft.dk): B 17","url":"https://oda.ft.dk/api/Sag(106183)"},{"title":"Folketingets sagsdata (oda.ft.dk): B 42","url":"https://oda.ft.dk/api/Sag(106411)"}]},"career":{"pay":[{"role":"Folketingsmedlem","amount":"ca. 1.100.000 kr./år (grundvederlag, niveau 31. marts 2026)","details":"Reguleres én gang årligt pr. 1. april. Reformen fra 2025 fjerner retten til tjenestemandspension for kommende folketingsmedlemmer og ministre og begrænser eftervederlaget for dem, der ikke bliver genvalgt.","source":{"title":"Lov nr. 1756 af 29. december 2025 om Folketingets medlemmers vederlag (retsinformation)","url":"https://www.retsinformation.dk/eli/lta/2025/1756/pdf"}},{"role":"Minister","amount":"ca. 2.053.000 kr./år (grundvederlag, niveau 31. marts 2026)","details":"Fastsat i lov nr. 1757 af 29. december 2025. Reguleres pr. 1. april.","source":{"title":"Lov nr. 1757 af 29. december 2025 om ministres vederlag (retsinformation)","url":"https://www.retsinformation.dk/eli/lta/2025/1757/pdf"}},{"role":"Statsminister","amount":"ca. 2,5 mio. kr./år","details":"Statsministeren får omkring 25 pct. mere end de øvrige ministre. Oven i kommer fri bil og tjenestebolig på Marienborg.","source":{"title":"Lov nr. 1757 af 29. december 2025 om ministres vederlag (retsinformation)","url":"https://www.retsinformation.dk/eli/lta/2025/1757/pdf"}},{"role":"Borgmester","amount":"ca. 1.384.000 kr./år (eksempel: Næstved Kommune, satser pr. 1. april 2025)","details":"Borgmestervederlaget fastsættes efter kommunens indbyggertal i vederlagsbekendtgørelsen (bekendtgørelse nr. 1325 af 13. november 2025, gældende fra 1. januar 2026).","source":{"title":"Kommunale vederlag til medlemmer af Næstved Byråd 2026","url":"https://backoffice.naestved.dk/media/iqzkpnrd/kommunale-vederlag-til-medlemmer-af-naestved-byraad-2026.pdf"}},{"role":"Almindeligt byrådsmedlem","amount":"ca. 89.000-107.000 kr./år fast vederlag (niveau 2025, afhængig af kommunens størrelse)","details":"Det faste vederlag er lavest i mindre kommuner og 107.178 kr. i kommuner med over 80.000 indbyggere. Udvalgs- og formandsposter får tillæg.","source":{"title":"Vederlagsbekendtgørelse (Sønderborg Kommune)","url":"https://sonderborgkommune.dk/sites/default/files/2025-11/Vederlagsbekendtg%C3%B8relsen.pdf"}},{"role":"Medlem af Europa-Parlamentet","amount":"ca. 11.255 EUR/md. brutto (grundløn)","details":"Nettoløn ca. 8.773 EUR/md. efter EU-skat. Samlet med godtgørelser ca. 18.000 EUR/md.","source":{"title":"Exclusive: The Left group wants to halve MEP salaries (Euronews, 7.10.2026)","url":"https://www.euronews.com/2026/10/07/exclusive-the-left-group-wants-to-halve-mep-salaries"}}],"howCandidatesAreChosen":"Folketinget har 175 mandater i Danmark. 135 af dem er kredsmandater, og de resterende 40 er tillægsmandater, som fordeles på landsplan efter partiernes samlede stemmer. Grønland og Færøerne har hver to mandater. Kandidaterne stiller op i en opstillingskreds eller en storkreds, og partierne laver en liste. Ved sideordnet opstilling står flere kandidater fra samme parti i samme kreds, og de personlige stemmer afgør, hvem der bliver valgt først. Man kan blive valgt uden at vinde sin kreds, hvis partiets samlede stemmetal giver mandat via tillægsmandaterne og listerækkefølgen.","typicalRoutes":[{"route":"Ungdomsparti, så Folketinget","details":"Den mest brugte vej. Mette Frederiksen var aktiv i DSU og blev valgt til Folketinget i 2001 som 24-årig. Alex Vanopslagh var landsformand for Liberal Alliances Ungdom 2014-2016, kom i Københavns Borgerrepræsentation i 2018 og blev folketingsmedlem og politisk leder i 2019. Ungdomspartiet giver netværk, træning i at tale og en plads i køen, når kandidaterne skal findes."},{"route":"Byråd, så Folketinget","details":"Mange begynder lokalt, fordi et byrådsvalg kræver langt færre stemmer. Lars Løkke Rasmussen blev valgt til byrådet i Græsted-Gilleleje som 22-årig i 1986, kom i Folketinget i 1994 og var amtsborgmester 1998-2001. Jacob Mark (SF) blev valgt til Køge Byråd som 18-årig og kom i Folketinget i 2015."},{"route":"Europa-Parlamentet som springbræt","details":"Et EP-valg er ét stort landsdækkende personvalg, så en kendt profil kan samle stemmer fra hele landet. Morten Messerschmidt kom i Folketinget i 2005 som 24-årig, blev valgt til Europa-Parlamentet i 2009 og fik i 2014 465.758 personlige stemmer, det højeste antal ved et dansk valg. Anders Vistisen sad i Europa-Parlamentet for DF og sidder nu i folketingsgruppen."},{"route":"Kendt udefra, hentet ind","details":"Partier henter også folk, som allerede har et publikum: journalister, debattører, erhvervsfolk og profiler fra sociale medier. Det er den hurtigste vej, men den kræver, at du har noget, partiet mangler: et publikum, en sag du ejer, eller en vælgergruppe de ikke selv kan nå."}],"youngestMFs":[{"name":"Sofie Therese Svendsen","party":"K (Det Konservative Folkeparti)","age":"23 på valgdagen 24.3.2026","howTheyGotIn":"Valgt ved folketingsvalget 24. marts 2026. Hun er det yngste medlem af det nye Folketing."},{"name":"Ellen Emilie Mindegaard-Müllertz","party":"M (Moderaterne)","age":"24","howTheyGotIn":"Valgt ved folketingsvalget 24. marts 2026. Hun er det yngste medlem for Moderaterne."}],"socialMediaRoutes":[{"name":"Alex Vanopslagh (LA)","note":"Hans valgkamp på TikTok ved folketingsvalget 2022 er dokumenteret i et speciale fra Aalborg Universitet, der beskriver en parasocial kontakt med vælgerne. Et speciale fra RUC finder, at partiets TikTok-tilstedeværelse ikke påvirkede valgresultatet væsentligt.","source":{"title":"Politiktok: et casestudie af Liberal Alliances anvendelse af TikTok under folketingsvalget 2022 (Aalborg Universitet)","url":"https://projekter.aau.dk/politiktok-et-casestudie-af-liberal-alliances-anvendelse-af-tiktok-under-folketingsvalget-2022-708917a0.html"}},{"name":"Dansk Folkeparti","note":"Ifølge en forsker fra Københavns Universitet har DF overtaget en meme-præget stil fra Liberal Alliance og har haft en udtalt opmærksomhedsstrategi på sociale medier.","source":{"title":"Forsker: virale memes og populærkultur er blevet våben i moderne politisk kommunikation (Altinget)","url":"https://www.altinget.dk/kultur/artikel/forsker-virale-memes-og-populaerkultur-er-blevet-vaaben-i-moderne-politisk-kommunikation"}},{"name":"Mette Frederiksen (S) og Troels Lund Poulsen (V)","note":"Ifølge en Altinget-analyse af partiledernes sociale medier har Mette Frederiksen 932.000 følgere samlet på Facebook og Instagram, mens Troels Lund Poulsen har 33.000. Det viser rækkeviddeforskellen mellem to partiledere, men ikke gennembruddet.","source":{"title":"Some-ekspert: Mette Frederiksen har en atombombe, mens Troels Lund har en slangebøsse (Altinget)","url":"https://www.altinget.dk/artikel/some-ekspert-mette-frederiksen-har-en-atombombe-mens-troels-lund-har-en-slangeboesse-det-kan-afgoere-valget"}}],"upcomingElections":[{"what":"Folketingsvalg","when":"senest 2030-03-24","note":"Næste folketingsvalg skal holdes senest fire år efter valget den 24. marts 2026."},{"what":"Kommunal- og regionsvalg","when":"2029-11-20","note":"Holdes tredje tirsdag i november hvert fjerde år. Næste valg er 20. november 2029."},{"what":"Europa-Parlamentsvalg","when":"juni 2029","note":"Vælger medlemmer til Europa-Parlamentet for de næste fem år."}],"otherPoliticalJobs":[{"job":"Særlig rådgiver","pay":"Lønnen er ikke oplyst i de kilder, der er brugt.","note":"Ansat af en minister uden for den faste embedsstand."},{"job":"Politisk konsulent eller pressemedarbejder i et parti","pay":"Lønnen er ikke oplyst i de kilder, der er brugt.","note":"Ansættelser i partisekretariater og folketingsgrupper."},{"job":"Byrådsmedlem","pay":"ca. 89.000-107.000 kr./år fast vederlag (niveau 2025)","note":"Typisk et deltidshverv ved siden af et andet job."},{"job":"Borgmester","pay":"ca. 1.384.000 kr./år i Næstved Kommune (satser pr. 1. april 2025)","note":"Eftervederlag: i København udbetales 1,5 gange sidste månedsvederlag for hvert påbegyndt år som borgmester (kommunens notat)."},{"job":"Medlem af Europa-Parlamentet","pay":"ca. 11.255 EUR/md. brutto (grundløn)","note":"Kræver en europæisk valgliste. Valget afholdes hvert femte år."}],"contentLandscape":{"summary":"I en Altinget-debatartikel skriver en erhvervsforsker, at sociale medier har overtaget den politiske kommunikation. Han peger på, at unge førstegangsvælgere primært eksponeres for én politiker og én platform.","rules":"EU's forordning 2024/900 om gennemsigtighed i politisk reklame (TTPA) gælder fra oktober 2025. Politisk reklame skal mærkes, og gennemsigtighedsmeddelelsen skal oplyse afsender, udgifter og finansiering. Målretning med personfølsomme data er forbudt i politisk reklame, og målretning med andre personoplysninger kræver et særskilt samtykke (recitalerne 56, 57, 77, 78 og 82).","sources":[{"title":"Forordning (EU) 2024/900 om gennemsigtighed i politisk reklame (EUR-Lex)","url":"https://eur-lex.europa.eu/eli/reg/2024/900/oj"},{"title":"Erhvervsforsker: De sociale medier har endeligt overtaget vores demokrati (Altinget)","url":"https://www.altinget.dk/uddannelse/artikel/erhvervsforsker-de-sociale-medier-har-endeligt-overtaget-vores-demokrati"}]},"honestOdds":"Der var 933 opstillede kandidater ved folketingsvalget den 24. marts 2026, og 175 mandater blev fordelt. Det svarer til ca. 19 pct. af kandidaterne. Kvinder udgjorde 39,4 pct. af kandidaterne, som var 46,3 år i gennemsnit, og 65 kandidater (7,0 pct.) var under 25 år.","sources":[{"title":"Folketingskandidaterne er i gennemsnit 46 år (Danmarks Statistik, 18.3.2026)","url":"https://www.dst.dk/da/presse/Pressemeddelelser/2026/2026-03-18-folketingskandidaterne-er-i-gennemsnit-46-aar"},{"title":"Kandidatstatistik 2026 (Danmarks Statistik)","url":"https://www.dst.dk/valg/Valg2546527/other/Kandidatstatistik%202026.pdf"},{"title":"Politikerne stiger i løn og falder i pension: Her er aftalens detaljer (Altinget, 27.5.2025)","url":"https://www.altinget.dk/embedsvaerk/artikel/politikerne-stiger-i-loen-og-falder-i-pension-her-er-aftalens-detaljer"}]},"hooks":[{"name":"Anklagen","how":"Start midt i konflikten. Første sætning er en indvending, ikke en præsentation.","ex":"»Du stemmer DF. Så du synes ikke, jeg hører til her?«"},{"name":"Tallet","how":"Ét rigtigt tal, sagt langsomt, vist på skærmen med kilde. Aldrig et tal du ikke kan dokumentere.","ex":"»93 for. 15 imod. Her er de to partier, der stemte nej til billigere bøger.«"},{"name":"Indrømmelsen","how":"Giv modparten et point i første sætning. Det er sjældent i politik, så folk bliver hængende.","ex":"»Jeg er DF'er, og her er den ene ting, venstrefløjen har ret i.«"},{"name":"Rollebyttet","how":"Lad DF'eren forsvare modpartens holdning i 20 sekunder, og omvendt. Viser at du kan stoffet.","ex":"»30 sekunder: DF'eren skal overbevise dig om at stemme Enhedslisten.«"},{"name":"Ja eller nej","how":"Stil et spørgsmål politikere plejer at tale udenom, og kræv ét ord først, forklaring bagefter.","ex":"»Ja eller nej: Skal en læge fra Syrien, der har boet her i 10 år, kunne sendes hjem?«"},{"name":"Myten","how":"Lov et antal punkter. Folk bliver for at se den sidste.","ex":"»3 ting folk tror om DF, som er forkerte. Og 1 der passer.«"},{"name":"Væddemålet","how":"Sæt et ur på skærmen. En tidsfrist holder seeren til det sidste sekund.","ex":"»Giv mig 40 sekunder til at ændre din mening om remigration.«"},{"name":"Nyheden","how":"Tag noget fra Folketinget i denne uge, og forklar det før medierne har tygget det færdigt.","ex":"»I torsdags stemte Folketinget om det her. Du har ikke hørt om det. Det burde du.«"},{"name":"Dilemmaet","how":"Tving et valg mellem to gode ting. Kommentarfeltet gør resten.","ex":"»Du har én milliard. Ældreplejen eller forsvaret. Vælg.«"},{"name":"Den personlige","how":"Én sætning om dig selv, som ingen anden kan kopiere. Brug den, når emnet rammer dit eget liv.","ex":"»Jeg er selv vokset op mellem to kulturer. Derfor irriterer den her debat mig.«"}],"moves":[{"name":"Stålmand først","text":"Gengiv modpartens stærkeste argument, så modparten selv ville nikke. Først derefter svarer du. Det gør dit svar mere troværdigt og gør det svært at kalde videoen ensidig."},{"name":"Skel skarpt","text":"Sig forskellen højt: kritik af kriminalitet og parallelsamfund er ikke kritik af mennesker med udenlandsk baggrund. Gå efter handlinger, aldrig ophav. Det er dit særkende, og det er det, de fleste videoer i genren mangler."},{"name":"Ét tal, én kilde","text":"Hold dig til ét tal pr. video. Vis det på skærmen, og læg kilden øverst i kommentarfeltet. Et tal du ikke kan linke til, bruger du ikke."},{"name":"Lad personen vinde","text":"Lad den vilkårlige person lande pointen i hver tredje eller fjerde video. Så tror seerne på, at kampen er ærlig, de gange DF'eren vinder."},{"name":"Slut med et spørgsmål","text":"Afslut med et åbent spørgsmål til seeren i stedet for en konklusion. Kommentarer er det, der løfter videoen i algoritmen."},{"name":"Samme ramme hver gang","text":"Samme åbning, samme to pladser, samme farve på hver rolle. Efter fem videoer genkender folk formatet på et halvt sekund."},{"name":"Brug primærkilden","text":"Afstemninger og forslag fra Folketinget er offentlige. »Sådan stemte de« slår »jeg har hørt at« hver gang, og du finder det under I dag."},{"name":"Svar med video","text":"Tag den skarpeste kritiske kommentar og svar på den i en ny video. Det giver gratis idéer og viser, at du tør tage imod."},{"name":"Sig hvad du ikke ved","text":"»Det ved jeg ikke, det finder jeg ud af til næste video« er bedre end at gætte. Det gør dig sværere at angribe og giver en grund til at følge med."}],"checklist":["Hvert tal er tjekket mod kilden i dag, ikke efter hukommelsen.","Kilden står i caption eller øverste kommentar.","Ingen opdigtede citater fra rigtige politikere. Citér ordret, eller skriv »partiet mener«.","Det fremgår, at »DF'eren« er en rolle, og at du ikke taler på partiets vegne.","Kritikken går på handlinger og politik, ikke på grupper af mennesker.","Modpartens bedste argument er med, ikke en stråmand.","AI-genereret billede, stemme eller video er mærket som AI.","Klip fra tv eller Folketinget har kildeangivelse."],"format":{"name":"Vilkårlig person mod DF'er","pitch":"To roller, ét emne, under et minut. Den vilkårlige person stiller det spørgsmål, seeren selv sidder med. DF'eren svarer, som en dygtig DF'er faktisk ville svare. Du spiller begge.","rules":["0–3 sek.: hooket. Altid en indvending eller et tal.","3–20 sek.: personens bedste argument, uafbrudt.","20–45 sek.: DF'erens svar med ét tal og én kilde.","45–55 sek.: ét modspørgsmål hver vej.","Sidste 5 sek.: spørgsmål til seeren."]},"plan":[{"when":"Uge 1–4","title":"Lær stoffet og find formatet","items":["Kan forklare hvert af de 12 partier på 30 sekunder (tjek dig selv under Træn).","Følg I dag-siden hver morgen i 10 minutter.","Optag de første 5 videoer. De skal ikke være gode, de skal være lavet."]},{"when":"Måned 2–3","title":"Fast rytme","items":["3 videoer om ugen, samme ramme hver gang.","Vælg 2 emner, du vil være den bedste til. Udlændinge og ét til.","Meld dig ind i ungdomspartiet og mød op til to lokale møder. Sig ja til den første opgave, du bliver tilbudt."]},{"when":"Måned 4–6","title":"Bliv set af de rigtige","items":["Skriv to debatindlæg til en lokalavis eller Altinget.","Tilbyd at lave video for en lokal kandidat eller et byrådsmedlem.","Tag til landsmøde. Det er dér, folk i partiet lærer hinanden at kende."]},{"when":"Måned 7–12","title":"Tag en post","items":["Stil op til en bestyrelsespost i lokalforeningen eller ungdomspartiet.","Følg ét folketingsudvalg tæt, og bliv den der ved mest om det.","Sigt efter en plads på kandidatlisten til kommunalvalget i november 2029."]}]};
